import { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Bot, X, Send, Sparkles, Loader2 } from 'lucide-react';
import { callAI } from '../lib/ai';
import { cn } from '../lib/utils';
import { useLanguageContext } from '../lib/i18n/language-context';

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

export function AIAssistant({ context }: { context?: string }) {
  const { t } = useLanguageContext();
  const [open, setOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setMessages([
      {
        role: 'assistant',
        content: t(
          'ai.welcomeMessage',
          "Hi! I'm RealtyNow's AI assistant. Ask me about properties, listings, or real estate in general.",
        ),
      },
    ]);
  }, [t]);

  const quickPrompts = [
    t('ai.quickPrompt1', 'Find 3BHK apartments under 1 crore in Mumbai'),
    t('ai.quickPrompt2', 'What documents do I need to list a property?'),
    t('ai.quickPrompt3', 'Suggest areas in Hyderabad for renting under 30k'),
  ];

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, loading]);

  useEffect(() => {
    const handleOpen = (e: Event) => {
      setOpen(true);
      const customEv = e as CustomEvent<{ prompt?: string }>;
      if (customEv.detail?.prompt) {
        send(customEv.detail.prompt);
      }
    };
    window.addEventListener('open-ai-assistant', handleOpen);
    return () => window.removeEventListener('open-ai-assistant', handleOpen);
  }, []);

  const send = async (text: string) => {
    if (!text.trim() || loading) return;
    const userMsg: Message = { role: 'user', content: text };
    setMessages((m) => [...m, userMsg]);
    setInput('');
    setLoading(true);
    try {
      const result = await callAI('chat', { message: text, context });
      setMessages((m) => [...m, { role: 'assistant', content: result }]);
    } catch (err) {
      setMessages((m) => [
        ...m,
        {
          role: 'assistant',
          content: `${t('ai.errorMessage', "Sorry, I couldn't process that.")} ${err instanceof Error ? err.message : t('ai.tryAgain', 'Try again.')}`,
        },
      ]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="fixed bottom-6 right-6 z-40 flex items-center gap-2 rounded-full bg-navy-700 px-4 py-3 text-sm font-bold text-white shadow-cardHover hover:bg-navy-800 transition"
      >
        <Sparkles className="h-5 w-5 text-gold-400" /> {t('ai.assistant', 'AI Assistant')}
      </button>

      <AnimatePresence>
        {open && (
          <>
            <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
            <motion.div
              initial={{ opacity: 0, y: 20, scale: 0.96 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 20, scale: 0.96 }}
              transition={{ duration: 0.2 }}
              className="fixed bottom-6 right-6 z-50 flex h-[520px] w-[calc(100vw-3rem)] max-w-sm flex-col overflow-hidden rounded-2xl border border-navy-100 bg-white shadow-cardHover"
            >
              <div className="flex items-center justify-between border-b border-navy-100 bg-navy-700 px-4 py-3 text-white">
                <div className="flex items-center gap-2">
                  <div className="grid h-8 w-8 place-items-center rounded-lg bg-white/10">
                    <Bot className="h-5 w-5 text-gold-400" />
                  </div>
                  <div>
                    <p className="font-display text-sm font-semibold">{t('ai.title', 'RealtyNow AI')}</p>
                    <p className="text-xs text-navy-300">{t('ai.online', 'Online')}</p>
                  </div>
                </div>
                <button onClick={() => setOpen(false)} className="rounded-lg p-1.5 hover:bg-white/10">
                  <X className="h-5 w-5" />
                </button>
              </div>

              <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-3 bg-navy-50/30">
                {messages.map((m, i) => (
                  <div key={i} className={cn('flex', m.role === 'user' ? 'justify-end' : 'justify-start')}>
                    <div
                      className={cn(
                        'max-w-[80%] rounded-2xl px-3.5 py-2.5 text-sm',
                        m.role === 'user'
                          ? 'bg-navy-700 text-white rounded-br-sm'
                          : 'bg-white border border-navy-100 text-navy-800 rounded-bl-sm',
                      )}
                    >
                      {m.content}
                    </div>
                  </div>
                ))}
                {loading && (
                  <div className="flex justify-start">
                    <div className="rounded-2xl rounded-bl-sm bg-white border border-navy-100 px-3.5 py-2.5">
                      <Loader2 className="h-4 w-4 animate-spin text-navy-500" />
                    </div>
                  </div>
                )}
                {messages.length === 1 && !loading && (
                  <div className="space-y-2 pt-2">
                    <p className="text-xs text-navy-400">{t('ai.tryAsking', 'Try asking:')}</p>
                    {quickPrompts.map((p) => (
                      <button
                        key={p}
                        onClick={() => send(p)}
                        className="block w-full rounded-lg border border-navy-100 bg-white px-3 py-2 text-left text-xs text-navy-700 hover:border-navy-300 hover:bg-navy-50"
                      >
                        {p}
                      </button>
                    ))}
                  </div>
                )}
              </div>

              <form
                onSubmit={(e) => {
                  e.preventDefault();
                  send(input);
                }}
                className="flex items-center gap-2 border-t border-navy-100 bg-white p-3"
              >
                <input
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={t('ai.placeholder', 'Type your message...')}
                  className="flex-1 rounded-lg border border-navy-200 px-3 py-2 text-sm focus:border-navy-400 focus:outline-none focus:ring-2 focus:ring-navy-200"
                />
                <button
                  type="submit"
                  disabled={loading || !input.trim()}
                  className="grid h-9 w-9 place-items-center rounded-lg bg-navy-700 text-white hover:bg-navy-800 disabled:opacity-50 cursor-pointer"
                >
                  <Send className="h-4 w-4" />
                </button>
              </form>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </>
  );
}

import { useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X, LogOut, ChevronRight, Home, Globe } from 'lucide-react';
import { useAuth } from '../lib/auth';
import { useLanguageContext } from '../lib/i18n/language-context';
import { LanguageSelectorModal } from './language-selector-modal';
import { Avatar } from './ui';
import { Logo } from './logo';
import { NotificationBell } from './notification-bell';
import { cn, relativeTime } from '../lib/utils';

export interface NavSection {
  heading?: string;
  items: { to: string; label: string; icon: React.ComponentType<{ className?: string }>; end?: boolean }[];
}

export function DashboardLayout({
  children,
  sections,
  title,
  badge,
}: {
  children: React.ReactNode;
  sections: NavSection[];
  title: string;
  badge?: string;
}) {
  const { profile, signOut } = useAuth();
  const { currentLanguage, t } = useLanguageContext();
  const location = useLocation();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [langModalOpen, setLangModalOpen] = useState(false);

  const isActive = (to: string, end?: boolean) => (end ? location.pathname === to : location.pathname.startsWith(to));

  return (
    <div className="min-h-screen bg-navy-50/40">
      {/* Sidebar (desktop) */}
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-64 border-r border-navy-100 bg-white lg:flex flex-col">
        <div className="flex h-16 items-center gap-2 border-b border-navy-100 px-5">
          <Logo to="/" size={160} />
        </div>
        <nav className="flex-1 overflow-y-auto px-3 py-4">
          {sections.map((section, i) => (
            <div key={i} className="mb-4">
              {section.heading && (
                <p className="px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-navy-400">
                  {t(section.heading, section.heading)}
                </p>
              )}
              <div className="space-y-0.5">
                {section.items.map((item) => (
                  <Link
                    key={item.to}
                    to={item.to}
                    className={cn('sidebar-link', isActive(item.to, item.end) && 'sidebar-link-active')}
                  >
                    <item.icon className="h-4 w-4" />
                    {t(item.label, item.label)}
                  </Link>
                ))}
              </div>
            </div>
          ))}
        </nav>
        <div className="border-t border-navy-100 p-3">
          <button
            onClick={() => {
              signOut();
              navigate('/');
            }}
            className="sidebar-link w-full text-left text-error-600 hover:bg-error-50"
          >
            <LogOut className="h-4 w-4" /> {t('common.logout', 'Sign out')}
          </button>
        </div>
      </aside>

      {/* Mobile sidebar */}
      <AnimatePresence>
        {open && (
          <>
            <div className="fixed inset-0 z-40 bg-navy-950/40 lg:hidden" onClick={() => setOpen(false)} />
            <motion.aside
              initial={{ x: -280 }}
              animate={{ x: 0 }}
              exit={{ x: -280 }}
              transition={{ type: 'tween', duration: 0.2 }}
              className="fixed inset-y-0 left-0 z-50 w-64 bg-white lg:hidden flex flex-col"
            >
              <div className="flex h-16 items-center justify-between border-b border-navy-100 px-5">
                <Logo to="/" size={160} />
                <button onClick={() => setOpen(false)}>
                  <X className="h-5 w-5 text-navy-500" />
                </button>
              </div>
              <nav className="flex-1 overflow-y-auto px-3 py-4">
                {sections.map((section, i) => (
                  <div key={i} className="mb-4">
                    {section.heading && (
                      <p className="px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-navy-400">
                        {t(section.heading, section.heading)}
                      </p>
                    )}
                    <div className="space-y-0.5">
                      {section.items.map((item) => (
                        <Link
                          key={item.to}
                          to={item.to}
                          onClick={() => setOpen(false)}
                          className={cn('sidebar-link', isActive(item.to, item.end) && 'sidebar-link-active')}
                        >
                          <item.icon className="h-4 w-4" /> {t(item.label, item.label)}
                        </Link>
                      ))}
                    </div>
                  </div>
                ))}
              </nav>
            </motion.aside>
          </>
        )}
      </AnimatePresence>

      {/* Main content */}
      <div className="lg:pl-64">
        <header className="sticky top-0 z-20 flex h-16 items-center gap-3 border-b border-navy-100 bg-white/90 px-4 backdrop-blur sm:px-6">
          <button
            onClick={() => setOpen(true)}
            className="lg:hidden grid place-items-center rounded-lg p-2 text-navy-700 hover:bg-navy-50"
          >
            <Menu className="h-5 w-5" />
          </button>
          <div className="flex-1">
            <h1 className="font-display text-lg font-semibold text-navy-900 flex items-center gap-2">
              {t(title, title)}
              {badge && <span className="badge bg-gold-100 text-gold-700">{badge}</span>}
            </h1>
          </div>
          <button
            onClick={() => setLangModalOpen(true)}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl border border-slate-200 hover:border-red-500 bg-white hover:bg-red-50/50 text-slate-800 font-bold text-xs transition-all shadow-sm cursor-pointer"
            title={t('common.selectLanguage', 'Select Language')}
          >
            <Globe className="h-4 w-4 text-red-600" />
            <span className="hidden sm:inline">{currentLanguage.nativeName}</span>
            <span className="sm:hidden uppercase font-mono">{currentLanguage.code}</span>
          </button>
          <Link
            to="/"
            className="hidden sm:grid place-items-center rounded-lg p-2 text-navy-500 hover:bg-navy-50"
            aria-label="Home"
          >
            <Home className="h-5 w-5" />
          </Link>
          <NotificationBell />
          <Link
            to={
              profile?.role === 'admin'
                ? '/admin/settings'
                : profile?.role === 'agent'
                  ? '/agent/settings'
                  : '/portal/settings'
            }
          >
            <Avatar
              name={`${profile?.first_name ?? ''} ${profile?.last_name ?? ''}`.trim() || (profile?.email ?? 'U')}
              src={profile?.avatar_url}
              size={34}
            />
          </Link>
        </header>

        <LanguageSelectorModal isOpen={langModalOpen} onClose={() => setLangModalOpen(false)} />

        <div className="px-4 py-6 sm:px-6 lg:px-8">
          <motion.div initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
            {children}
          </motion.div>
        </div>
      </div>
    </div>
  );
}

export function PageHeader({
  title,
  subtitle,
  action,
}: {
  title: string;
  subtitle?: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
      <div>
        <h2 className="font-display text-2xl font-bold text-navy-900">{title}</h2>
        {subtitle && <p className="mt-1 text-sm text-navy-500">{subtitle}</p>}
      </div>
      {action}
    </div>
  );
}

export function StatCard({
  label,
  value,
  icon,
  trend,
  accent = 'navy',
  to,
  onClick,
}: {
  label: string;
  value: string | number;
  icon: React.ReactNode;
  trend?: string;
  accent?: 'navy' | 'gold' | 'success' | 'error';
  to?: string;
  onClick?: () => void;
}) {
  const accentBg = {
    navy: 'bg-navy-50 text-navy-700',
    gold: 'bg-gold-50 text-gold-600',
    success: 'bg-success-50 text-success-600',
    error: 'bg-error-50 text-error-600',
  }[accent];

  const content = (
    <div className="flex items-start justify-between">
      <div>
        <p className="text-sm text-navy-500 font-medium group-hover:text-navy-700 transition-colors">{label}</p>
        <p className="mt-2 font-display text-2xl font-bold text-navy-900">{value}</p>
        {trend && <p className="mt-1 text-xs text-success-600 font-semibold">{trend}</p>}
      </div>
      <div
        className={cn(
          'grid h-11 w-11 place-items-center rounded-xl transition-transform group-hover:scale-110',
          accentBg,
        )}
      >
        {icon}
      </div>
    </div>
  );

  if (to) {
    return (
      <Link
        to={to}
        className="card p-5 block group hover:shadow-cardHover hover:border-navy-300 transition-all cursor-pointer"
      >
        {content}
      </Link>
    );
  }

  if (onClick) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 6 }}
        animate={{ opacity: 1, y: 0 }}
        onClick={onClick}
        className="card p-5 block group hover:shadow-cardHover hover:border-navy-300 transition-all cursor-pointer"
      >
        {content}
      </motion.div>
    );
  }

  return (
    <motion.div initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} className="card p-5">
      {content}
    </motion.div>
  );
}

import { useState, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Search, ArrowUpDown, Trash2, Calendar, LayoutList, LayoutGrid } from 'lucide-react';
import { Button, Input, Skeleton, Badge, Select } from './ui';
import { cn, formatDate, formatPrice } from '../lib/utils';
import { StatusBadge } from './property-card';

export interface Column<T> {
  key: string;
  header: string;
  render?: (row: T) => React.ReactNode;
  sortable?: boolean;
  className?: string;
}

export type DatePreset = 'all' | 'today' | 'yesterday' | '7days' | '30days' | 'this_month' | 'custom';

export function isDateInPreset(
  dateStr: string | null | undefined,
  preset: DatePreset,
  customStart?: string,
  customEnd?: string,
): boolean {
  if (preset === 'all') return true;
  if (!dateStr) return true;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return true;

  const now = new Date();
  const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const todayEnd = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);

  if (preset === 'today') {
    return d >= todayStart && d <= todayEnd;
  }
  if (preset === 'yesterday') {
    const yestStart = new Date(todayStart);
    yestStart.setDate(yestStart.getDate() - 1);
    const yestEnd = new Date(todayEnd);
    yestEnd.setDate(yestEnd.getDate() - 1);
    return d >= yestStart && d <= yestEnd;
  }
  if (preset === '7days') {
    const start7 = new Date(todayStart);
    start7.setDate(start7.getDate() - 7);
    return d >= start7 && d <= todayEnd;
  }
  if (preset === '30days') {
    const start30 = new Date(todayStart);
    start30.setDate(start30.getDate() - 30);
    return d >= start30 && d <= todayEnd;
  }
  if (preset === 'this_month') {
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
    return d >= monthStart && d <= todayEnd;
  }
  if (preset === 'custom') {
    if (customStart) {
      const cs = new Date(customStart);
      if (d < cs) return false;
    }
    if (customEnd) {
      const ce = new Date(customEnd);
      ce.setHours(23, 59, 59, 999);
      if (d > ce) return false;
    }
    return true;
  }
  return true;
}

interface DataTableProps<T> {
  columns: Column<T>[];
  rows: T[];
  loading?: boolean;
  searchable?: boolean;
  searchPlaceholder?: string;
  searchKeys?: (keyof T)[];
  dateKey?: keyof T;
  pageSize?: number;
  onRowClick?: (row: T) => void;
  selectedIds?: Set<string>;
  onToggleSelect?: (id: string) => void;
  onSelectAll?: (ids: string[]) => void;
  emptyState?: React.ReactNode;
  getRowId: (row: T) => string;
  cardRender?: (row: T) => React.ReactNode;
  defaultView?: 'table' | 'grid';
}

export function DataTable<T>({
  columns,
  rows,
  loading,
  searchable = true,
  searchKeys,
  dateKey = 'created_at' as keyof T,
  pageSize = 10,
  onRowClick,
  selectedIds,
  onToggleSelect,
  onSelectAll,
  emptyState,
  getRowId,
  cardRender,
  defaultView = 'table',
}: DataTableProps<T>) {
  const [query, setQuery] = useState('');
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');
  const [page, setPage] = useState(1);
  const [viewMode, setViewMode] = useState<'table' | 'grid'>(defaultView);
  const [datePreset, setDatePreset] = useState<DatePreset>('all');
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');

  // 1. Date Filtering
  const dateFiltered = useMemo(() => {
    return rows.filter((r) => {
      const val = (r as Record<string, unknown>)[dateKey as string] as string | null | undefined;
      return isDateInPreset(val, datePreset, customStart, customEnd);
    });
  }, [rows, dateKey, datePreset, customStart, customEnd]);

  // 2. Search Query Filtering
  const filtered = useMemo(() => {
    if (!query) return dateFiltered;
    const q = query.toLowerCase();
    if (!searchKeys || searchKeys.length === 0) {
      return dateFiltered.filter((r) =>
        Object.values(r as Record<string, unknown>).some((val) =>
          String(val ?? '')
            .toLowerCase()
            .includes(q),
        ),
      );
    }
    return dateFiltered.filter((r) =>
      searchKeys.some((k) =>
        String((r as Record<string, unknown>)[k as string] ?? '')
          .toLowerCase()
          .includes(q),
      ),
    );
  }, [dateFiltered, query, searchKeys]);

  // 3. Sorting
  const sorted = useMemo(() => {
    if (!sortKey) return filtered;
    const col = columns.find((c) => c.key === sortKey);
    if (!col?.sortable) return filtered;
    return [...filtered].sort((a, b) => {
      const av = (a as Record<string, unknown>)[sortKey];
      const bv = (b as Record<string, unknown>)[sortKey];
      if (av == null) return 1;
      if (bv == null) return -1;
      if (typeof av === 'number' && typeof bv === 'number') return sortDir === 'asc' ? av - bv : bv - av;
      return sortDir === 'asc' ? String(av).localeCompare(String(bv)) : String(bv).localeCompare(String(av));
    });
  }, [filtered, sortKey, sortDir, columns]);

  const totalPages = Math.max(1, Math.ceil(sorted.length / pageSize));
  const current = Math.min(page, totalPages);
  const pageRows = sorted.slice((current - 1) * pageSize, current * pageSize);
  const allOnPageSelected = selectedIds && pageRows.length > 0 && pageRows.every((r) => selectedIds.has(getRowId(r)));

  const toggleSort = (key: string) => {
    if (sortKey === key) setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  return (
    <div className="space-y-4">
      {/* Top Filter & Toolbar Bar */}
      <div className="flex flex-wrap items-center justify-between gap-3 bg-white p-3 rounded-2xl border border-navy-100 shadow-sm">
        {/* Left: Search Bar */}
        {searchable && (
          <div className="relative min-w-[220px] flex-1 max-w-sm">
            <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-navy-400" />
            <Input
              placeholder="Search records…"
              value={query}
              onChange={(e) => {
                setQuery(e.target.value);
                setPage(1);
              }}
              className="pl-9 text-sm"
            />
          </div>
        )}

        {/* Middle: Advanced Date Filter */}
        <div className="flex flex-wrap items-center gap-2">
          <div className="flex items-center gap-1.5 text-xs font-semibold text-navy-600 bg-navy-50 px-2.5 py-1.5 rounded-xl border border-navy-100">
            <Calendar className="h-4 w-4 text-navy-500" />
            <span>Date:</span>
            <select
              value={datePreset}
              onChange={(e) => {
                setDatePreset(e.target.value as DatePreset);
                setPage(1);
              }}
              className="bg-transparent font-bold text-navy-900 focus:outline-none cursor-pointer pr-1"
            >
              <option value="all">All Time</option>
              <option value="today">Today</option>
              <option value="yesterday">Yesterday</option>
              <option value="7days">Last 7 Days</option>
              <option value="30days">Last 30 Days</option>
              <option value="this_month">This Month</option>
              <option value="custom">Custom Range</option>
            </select>
          </div>

          {datePreset === 'custom' && (
            <div className="flex items-center gap-1.5 bg-navy-50 p-1 rounded-xl border border-navy-100 text-xs">
              <input
                type="date"
                value={customStart}
                onChange={(e) => setCustomStart(e.target.value)}
                className="bg-white border border-navy-200 rounded px-2 py-1 text-xs"
              />
              <span className="text-navy-400">to</span>
              <input
                type="date"
                value={customEnd}
                onChange={(e) => setCustomEnd(e.target.value)}
                className="bg-white border border-navy-200 rounded px-2 py-1 text-xs"
              />
            </div>
          )}
        </div>

        {/* Right: View Toggle Switcher (Table vs Card Grid) */}
        <div className="flex items-center gap-1 bg-navy-100/70 p-1 rounded-xl">
          <button
            onClick={() => setViewMode('table')}
            className={cn(
              'flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-all',
              viewMode === 'table' ? 'bg-white text-navy-900 shadow-sm' : 'text-navy-600 hover:text-navy-900',
            )}
          >
            <LayoutList className="h-4 w-4" />
            <span>Table</span>
          </button>
          <button
            onClick={() => setViewMode('grid')}
            className={cn(
              'flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-all',
              viewMode === 'grid' ? 'bg-white text-navy-900 shadow-sm' : 'text-navy-600 hover:text-navy-900',
            )}
          >
            <LayoutGrid className="h-4 w-4" />
            <span>Cards</span>
          </button>
        </div>
      </div>

      {/* Selected Items Counter */}
      {selectedIds && selectedIds.size > 0 && (
        <div className="text-xs font-bold text-navy-600 px-1">{selectedIds.size} item(s) selected</div>
      )}

      {/* View Mode: Table View */}
      {viewMode === 'table' ? (
        <div className="card overflow-hidden">
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-navy-100">
              <thead className="bg-navy-50/60">
                <tr>
                  {onToggleSelect && (
                    <th className="table-cell-head w-10">
                      <input
                        type="checkbox"
                        checked={!!allOnPageSelected}
                        onChange={() => onSelectAll?.(pageRows.map(getRowId))}
                        className="rounded border-navy-300 text-navy-700 focus:ring-navy-400"
                      />
                    </th>
                  )}
                  {columns.map((col) => (
                    <th key={col.key} className={cn('table-cell-head', col.className)}>
                      {col.sortable ? (
                        <button
                          onClick={() => toggleSort(col.key)}
                          className="inline-flex items-center gap-1 hover:text-navy-700"
                        >
                          {col.header}
                          <ArrowUpDown className="h-3 w-3" />
                        </button>
                      ) : (
                        col.header
                      )}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-navy-50">
                {loading ? (
                  Array.from({ length: 6 }).map((_, i) => (
                    <tr key={i}>
                      {onToggleSelect && (
                        <td className="table-cell">
                          <Skeleton className="h-4 w-4" />
                        </td>
                      )}
                      {columns.map((c) => (
                        <td key={c.key} className="table-cell">
                          <Skeleton />
                        </td>
                      ))}
                    </tr>
                  ))
                ) : pageRows.length === 0 ? (
                  <tr>
                    <td colSpan={columns.length + (onToggleSelect ? 1 : 0)} className="p-0">
                      {emptyState ?? (
                        <div className="px-4 py-10 text-center text-sm text-navy-400">No records found.</div>
                      )}
                    </td>
                  </tr>
                ) : (
                  pageRows.map((row) => {
                    const id = getRowId(row);
                    const selected = selectedIds?.has(id);
                    return (
                      <tr
                        key={id}
                        onClick={() => onRowClick?.(row)}
                        className={cn(
                          'transition hover:bg-navy-50/40',
                          onRowClick && 'cursor-pointer',
                          selected && 'bg-navy-50/60',
                        )}
                      >
                        {onToggleSelect && (
                          <td className="table-cell" onClick={(e) => e.stopPropagation()}>
                            <input
                              type="checkbox"
                              checked={!!selected}
                              onChange={() => onToggleSelect(id)}
                              className="rounded border-navy-300 text-navy-700 focus:ring-navy-400"
                            />
                          </td>
                        )}
                        {columns.map((col) => (
                          <td key={col.key} className={cn('table-cell', col.className)}>
                            {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.key] ?? '—')}
                          </td>
                        ))}
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        /* View Mode: Card Grid View */
        <div>
          {loading ? (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {Array.from({ length: 6 }).map((_, i) => (
                <Skeleton key={i} className="h-64 rounded-2xl" />
              ))}
            </div>
          ) : pageRows.length === 0 ? (
            <div className="card p-10 text-center text-sm text-navy-400">{emptyState ?? 'No records found.'}</div>
          ) : (
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {pageRows.map((row) => {
                const id = getRowId(row);
                if (cardRender) return <div key={id}>{cardRender(row)}</div>;

                // Fallback default card render for any object (Properties, Applications, Users)
                const rec = row as Record<string, any>;
                const img = rec.images?.[0] ?? 'https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg';
                const title = rec.title ?? rec.name ?? rec.full_name ?? `Item #${id.slice(0, 6)}`;
                const status = rec.status ?? rec.approval_status ?? 'active';

                return (
                  <div
                    key={id}
                    onClick={() => onRowClick?.(row)}
                    className="card p-4 hover:shadow-cardHover transition-all flex flex-col justify-between cursor-pointer group"
                  >
                    <div>
                      <div className="relative aspect-video rounded-xl overflow-hidden mb-3 bg-navy-100">
                        <img
                          src={img}
                          alt=""
                          className="h-full w-full object-cover group-hover:scale-105 transition-transform"
                        />
                        <div className="absolute top-2 right-2">
                          <StatusBadge status={status} />
                        </div>
                      </div>
                      <h4 className="font-bold text-navy-900 text-base line-clamp-1">{title}</h4>
                      {rec.locality_name && (
                        <p className="text-xs text-navy-500 mt-0.5">
                          {rec.locality_name}, {rec.city_name}
                        </p>
                      )}
                      {rec.price != null && (
                        <p className="font-bold text-navy-900 mt-2 text-lg">{formatPrice(rec.price, rec.purpose)}</p>
                      )}
                      {rec.created_at && <p className="text-xs text-navy-400 mt-1">{formatDate(rec.created_at)}</p>}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* Pagination Footer */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between border-t border-navy-100 px-4 py-3 text-sm bg-white rounded-2xl border">
          <span className="text-navy-500">
            Showing {(current - 1) * pageSize + 1}–{Math.min(current * pageSize, sorted.length)} of {sorted.length}
          </span>
          <div className="flex items-center gap-1">
            <Button variant="ghost" size="sm" disabled={current === 1} onClick={() => setPage((p) => p - 1)}>
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <span className="px-2 font-semibold text-navy-700">
              {current} / {totalPages}
            </span>
            <Button variant="ghost" size="sm" disabled={current === totalPages} onClick={() => setPage((p) => p + 1)}>
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

export function BulkActionsBar({
