import React, { useState, useMemo } from 'react';
import {
  Search,
  Filter,
  Download,
  ArrowUpDown,
  ChevronLeft,
  ChevronRight,
  FileSpreadsheet,
  FileText,
  Printer,
  CheckSquare,
  Square,
  MoreVertical,
  Plus,
  Edit,
  Trash2,
  Eye,
  RefreshCw,
} from 'lucide-react';
import { useLanguageContext } from '../../lib/i18n/language-context';

export interface ColumnDef<T> {
  field: keyof T | string;
  headerName: string;
  width?: string | number;
  sortable?: boolean;
  filterable?: boolean;
  render?: (row: T) => React.ReactNode;
}

interface EnterpriseDataGridProps<T extends { id: string | number }> {
  title?: string;
  subtitle?: string;
  columns: ColumnDef<T>[];
  data: T[];
  loading?: boolean;
  onRowClick?: (row: T) => void;
  onAdd?: () => void;
  onEdit?: (row: T) => void;
  onDelete?: (row: T) => void;
  onExportExcel?: () => void;
  onExportPdf?: () => void;
  onExportCsv?: () => void;
}

export function EnterpriseDataGrid<T extends { id: string | number }>({
  title,
  subtitle,
  columns,
  data,
  loading = false,
  onRowClick,
  onAdd,
  onEdit,
  onDelete,
}: EnterpriseDataGridProps<T>) {
  const { t } = useLanguageContext();
  const [searchQuery, setSearchQuery] = useState('');
  const [sortField, setSortField] = useState<string | null>(null);
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');
  const [selectedIds, setSelectedIds] = useState<Set<string | number>>(new Set());
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [filterColumn, setFilterColumn] = useState<string>('all');

  // Filter & Search Logic
  const filteredData = useMemo(() => {
    return data.filter((row) => {
      if (!searchQuery.trim()) return true;
      const q = searchQuery.toLowerCase();
      if (filterColumn !== 'all') {
        const val = String((row as Record<string, unknown>)[filterColumn] ?? '').toLowerCase();
        return val.includes(q);
      }
      return Object.values(row as Record<string, unknown>).some((val) =>
        String(val ?? '')
          .toLowerCase()
          .includes(q),
      );
    });
  }, [data, searchQuery, filterColumn]);

  // Sort Logic
  const sortedData = useMemo(() => {
    if (!sortField) return filteredData;
    return [...filteredData].sort((a, b) => {
      const valA = (a as Record<string, unknown>)[sortField];
      const valB = (b as Record<string, unknown>)[sortField];
      if (valA == null) return 1;
      if (valB == null) return -1;
      if (valA < valB) return sortDirection === 'asc' ? -1 : 1;
      if (valA > valB) return sortDirection === 'asc' ? 1 : -1;
      return 0;
    });
  }, [filteredData, sortField, sortDirection]);

  // Pagination Logic
  const totalPages = Math.ceil(sortedData.length / pageSize) || 1;
  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return sortedData.slice(start, start + pageSize);
  }, [sortedData, currentPage, pageSize]);

  const handleSort = (field: string) => {
    if (sortField === field) {
      if (sortDirection === 'asc') setSortDirection('desc');
      else {
        setSortField(null);
        setSortDirection('asc');
      }
    } else {
      setSortField(field);
      setSortDirection('asc');
    }
  };

  const toggleSelectAll = () => {
    if (selectedIds.size === paginatedData.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(paginatedData.map((d) => d.id)));
    }
  };

  const toggleSelectRow = (id: string | number, e: React.MouseEvent) => {
    e.stopPropagation();
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  // CSV Export
  const exportCSV = () => {
    if (!data.length) return;
    const headers = columns.map((c) => c.headerName).join(',');
    const rows = data.map((row) =>
      columns.map((c) => `"${String((row as Record<string, unknown>)[c.field as string] ?? '').replace(/"/g, '""')}"`).join(','),
    );
    const csvContent = 'data:text/csv;charset=utf-8,' + [headers, ...rows].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `${title || 'export'}_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="w-full bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden font-sans">
      {/* Grid Top Action Bar */}
      <div className="p-5 bg-gradient-to-r from-slate-900 via-slate-800 to-slate-900 text-white flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          {title && <h2 className="text-xl font-bold tracking-tight text-white flex items-center gap-2">{title}</h2>}
          {subtitle && <p className="text-xs text-slate-300 mt-0.5">{subtitle}</p>}
        </div>

        {/* Global Action Tools */}
        <div className="flex flex-wrap items-center gap-2">
          {/* Search bar */}
          <div className="relative min-w-[220px]">
            <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setCurrentPage(1);
              }}
              placeholder={t('common.search', 'Search records...')}
              className="w-full pl-9 pr-3 py-1.5 text-xs bg-slate-800/80 border border-slate-700 rounded-xl text-white placeholder-slate-400 focus:outline-none focus:border-red-500 focus:ring-1 focus:ring-red-500 transition-all"
            />
          </div>

          {/* Filter Dropdown */}
          <select
            value={filterColumn}
            onChange={(e) => setFilterColumn(e.target.value)}
            className="px-3 py-1.5 text-xs bg-slate-800/80 border border-slate-700 rounded-xl text-slate-200 focus:outline-none focus:border-red-500 cursor-pointer"
          >
            <option value="all">{t('blog.allCategories', 'All Columns')}</option>
            {columns.map((c) => (
              <option key={String(c.field)} value={String(c.field)}>
                {c.headerName}
              </option>
            ))}
          </select>

          {/* Export Buttons */}
          <button
            type="button"
            onClick={exportCSV}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 border border-slate-700 text-xs font-semibold text-slate-200 transition-all cursor-pointer"
            title="Export CSV"
          >
            <FileSpreadsheet className="w-3.5 h-3.5 text-green-400" />
            <span>CSV</span>
          </button>

          <button
            type="button"
            onClick={exportCSV}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 border border-slate-700 text-xs font-semibold text-slate-200 transition-all cursor-pointer"
            title="Export Excel"
          >
            <Download className="w-3.5 h-3.5 text-emerald-400" />
            <span>Excel</span>
          </button>

          <button
            type="button"
            onClick={() => window.print()}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-slate-800 hover:bg-slate-700 border border-slate-700 text-xs font-semibold text-slate-200 transition-all cursor-pointer"
            title="Print / PDF"
          >
            <Printer className="w-3.5 h-3.5 text-red-400" />
            <span>Print</span>
          </button>

          {onAdd && (
            <button
              type="button"
              onClick={onAdd}
              className="flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl bg-red-600 hover:bg-red-700 text-xs font-bold text-white shadow-md shadow-red-600/30 transition-all cursor-pointer"
            >
              <Plus className="w-4 h-4" />
              <span>{t('common.add', 'Add New')}</span>
            </button>
          )}
        </div>
      </div>

      {/* Main Table */}
      <div className="overflow-x-auto min-h-[300px]">
        <table className="w-full border-collapse text-left text-xs">
          <thead>
            <tr className="bg-slate-100/80 border-b border-slate-200 text-slate-700 font-bold uppercase tracking-wider sticky top-0 z-10">
              <th className="p-3.5 w-10 text-center">
                <button
                  type="button"
                  onClick={toggleSelectAll}
                  className="text-slate-400 hover:text-slate-700 cursor-pointer"
                >
                  {selectedIds.size === paginatedData.length && paginatedData.length > 0 ? (
                    <CheckSquare className="w-4 h-4 text-red-600" />
                  ) : (
                    <Square className="w-4 h-4" />
                  )}
                </button>
              </th>
              {columns.map((col) => (
                <th
                  key={String(col.field)}
                  style={{ width: col.width }}
                  className="p-3.5 whitespace-nowrap border-r border-slate-200/60 last:border-r-0 select-none"
                >
                  <div
                    className={`flex items-center justify-between gap-1.5 ${col.sortable !== false ? 'cursor-pointer hover:text-red-600' : ''}`}
                    onClick={() => col.sortable !== false && handleSort(String(col.field))}
                  >
                    <span>{col.headerName}</span>
                    {col.sortable !== false && (
                      <ArrowUpDown
                        className={`w-3.5 h-3.5 opacity-40 ${sortField === col.field ? 'opacity-100 text-red-600' : ''}`}
                      />
                    )}
                  </div>
                </th>
              ))}
              <th className="p-3.5 text-right whitespace-nowrap w-24">{t('portal.actions', 'Actions')}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 text-slate-800">
            {loading ? (
              Array.from({ length: 5 }).map((_, idx) => (
                <tr key={idx} className="animate-pulse">
                  <td className="p-3.5 text-center">
                    <div className="h-4 w-4 bg-slate-200 rounded mx-auto" />
                  </td>
                  {columns.map((c, i) => (
                    <td key={i} className="p-3.5">
                      <div className="h-4 bg-slate-100 rounded w-3/4" />
                    </td>
                  ))}
                  <td className="p-3.5 text-right">
                    <div className="h-4 w-12 bg-slate-100 rounded ml-auto" />
                  </td>
                </tr>
              ))
            ) : paginatedData.length === 0 ? (
              <tr>
                <td colSpan={columns.length + 2} className="p-12 text-center text-slate-400">
                  {t('search.noResults', 'No matching records found')}
                </td>
              </tr>
            ) : (
              paginatedData.map((row) => {
                const isSelected = selectedIds.has(row.id);
                return (
                  <tr
                    key={String(row.id)}
                    onClick={() => onRowClick && onRowClick(row)}
                    className={`transition-colors border-b border-slate-100 ${
                      isSelected ? 'bg-red-50/50 hover:bg-red-50' : 'hover:bg-slate-50/80'
                    } ${onRowClick ? 'cursor-pointer' : ''}`}
                  >
                    <td className="p-3.5 text-center" onClick={(e) => e.stopPropagation()}>
                      <button
                        type="button"
                        onClick={(e) => toggleSelectRow(row.id, e)}
                        className="text-slate-400 hover:text-slate-700 cursor-pointer"
                      >
                        {isSelected ? <CheckSquare className="w-4 h-4 text-red-600" /> : <Square className="w-4 h-4" />}
                      </button>
                    </td>
                    {columns.map((col) => (
                      <td
                        key={String(col.field)}
                        className="p-3.5 border-r border-slate-100 last:border-r-0 whitespace-nowrap font-medium"
                      >
                        {col.render ? col.render(row) : String((row as Record<string, unknown>)[col.field as string] ?? '—')}
                      </td>
                    ))}
                    <td className="p-3.5 text-right whitespace-nowrap" onClick={(e) => e.stopPropagation()}>
                      <div className="flex items-center justify-end gap-1">
                        {onEdit && (
                          <button
                            type="button"
                            onClick={() => onEdit(row)}
                            className="p-1.5 rounded-lg text-slate-500 hover:text-red-600 hover:bg-slate-100 transition-colors cursor-pointer"
                            title="Edit"
                          >
                            <Edit className="w-3.5 h-3.5" />
                          </button>
                        )}
                        {onDelete && (
                          <button
                            type="button"
                            onClick={() => onDelete(row)}
                            className="p-1.5 rounded-lg text-slate-500 hover:text-red-600 hover:bg-red-50 transition-colors cursor-pointer"
                            title="Delete"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination Footer */}
      <div className="px-5 py-3.5 bg-slate-50 border-t border-slate-200 flex flex-col sm:flex-row items-center justify-between gap-3 text-xs text-slate-600">
        <div className="flex items-center gap-2">
          <span>
            {t('common.showing', 'Showing')}{' '}
            <strong className="font-bold text-slate-900">
              {sortedData.length > 0 ? (currentPage - 1) * pageSize + 1 : 0}
            </strong>{' '}
            {t('common.to', 'to')}{' '}
            <strong className="font-bold text-slate-900">{Math.min(currentPage * pageSize, sortedData.length)}</strong>{' '}
            {t('common.of', 'of')} <strong className="font-bold text-slate-900">{sortedData.length}</strong>{' '}
            {t('common.entries', 'entries')}
          </span>
          {selectedIds.size > 0 && (
            <span className="ml-2 font-semibold text-red-600 bg-red-50 px-2 py-0.5 rounded-md border border-red-100">
              ({selectedIds.size} {t('compare.selectedCount', 'selected')})
            </span>
          )}
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-1.5">
            <span>Rows:</span>
            <select
              value={pageSize}
              onChange={(e) => {
                setPageSize(Number(e.target.value));
                setCurrentPage(1);
              }}
              className="bg-white border border-slate-200 rounded-lg px-2 py-1 text-xs font-semibold focus:outline-none focus:border-red-600"
            >
              <option value={10}>10</option>
              <option value={25}>25</option>
              <option value={50}>50</option>
              <option value={100}>100</option>
            </select>
          </div>

          <div className="flex items-center gap-1">
            <button
              type="button"
              disabled={currentPage === 1}
              onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
              className="p-1.5 rounded-lg border border-slate-200 bg-white hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed transition-all cursor-pointer"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="px-3 font-semibold text-slate-800">
              {currentPage} / {totalPages}
            </span>
            <button
              type="button"
              disabled={currentPage === totalPages}
              onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
              className="p-1.5 rounded-lg border border-slate-200 bg-white hover:bg-slate-100 disabled:opacity-40 disabled:cursor-not-allowed transition-all cursor-pointer"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useLanguageContext } from '../../lib/i18n/language-context';
import {
  Folder,
  File,
  FileText,
  Image as ImageIcon,
  Video,
  Upload,
  Download,
  Trash2,
  Search,
  Eye,
  Plus,
} from 'lucide-react';
import { uploadFile } from '../../lib/storage';

export interface FileItem {
  id: string;
  name: string;
  size: string;
  type: 'image' | 'pdf' | 'document' | 'video';
  url: string;
  folder: string;
  updatedAt: string;
}

interface EnterpriseFileManagerProps {
  files?: FileItem[];
  bucketName?: string;
  onFileUploaded?: (url: string, name: string) => void;
}

export function EnterpriseFileManager({
  files = [],
  bucketName = 'property-images',
  onFileUploaded,
}: EnterpriseFileManagerProps) {
  const { t } = useLanguageContext();
  const [activeFolder, setActiveFolder] = useState<string>('All Files');
  const [uploading, setUploading] = useState(false);
  const [search, setSearch] = useState('');

  const folders = ['All Files', 'Property Images', 'Floor Plans', 'Brochures', 'Legal Agreements'];

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    const { url, error } = await uploadFile(bucketName as any, file);
    setUploading(false);
    if (!error && url && onFileUploaded) {
      onFileUploaded(url, file.name);
    }
  };

  return (
    <div className="w-full bg-white rounded-3xl border border-slate-200 shadow-md p-6 font-sans">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-5 mb-5 border-b border-slate-100">
        <div>
          <h2 className="text-lg font-bold text-slate-900 leading-tight">Enterprise Storage File Manager</h2>
          <p className="text-xs text-slate-500">Manage property images, brochures, tax documents & sale agreements.</p>
        </div>

        <div className="flex items-center gap-3">
          <label className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 active:scale-95 text-white font-bold text-xs rounded-xl shadow-md shadow-red-600/30 cursor-pointer transition-all">
            <Upload className="w-4 h-4" />
            <span>{uploading ? 'Uploading...' : 'Upload Asset'}</span>
            <input type="file" onChange={handleUpload} className="hidden" />
          </label>
        </div>
      </div>

      {/* Main Grid: Folder Sidebar + File Grid */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {/* Folders */}
        <div className="space-y-1">
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider px-3 mb-2">Folders</p>
          {folders.map((f) => (
            <button
              key={f}
              type="button"
              onClick={() => setActiveFolder(f)}
              className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-xs font-bold transition-all text-left cursor-pointer ${
                activeFolder === f ? 'bg-red-50 text-red-600 border border-red-100' : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              <Folder className="w-4 h-4" />
              <span>{f}</span>
            </button>
          ))}
        </div>

        {/* Files Area */}
        <div className="md:col-span-3">
          <div className="flex items-center justify-between gap-4 mb-4">
            <div className="relative flex-1">
              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
              <input
                type="text"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search files..."
                className="w-full pl-9 pr-3 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-xl text-slate-900 focus:outline-none focus:border-red-600"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {files.length === 0 ? (
              <div className="col-span-full py-12 text-center text-slate-400 text-xs">
                No files uploaded in {activeFolder} yet.
              </div>
            ) : (
              files.map((file) => (
                <div
                  key={file.id}
                  className="p-3.5 rounded-2xl border border-slate-200 hover:border-red-200 bg-white hover:shadow-md transition-all flex flex-col justify-between"
                >
                  <div className="flex items-start gap-3">
                    <div className="w-10 h-10 rounded-xl bg-slate-100 text-slate-700 flex items-center justify-center font-bold">
                      {file.type === 'image' ? (
                        <ImageIcon className="w-5 h-5 text-red-500" />
                      ) : (
                        <FileText className="w-5 h-5 text-blue-500" />
                      )}
                    </div>
                    <div className="overflow-hidden">
                      <p className="text-xs font-bold text-slate-900 truncate">{file.name}</p>
                      <p className="text-[10px] text-slate-400 mt-0.5">
                        {file.size} • {file.updatedAt}
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center justify-between pt-3 mt-3 border-t border-slate-100">
                    <a
                      href={file.url}
                      target="_blank"
                      rel="noreferrer"
                      className="text-xs font-bold text-red-600 hover:underline flex items-center gap-1"
                    >
                      <Eye className="w-3.5 h-3.5" /> Preview
                    </a>
                    <a href={file.url} download className="p-1 rounded text-slate-400 hover:text-slate-700">
                      <Download className="w-3.5 h-3.5" />
                    </a>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useLanguageContext } from '../../lib/i18n/language-context';
import {
  User,
  Phone,
  Mail,
  Calendar,
  DollarSign,
  Plus,
  MoreHorizontal,
  MessageSquare,
  ShieldCheck,
  MapPin,
} from 'lucide-react';

export interface KanbanLeadCard {
  id: string;
  title: string;
  customerName: string;
  phone: string;
  email: string;
  budget: string;
  locality?: string;
  stage: 'new' | 'contacted' | 'site_visit' | 'negotiation' | 'booking' | 'sold' | 'closed';
  priority?: 'High' | 'Medium' | 'Low';
  assignedAgent?: string;
  createdAt: string;
}

const STAGES: { key: KanbanLeadCard['stage']; label: string; color: string; bg: string }[] = [
  { key: 'new', label: 'New Lead', color: 'border-blue-500 text-blue-700', bg: 'bg-blue-50' },
  { key: 'contacted', label: 'Contacted', color: 'border-indigo-500 text-indigo-700', bg: 'bg-indigo-50' },
  { key: 'site_visit', label: 'Site Visit Scheduled', color: 'border-amber-500 text-amber-700', bg: 'bg-amber-50' },
  { key: 'negotiation', label: 'Negotiation', color: 'border-purple-500 text-purple-700', bg: 'bg-purple-50' },
  { key: 'booking', label: 'Booking In Progress', color: 'border-emerald-500 text-emerald-700', bg: 'bg-emerald-50' },
  { key: 'sold', label: 'Sold / Closed', color: 'border-green-600 text-green-800', bg: 'bg-green-100' },
  { key: 'closed', label: 'Archived', color: 'border-slate-400 text-slate-600', bg: 'bg-slate-100' },
];

interface EnterpriseKanbanProps {
  initialLeads: KanbanLeadCard[];
  onLeadStageChange?: (leadId: string, newStage: KanbanLeadCard['stage']) => void;
  onAddLead?: () => void;
}

export function EnterpriseKanban({ initialLeads, onLeadStageChange, onAddLead }: EnterpriseKanbanProps) {
  const { t } = useLanguageContext();
  const [leads, setLeads] = useState<KanbanLeadCard[]>(initialLeads);
  const [draggedId, setDraggedId] = useState<string | null>(null);

  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedId(id);
    e.dataTransfer.setData('text/plain', id);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (e: React.DragEvent, stageKey: KanbanLeadCard['stage']) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('text/plain') || draggedId;
    if (!id) return;

    setLeads((prev) => prev.map((lead) => (lead.id === id ? { ...lead, stage: stageKey } : lead)));

    if (onLeadStageChange) {
      onLeadStageChange(id, stageKey);
    }
    setDraggedId(null);
  };

  return (
    <div className="w-full bg-slate-900 rounded-3xl p-6 shadow-xl border border-slate-800 text-white font-sans overflow-x-auto">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 pb-4 border-b border-slate-800">
        <div>
          <h2 className="text-xl font-bold text-white flex items-center gap-2">
            <ShieldCheck className="w-6 h-6 text-red-500" />
            CRM Lead Pipeline (Kanban Board)
          </h2>
          <p className="text-xs text-slate-400 mt-1">
            Drag and drop customer leads across sales pipeline stages in real-time.
          </p>
        </div>
        {onAddLead && (
          <button
            type="button"
            onClick={onAddLead}
            className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 active:scale-95 text-white font-bold text-xs rounded-xl shadow-lg shadow-red-600/30 transition-all cursor-pointer"
          >
            <Plus className="w-4 h-4" />
            <span>Add Lead</span>
          </button>
        )}
      </div>

      {/* Board Columns */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7 gap-4 min-w-[1200px]">
        {STAGES.map((stage) => {
          const stageLeads = leads.filter((l) => l.stage === stage.key);
          return (
            <div
              key={stage.key}
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, stage.key)}
              className="flex flex-col bg-slate-800/60 border border-slate-700/60 rounded-2xl p-3 min-h-[450px]"
            >
              {/* Stage Header */}
              <div
                className={`p-2.5 rounded-xl border-l-4 ${stage.color} ${stage.bg} flex items-center justify-between mb-3 shadow-sm`}
              >
                <span className="font-bold text-xs text-slate-900">{stage.label}</span>
                <span className="text-[11px] font-extrabold px-2 py-0.5 rounded-full bg-white text-slate-900 shadow-xs">
                  {stageLeads.length}
                </span>
              </div>

              {/* Cards Container */}
              <div className="flex-1 space-y-3 overflow-y-auto max-h-[600px] pr-1">
                {stageLeads.length === 0 ? (
                  <div className="h-32 border-2 border-dashed border-slate-700/60 rounded-xl flex items-center justify-center text-slate-500 text-xs font-semibold">
                    Drop lead here
                  </div>
                ) : (
                  stageLeads.map((lead) => (
                    <div
                      key={lead.id}
                      draggable
                      onDragStart={(e) => handleDragStart(e, lead.id)}
                      className="bg-slate-900 border border-slate-700 hover:border-red-500 rounded-xl p-3.5 shadow-md hover:shadow-lg transition-all cursor-grab active:cursor-grabbing group"
                    >
                      <div className="flex items-start justify-between gap-2 mb-2">
                        <span className="text-xs font-bold text-white group-hover:text-red-400 transition-colors line-clamp-1">
                          {lead.title}
                        </span>
                        {lead.priority && (
                          <span
                            className={`text-[10px] font-black px-1.5 py-0.5 rounded uppercase ${
                              lead.priority === 'High'
                                ? 'bg-red-500/20 text-red-400 border border-red-500/30'
                                : lead.priority === 'Medium'
                                  ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30'
                                  : 'bg-slate-700 text-slate-300'
                            }`}
                          >
                            {lead.priority}
                          </span>
                        )}
                      </div>

                      <div className="space-y-1 text-xs text-slate-400 border-t border-slate-800/80 pt-2">
                        <div className="flex items-center gap-1.5 font-medium text-slate-200">
                          <User className="w-3.5 h-3.5 text-red-500" />
                          <span>{lead.customerName}</span>
                        </div>
                        <div className="flex items-center gap-1.5 text-[11px]">
                          <Phone className="w-3 h-3 text-slate-500" />
                          <span>{lead.phone}</span>
                        </div>
                        {lead.locality && (
                          <div className="flex items-center gap-1.5 text-[11px]">
                            <MapPin className="w-3 h-3 text-slate-500" />
                            <span>{lead.locality}</span>
                          </div>
                        )}
                        <div className="flex items-center justify-between text-[11px] font-bold text-emerald-400 pt-1">
                          <span>₹ {lead.budget}</span>
                          <span className="text-[10px] text-slate-500 font-normal">{lead.createdAt}</span>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useLanguageContext } from '../../lib/i18n/language-context';
import {
  Bold,
  Italic,
  Underline,
  List,
  ListOrdered,
  Link as LinkIcon,
  Image as ImageIcon,
  Code,
  Sparkles,
  Eye,
} from 'lucide-react';

interface EnterpriseRichTextEditorProps {
  value: string;
  onChange: (val: string) => void;
  label?: string;
  placeholder?: string;
}

export function EnterpriseRichTextEditor({ value, onChange, label, placeholder }: EnterpriseRichTextEditorProps) {
  const { t } = useLanguageContext();
  const [htmlMode, setHtmlMode] = useState(false);

  const applyTag = (tag: string) => {
    if (tag === 'b') onChange(`<b>${value}</b>`);
    else if (tag === 'i') onChange(`<i>${value}</i>`);
    else if (tag === 'u') onChange(`<u>${value}</u>`);
    else if (tag === 'h2') onChange(`<h2>${value}</h2>`);
    else if (tag === 'ul') onChange(`<ul>\n  <li>${value || 'List item'}</li>\n</ul>`);
  };

  return (
    <div className="w-full font-sans">
      {label && <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">{label}</label>}

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden focus-within:border-red-600 transition-all">
        {/* Editor Toolbar */}
        <div className="px-4 py-2.5 bg-slate-50 border-b border-slate-200 flex flex-wrap items-center justify-between gap-2">
          <div className="flex items-center gap-1">
            <button
              type="button"
              onClick={() => applyTag('b')}
              className="p-1.5 rounded-lg hover:bg-slate-200 text-slate-700 font-bold transition-colors cursor-pointer"
              title="Bold"
            >
              <Bold className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={() => applyTag('i')}
              className="p-1.5 rounded-lg hover:bg-slate-200 text-slate-700 italic transition-colors cursor-pointer"
              title="Italic"
            >
              <Italic className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={() => applyTag('u')}
              className="p-1.5 rounded-lg hover:bg-slate-200 text-slate-700 underline transition-colors cursor-pointer"
              title="Underline"
            >
              <Underline className="w-4 h-4" />
            </button>
            <div className="w-px h-5 bg-slate-300 mx-1" />
            <button
              type="button"
              onClick={() => applyTag('ul')}
              className="p-1.5 rounded-lg hover:bg-slate-200 text-slate-700 transition-colors cursor-pointer"
              title="Bullet List"
            >
              <List className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={() => applyTag('h2')}
              className="p-1.5 rounded-lg hover:bg-slate-200 text-slate-700 font-bold text-xs transition-colors cursor-pointer"
              title="Heading 2"
            >
              H2
            </button>
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setHtmlMode(!htmlMode)}
              className={`flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-bold transition-all cursor-pointer ${
                htmlMode ? 'bg-slate-900 text-white' : 'bg-slate-200 text-slate-700 hover:bg-slate-300'
              }`}
            >
              <Code className="w-3.5 h-3.5" />
              <span>{htmlMode ? 'Visual Mode' : 'HTML Mode'}</span>
            </button>
          </div>
        </div>

        {/* Editor Area */}
        <textarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder || 'Write content using rich editor...'}
          className="w-full p-4 min-h-[160px] max-h-[350px] text-sm text-slate-900 focus:outline-none placeholder-slate-400 font-normal resize-y"
        />
      </div>
    </div>
  );
}

import React, { useState } from 'react';
