import { useState, useRef, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Bell, Check, X } from 'lucide-react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import { useAuth } from '../lib/auth';
import { useRealtimeNotifications } from '../lib/realtime';
import { cn, relativeTime } from '../lib/utils';

export function NotificationBell() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [open, setOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const { unreadCount, refetchFlag, setUnreadCount } = useRealtimeNotifications(user?.id);

  const { data: notifications } = useQuery({
    queryKey: ['notifications', user?.id, refetchFlag],
    queryFn: async () => {
      if (!user) return [];
      const { data } = await supabase
        .from('notifications')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(20);
      return data ?? [];
    },
    enabled: !!user,
  });

  const markReadMutation = useMutation({
    mutationFn: async (id: string) => {
      await supabase.from('notifications').update({ read_at: new Date().toISOString() }).eq('id', id);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notifications'] });
      setUnreadCount((c) => Math.max(0, c - 1));
    },
  });

  const markAllReadMutation = useMutation({
    mutationFn: async () => {
      if (!user) return;
      await supabase
        .from('notifications')
        .update({ read_at: new Date().toISOString() })
        .eq('user_id', user.id)
        .is('read_at', null);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notifications'] });
      setUnreadCount(0);
    },
  });

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  const handleNotifClick = (notif: { id: string; link: string | null; read_at: string | null }) => {
    if (!notif.read_at) markReadMutation.mutate(notif.id);
    if (notif.link) navigate(notif.link);
    setOpen(false);
  };

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        onClick={() => setOpen((o) => !o)}
        className="relative grid place-items-center rounded-lg p-2 text-navy-500 transition hover:bg-navy-50 hover:text-navy-700"
        aria-label="Notifications"
      >
        <Bell className="h-5 w-5" />
        {unreadCount > 0 && (
          <span className="absolute right-1 top-1 grid h-4 min-w-4 place-items-center rounded-full bg-gold-400 px-1 text-[10px] font-bold text-white">
            {unreadCount > 9 ? '9+' : unreadCount}
          </span>
        )}
      </button>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: 8, scale: 0.96 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 8, scale: 0.96 }}
            transition={{ duration: 0.15 }}
            className="absolute right-0 top-12 z-50 w-80 sm:w-96 overflow-hidden rounded-xl border border-navy-100 bg-white shadow-cardHover"
          >
            <div className="flex items-center justify-between border-b border-navy-100 px-4 py-3">
              <p className="font-display text-sm font-semibold text-navy-900">Notifications</p>
              {unreadCount > 0 && (
                <button
                  onClick={() => markAllReadMutation.mutate()}
                  className="text-xs font-medium text-navy-700 hover:text-navy-900"
                >
                  Mark all read
                </button>
              )}
            </div>

            <div className="max-h-96 overflow-y-auto">
              {notifications && notifications.length > 0 ? (
                notifications.map((notif) => (
                  <button
                    key={notif.id}
                    onClick={() => handleNotifClick(notif)}
                    className={cn(
                      'flex w-full gap-3 border-b border-navy-50 px-4 py-3 text-left transition hover:bg-navy-50',
                      !notif.read_at && 'bg-gold-50/40',
                    )}
                  >
                    <div
                      className={cn(
                        'mt-1.5 h-2 w-2 shrink-0 rounded-full',
                        !notif.read_at ? 'bg-gold-400' : 'bg-transparent',
                      )}
                    />
                    <div className="min-w-0 flex-1">
                      <p className="text-sm font-semibold text-navy-900">{notif.title}</p>
                      <p className="mt-0.5 text-xs text-navy-600 line-clamp-2">{notif.body}</p>
                      <p className="mt-1 text-[11px] text-navy-400">{relativeTime(notif.created_at)}</p>
                    </div>
                  </button>
                ))
              ) : (
                <div className="px-4 py-10 text-center">
                  <Bell className="mx-auto h-8 w-8 text-navy-200" />
                  <p className="mt-2 text-sm text-navy-500">No notifications yet</p>
                </div>
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { supabase } from '../../lib/supabase';
import { Button } from '../ui';
import { useToast } from '../toast';

// Extend Window object for Razorpay
declare global {
  interface Window {
    Razorpay: any;
  }
}

interface RazorpayCheckoutProps {
  packageId: string;
  billingCycle: 'monthly' | 'yearly';
  buttonText?: string;
  className?: string;
  onSuccess?: (paymentId: string) => void;
  onError?: (error: any) => void;
  disabled?: boolean;
}

export function RazorpayCheckout({
  packageId,
  billingCycle,
  buttonText = 'Subscribe Now',
  className = '',
  onSuccess,
  onError,
  disabled = false,
}: RazorpayCheckoutProps) {
  const [loading, setLoading] = useState(false);
  const [isScriptLoaded, setIsScriptLoaded] = useState(false);
  const { addToast } = useToast();

  useEffect(() => {
    // Load Razorpay script
    const loadRazorpayScript = () => {
      if (window.Razorpay) {
        setIsScriptLoaded(true);
        return;
      }
      const script = document.createElement('script');
      script.src = 'https://checkout.razorpay.com/v1/checkout.js';
      script.onload = () => setIsScriptLoaded(true);
      script.onerror = () => {
        console.error('Failed to load Razorpay script');
        addToast('error', 'Payment gateway failed to load.');
      };
      document.body.appendChild(script);
    };

    loadRazorpayScript();
  }, [addToast]);

  const handlePayment = async () => {
    if (!isScriptLoaded) {
      addToast('info', 'Payment gateway is still loading...');
      return;
    }

    setLoading(true);

    try {
      // 1. Get current user session
      const { data: { session }, error: sessionError } = await supabase.auth.getSession();
      if (sessionError || !session) {
        throw new Error('You must be logged in to make a payment.');
      }

      // 2. Call Edge Function to create order
      const { data: orderData, error: orderError } = await supabase.functions.invoke('payment-gateway', {
        headers: {
          'x-action': 'create-order',
        },
        body: {
          package_id: packageId,
          billing_cycle: billingCycle,
          payment_type: 'upfront',
          discount_pct: 0
        },
      });

      if (orderError) throw orderError;
      if (!orderData || !orderData.success) {
        throw new Error(orderData?.error || 'Failed to initialize payment.');
      }

      const { razorpay_order_id, razorpay_key_id, amount, currency, payment_id } = orderData;

      // 3. Initialize Razorpay Checkout
      const options = {
        key: razorpay_key_id,
        amount: amount * 100, // amount in smallest currency unit (paise)
        currency: currency,
        name: 'RealtyNow Enterprise',
        description: `Subscription Payment`,
        image: '/logo.png', // Fallback to your site's logo
        order_id: razorpay_order_id,
        handler: async function (response: any) {
          try {
            // 4. Verify Payment with Edge Function
            const { data: verifyData, error: verifyError } = await supabase.functions.invoke('payment-gateway', {
              headers: {
                'x-action': 'verify-payment',
              },
              body: {
                payment_id: payment_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_order_id: response.razorpay_order_id,
                razorpay_signature: response.razorpay_signature
              },
            });

            if (verifyError) throw verifyError;
            if (!verifyData || !verifyData.success) {
              throw new Error(verifyData?.error || 'Payment verification failed.');
            }

            addToast('success', 'Payment successful!');
            if (onSuccess) onSuccess(payment_id);
          } catch (err: any) {
            console.error('Verification error:', err);
            addToast('error', err.message || 'Payment verification failed.');
            if (onError) onError(err);
          }
        },
        prefill: {
          name: session.user.user_metadata?.first_name || '',
          email: session.user.email,
        },
        theme: {
          color: '#1a365d', // primary-900 (navy)
        },
      };

      const razorpay = new window.Razorpay(options);
      razorpay.on('payment.failed', function (response: any) {
        console.error('Payment failed:', response.error);
        addToast('error', response.error.description);
        if (onError) onError(response.error);
      });

      razorpay.open();

    } catch (error: any) {
      console.error('Checkout error:', error);
      addToast('error', error.message || 'Something went wrong.');
      if (onError) onError(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Button
      onClick={handlePayment}
      disabled={disabled || loading || !isScriptLoaded}
      className={className}
    >
      {loading ? 'Processing...' : buttonText}
    </Button>
  );
}

