import { useQuery } from '@tanstack/react-query';
import { Link } from 'react-router-dom';
import { Calendar, MessageSquare, ShieldCheck, AlertCircle, Clock, Users, Building2 } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { useAuth } from '../lib/auth';
import { useLanguageContext } from '../lib/i18n/language-context';
import { Card, Button, Badge } from './ui';
import { formatDateTime } from '../lib/utils';
import { useRealtimeMulti } from '../lib/realtime';

export function RemindersWidget() {
  const { user, profile } = useAuth();
  const { t } = useLanguageContext();
  const realtimeTick = useRealtimeMulti(['appointments', 'enquiries', 'properties', 'profiles']);

  const { data: reminders, isLoading } = useQuery({
    queryKey: ['reminders', user?.id, profile?.role, realtimeTick],
    queryFn: async () => {
      if (!user || !profile) return [];
      const role = profile.role;
      const now = new Date().toISOString();
      let items: any[] = [];

      if (role === 'customer') {
        const { data: appts } = await supabase
          .from('appointments')
          .select('*, property:properties(title)')
          .eq('customer_id', user.id)
          .gte('scheduled_at', now)
          .order('scheduled_at', { ascending: true })
          .limit(3);

        if (appts) {
          appts.forEach((a) =>
            items.push({
              id: `appt-${a.id}`,
              title: `Upcoming Visit: ${Array.isArray(a.property) ? a.property[0]?.title : a.property?.title}`,
              subtitle: formatDateTime(a.scheduled_at),
              icon: Calendar,
              color: 'text-brand-600',
              bg: 'bg-brand-50',
              link: '/portal/enquiries',
            }),
          );
        }
      } else if (role === 'agent' || role === 'builder') {
        const { data: appts } = await supabase
          .from('appointments')
          .select('*, property:properties(title)')
          .eq('agent_id', user.id)
          .gte('scheduled_at', now)
          .order('scheduled_at', { ascending: true })
          .limit(3);

        if (appts) {
          appts.forEach((a) =>
            items.push({
              id: `appt-${a.id}`,
              title: `Host Visit: ${Array.isArray(a.property) ? a.property[0]?.title : a.property?.title}`,
              subtitle: formatDateTime(a.scheduled_at),
              icon: Calendar,
              color: 'text-brand-600',
              bg: 'bg-brand-50',
              link: `/${role}/appointments`,
            }),
          );
        }

        const { data: enquiries } = await supabase
          .from('enquiries')
          .select('*, property:properties(title)')
          .eq('agent_id', user.id)
          .eq('status', 'new')
          .limit(3);

        if (enquiries) {
          enquiries.forEach((e) =>
            items.push({
              id: `enq-${e.id}`,
              title: `New Enquiry on ${Array.isArray(e.property) ? e.property[0]?.title : e.property?.title}`,
              subtitle: 'Awaiting your response',
              icon: MessageSquare,
              color: 'text-gold-600',
              bg: 'bg-gold-50',
              link: `/${role}/leads`,
            }),
          );
        }
      } else if (role === 'admin') {
        const { data: pendingAgents } = await supabase
          .from('profiles')
          .select('*')
          .in('role', ['agent', 'builder'])
          .eq('role_status', 'pending')
          .limit(3);

        if (pendingAgents) {
          pendingAgents.forEach((p) =>
            items.push({
              id: `pend-${p.id}`,
              title: `Pending Application: ${p.first_name} ${p.last_name}`,
              subtitle: `${p.role} account waiting for approval`,
              icon: Users,
              color: 'text-error-600',
              bg: 'bg-error-50',
              link: `/admin/${p.role}-applications`,
            }),
          );
        }

        const { data: pendingProps } = await supabase
          .from('properties')
          .select('id, title')
          .eq('status', 'pending_verification')
          .limit(3);

        if (pendingProps) {
          pendingProps.forEach((p) =>
            items.push({
              id: `prop-${p.id}`,
              title: `Verify Property: ${p.title}`,
              subtitle: 'New listing submitted',
              icon: Building2,
              color: 'text-gold-600',
              bg: 'bg-gold-50',
              link: `/admin/approvals`,
            }),
          );
        }
      }

      return items;
    },
    enabled: !!user && !!profile,
  });

  return (
    <Card className="p-5">
      <div className="flex items-center justify-between mb-4">
        <h3 className="font-display font-semibold text-navy-900 flex items-center gap-2">
          <Clock className="h-5 w-5 text-brand-600" />
          {t('dashboard:reminders', 'Upcoming Reminders')}
        </h3>
        <Badge variant="info">{reminders?.length || 0}</Badge>
      </div>

      <div className="space-y-3">
        {isLoading ? (
          <div className="text-sm text-navy-400 py-2">Loading...</div>
        ) : reminders && reminders.length > 0 ? (
          reminders.map((r) => (
            <div
              key={r.id}
              className="flex items-start gap-3 rounded-lg border border-navy-100 p-3 hover:bg-navy-50 transition"
            >
              <div className={`mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-full ${r.bg} ${r.color}`}>
                <r.icon className="h-4 w-4" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-navy-900 truncate">{r.title}</p>
                <p className="text-xs text-navy-500 mt-0.5">{r.subtitle}</p>
              </div>
              <Link to={r.link}>
                <Button size="sm" variant="secondary" className="text-xs py-1 px-2 h-auto">
                  View
                </Button>
              </Link>
            </div>
          ))
        ) : (
          <div className="flex flex-col items-center justify-center py-6 text-center">
            <ShieldCheck className="h-8 w-8 text-navy-200 mb-2" />
            <p className="text-sm font-medium text-navy-900">All caught up!</p>
            <p className="text-xs text-navy-500 mt-1">You have no pending reminders.</p>
          </div>
        )}
      </div>
    </Card>
  );
}

import { useState, useCallback, createContext, useContext, type ReactNode } from 'react';

type ToastType = 'success' | 'error' | 'warning' | 'info';

interface Toast {
  id: string;
  type: ToastType;
  message: string;
}

interface ToastContextValue {
  toasts: Toast[];
  addToast: (type: ToastType, message: string) => void;
  removeToast: (id: string) => void;
}

const ToastContext = createContext<ToastContextValue | undefined>(undefined);

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const removeToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const addToast = useCallback(
    (type: ToastType, message: string) => {
      const id = crypto.randomUUID();
      setToasts((prev) => [...prev, { id, type, message }]);
      setTimeout(() => removeToast(id), 5000);
    },
    [removeToast],
  );

  return (
    <ToastContext.Provider value={{ toasts, addToast, removeToast }}>
      {children}
      <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2">
        {toasts.map((toast) => (
          <div
            key={toast.id}
            className={`px-4 py-3 rounded-lg shadow-lg text-sm font-medium max-w-sm animate-in slide-in-from-bottom-2 bg-green-600 text-white`}
          >
            <div className="flex items-center justify-between gap-3">
              <span>{toast.message}</span>
              <button
                onClick={() => removeToast(toast.id)}
                className="opacity-70 hover:opacity-100"
                aria-label="Dismiss"
              >
                ×
              </button>
            </div>
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const ctx = useContext(ToastContext);
  if (!ctx) throw new Error('useToast must be used within ToastProvider');
  return ctx;
}

import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { GitCompare, X, ChevronUp, ChevronDown, Trash2 } from 'lucide-react';
import { getCompareIds, clearCompareList, fetchComparedProperties } from '../../lib/compare';
import { useAuth } from '../../lib/auth';
import type { Property } from '../../lib/types';
import { formatCompactPrice } from '../../lib/utils';
import { Button } from '../ui';

const SESSION_DISMISSED_KEY = 'realtynow_compare_panel_dismissed';

function getSessionDismissed(): boolean {
  try {
    return sessionStorage.getItem(SESSION_DISMISSED_KEY) === '1';
  } catch {
    return false;
  }
}
function setSessionDismissed(val: boolean) {
  try {
    if (val) sessionStorage.setItem(SESSION_DISMISSED_KEY, '1');
    else sessionStorage.removeItem(SESSION_DISMISSED_KEY);
  } catch {
    /* ignore */
  }
}

export function CompareFloatingPanel() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [ids, setIds] = useState<string[]>(getCompareIds());
  const [properties, setProperties] = useState<Property[]>([]);
  const [isMinimized, setIsMinimized] = useState(false);
  // Use sessionStorage so dismissed state survives ALL React re-renders
  const [isDismissed, setIsDismissedState] = useState<boolean>(getSessionDismissed);

  const prevIdsLengthRef = useRef(getCompareIds().length);
  // Guard against calling fetchComparedProperties concurrently
  const fetchingRef = useRef(false);

  const dismiss = () => {
    setSessionDismissed(true);
    setIsDismissedState(true);
  };

  const clearAll = (e: React.MouseEvent) => {
    e.stopPropagation();
    clearCompareList(user?.id);
    dismiss();
  };

  // Listen for compare list changes (add/remove from property cards)
  useEffect(() => {
    const handleUpdate = (e: CustomEvent) => {
      const newIds: string[] = e.detail.ids;
      const prevLen = prevIdsLengthRef.current;
      prevIdsLengthRef.current = newIds.length;
      setIds(newIds);

      // Only re-open if a NEW property was actually added
      if (newIds.length > prevLen) {
        setSessionDismissed(false);
        setIsDismissedState(false);
      }
    };
    window.addEventListener('realtynow-compare-updated', handleUpdate as EventListener);
    return () => window.removeEventListener('realtynow-compare-updated', handleUpdate as EventListener);
  }, []);

  // Fetch property details only when IDs change AND panel is visible
  useEffect(() => {
    if (ids.length === 0) {
      setProperties([]);
      return;
    }
    if (fetchingRef.current) return;
    fetchingRef.current = true;
    fetchComparedProperties(user?.id).then((data) => {
      setProperties(data);
      fetchingRef.current = false;
    });
  }, [ids.join(','), user?.id]);

  // Nothing to show
  if (ids.length === 0 || isDismissed) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 z-[999] pointer-events-none flex justify-center px-4 pb-4">
      <AnimatePresence>
        <motion.div
          key="compare-panel"
          initial={{ y: 120, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: 120, opacity: 0 }}
          transition={{ type: 'spring', stiffness: 300, damping: 30 }}
          className="bg-white rounded-2xl border border-gray-200 pointer-events-auto overflow-hidden flex flex-col w-full max-w-4xl"
          style={{ boxShadow: '0 -4px 40px rgba(0,0,0,0.15)' }}
        >
          {/* Header */}
          <div
            className="bg-gray-900 text-white px-4 py-3 flex items-center justify-between cursor-pointer select-none"
            onClick={() => setIsMinimized(!isMinimized)}
          >
            <div className="flex items-center gap-2.5 font-semibold text-sm">
              <GitCompare className="h-4 w-4 text-red-400" />
              Compare Properties
              <span className="bg-red-600 text-[11px] px-2 py-0.5 rounded-full font-bold">{ids.length}/4</span>
            </div>

            <div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
              {/* Minimize/Expand */}
              <button
                className="p-1.5 hover:bg-white/15 rounded-lg transition-colors text-white/70 hover:text-white"
                onClick={() => setIsMinimized((v) => !v)}
                title={isMinimized ? 'Expand' : 'Minimize'}
              >
                {isMinimized ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
              </button>

              {/* Clear All */}
              <button
                className="p-1.5 hover:bg-red-600/40 rounded-lg transition-colors text-white/70 hover:text-red-300"
                onClick={clearAll}
                title="Clear all & close"
              >
                <Trash2 className="h-4 w-4" />
              </button>

              {/* Close / Dismiss permanently for this session */}
              <button
                className="p-1.5 hover:bg-white/15 rounded-lg transition-colors text-white/70 hover:text-white"
                onClick={(e) => {
                  e.stopPropagation();
                  dismiss();
                }}
                title="Close panel"
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          </div>

          {/* Body */}
          <AnimatePresence>
            {!isMinimized && (
              <motion.div
                key="panel-body"
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.2 }}
                className="bg-white p-4 flex flex-col md:flex-row gap-4 items-stretch md:items-center justify-between overflow-hidden"
              >
                {/* Property Mini Cards */}
                <div className="flex gap-3 overflow-x-auto pb-1 flex-1">
                  {properties.map((p) => (
                    <div
                      key={p.id}
                      className="flex gap-2.5 bg-gray-50 rounded-xl p-2 min-w-[190px] max-w-[220px] border border-gray-200 items-center shrink-0"
                    >
                      <img
                        src={p.images?.[0] || 'https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg'}
                        className="w-11 h-11 rounded-lg object-cover bg-gray-200 shrink-0"
                        alt=""
                        onError={(e) => {
                          (e.target as HTMLImageElement).src =
                            'https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg';
                        }}
                      />
                      <div className="min-w-0 flex-1">
                        <p className="text-xs font-semibold text-gray-900 truncate leading-tight" title={p.title}>
                          {p.title}
                        </p>
                        <p className="text-xs font-bold text-red-600 mt-0.5">{formatCompactPrice(p.price)}</p>
                      </div>
                    </div>
                  ))}

                  {/* Empty Slot placeholders */}
                  {Array.from({ length: Math.max(0, Math.min(2, 4 - properties.length)) }).map((_, i) => (
                    <div
                      key={`slot-${i}`}
                      className="flex bg-gray-50/50 rounded-xl p-2 min-w-[130px] border border-dashed border-gray-200 items-center justify-center shrink-0 opacity-60"
                    >
                      <p className="text-[11px] font-medium text-gray-400">+ Add property</p>
                    </div>
                  ))}
                </div>

                {/* Compare Button */}
                <div className="shrink-0 flex flex-col items-center gap-1">
                  <Button
                    onClick={() => {
                      navigate('/compare');
                    }}
                    disabled={properties.length < 2}
                    className="w-full md:w-auto font-bold"
                    icon={<GitCompare className="h-4 w-4" />}
                  >
                    Compare Now
                  </Button>
                  {properties.length < 2 && (
                    <p className="text-[10px] text-gray-400">Add {2 - properties.length} more to compare</p>
                  )}
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

