  enabled,
  onEnabledChange,
}: VirtualTourUploadSectionProps) {
  const { user } = useAuth();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isDragOver, setIsDragOver] = useState(false);
  const [previewItem, setPreviewItem] = useState<VirtualTourUploadItem | null>(null);
  const [uploadingAll, setUploadingAll] = useState(false);

  const validateFile = (file: File): string | null => {
    const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
    if (!validTypes.includes(file.type)) {
      return `Invalid type: ${file.type}. Use JPG, PNG, or WebP.`;
    }
    if (file.size > MAX_SIZE_MB * 1024 * 1024) {
      return `File too large (max ${MAX_SIZE_MB}MB).`;
    }
    return null;
  };

  const addFiles = useCallback(
    (files: FileList | File[]) => {
      const fileArr = Array.from(files);
      const newItems: VirtualTourUploadItem[] = fileArr.map((file, i) => {
        const err = validateFile(file);
        return {
          file,
          preview: URL.createObjectURL(file),
          room_name: ROOM_OPTIONS[Math.min(value.length + i, ROOM_OPTIONS.length - 1)],
          title: file.name.replace(/\.[^.]+$/, '').replace(/[-_]/g, ' '),
          floor_number: 1,
          is_cover: value.length === 0 && i === 0,
          sort_order: value.length + i,
          error: err || undefined,
        };
      });
      onChange([...value, ...newItems]);
    },
    [value, onChange],
  );

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragOver(false);
    if (e.dataTransfer.files.length) addFiles(e.dataTransfer.files);
  };

  const removeItem = (idx: number) => {
    const next = value.filter((_, i) => i !== idx);
    // Re-assign cover if needed
    if (value[idx].is_cover && next.length > 0) next[0].is_cover = true;
    onChange(next);
  };

  const updateItem = (idx: number, patch: Partial<VirtualTourUploadItem>) => {
    const next = [...value];
    next[idx] = { ...next[idx], ...patch };
    // Ensure only one cover
    if (patch.is_cover) {
      next.forEach((item, i) => {
        if (i !== idx) item.is_cover = false;
      });
    }
    onChange(next);
  };

  const moveItem = (idx: number, dir: -1 | 1) => {
    const next = [...value];
    const target = idx + dir;
    if (target < 0 || target >= next.length) return;
    [next[idx], next[target]] = [next[target], next[idx]];
    next.forEach((item, i) => {
      item.sort_order = i;
    });
    onChange(next);
  };

  const uploadAll = async () => {
    if (!propertyId) return;
    setUploadingAll(true);

    const updated = [...value];
    for (let i = 0; i < updated.length; i++) {
      const item = updated[i];
      if (item.uploaded || item.error) continue;

      updated[i] = { ...item, uploading: true };
      onChange([...updated]);

      try {
        const ext = item.file.name.split('.').pop();
        const path = `${propertyId}/${Date.now()}-${i}.${ext}`;
        const { data, error } = await supabase.storage
          .from(BUCKET)
          .upload(path, item.file, { upsert: true, contentType: item.file.type });

        if (error) throw error;

        const { data: urlData } = supabase.storage.from(BUCKET).getPublicUrl(data.path);
        updated[i] = { ...item, uploading: false, uploaded: true, url: urlData.publicUrl };
        onChange([...updated]);

        // Insert into DB
        await supabase.from('property_virtual_tours').insert({
          property_id: propertyId,
          room_name: item.room_name,
          title: item.title,
          image_url: urlData.publicUrl,
          thumbnail_url: urlData.publicUrl,
          sort_order: item.sort_order,
          is_cover: item.is_cover,
          floor_number: item.floor_number,
          created_by: user?.id,
        });
      } catch (err: any) {
        updated[i] = { ...updated[i], uploading: false, error: err?.message ?? 'Upload failed' };
        onChange([...updated]);
      }
    }
    setUploadingAll(false);
  };

  const pendingCount = value.filter((v) => !v.uploaded && !v.error).length;

  return (
    <div className="w-full font-sans space-y-5">
      {/* Section Header + Toggle */}
      <div className="flex items-center justify-between gap-4 p-5 bg-gradient-to-br from-slate-900 to-slate-800 rounded-2xl border border-slate-700 shadow-xl">
        <div className="flex items-center gap-3">
          <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-red-600 to-rose-700 flex items-center justify-center shadow-lg shadow-red-600/30">
            <Camera className="w-6 h-6 text-white" />
          </div>
          <div>
            <h3 className="text-base font-extrabold text-white flex items-center gap-2">
              360° Virtual Tour
              <span className="text-[10px] font-black uppercase text-red-400 bg-red-500/10 px-2 py-0.5 rounded-full border border-red-500/20 tracking-wider">
                Premium
              </span>
            </h3>
            <p className="text-xs text-slate-400 mt-0.5">
              Upload equirectangular panoramas to give buyers an immersive walkthrough.
            </p>
          </div>
        </div>

        {/* Toggle */}
        <label className="flex items-center gap-2 cursor-pointer">
          <span className="text-xs font-bold text-slate-400">Enable Tour</span>
          <div
            onClick={() => onEnabledChange(!enabled)}
            className={`relative w-12 h-6 rounded-full transition-all cursor-pointer ${enabled ? 'bg-red-600' : 'bg-slate-700'}`}
          >
            <div
              className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow-md transition-all ${enabled ? 'left-7' : 'left-1'}`}
            />
          </div>
        </label>
      </div>

      {!enabled ? (
        <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-200 text-sm text-slate-500">
          <Info className="w-5 h-5 text-slate-400 shrink-0" />
          Enable the toggle above to add 360° panorama images to your listing.
        </div>
      ) : (
        <>
          {/* Upload Guidelines */}
          <div className="flex flex-wrap gap-2 text-xs">
            {[
              'Equirectangular Format Recommended',
              'Max 20MB per image',
              'JPG / JPEG / PNG / WebP',
              'Aspect Ratio 2:1 ideal',
            ].map((tip) => (
              <span
                key={tip}
                className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-100 text-slate-600 rounded-full border border-slate-200 font-semibold"
              >
                <CheckCircle2 className="w-3.5 h-3.5 text-emerald-500" />
                {tip}
              </span>
            ))}
          </div>

          {/* Drag & Drop Zone */}
          <div
            onDrop={handleDrop}
            onDragOver={(e) => {
              e.preventDefault();
              setIsDragOver(true);
            }}
            onDragLeave={() => setIsDragOver(false)}
            onClick={() => fileInputRef.current?.click()}
            className={`relative flex flex-col items-center justify-center gap-4 p-8 rounded-2xl border-2 border-dashed cursor-pointer transition-all ${
              isDragOver
                ? 'border-red-500 bg-red-50/50 scale-[1.01]'
                : 'border-slate-300 bg-slate-50/50 hover:border-red-400 hover:bg-red-50/30'
            }`}
          >
            <div className="w-16 h-16 rounded-3xl bg-red-50 text-red-600 flex items-center justify-center shadow-lg shadow-red-100">
              <Upload className="w-8 h-8" />
            </div>
            <div className="text-center">
              <p className="text-sm font-bold text-slate-800">
                {isDragOver ? 'Drop panorama images here' : 'Drag & drop 360° images or click to browse'}
              </p>
              <p className="text-xs text-slate-500 mt-1">Equirectangular panoramas work best (2:1 aspect ratio)</p>
            </div>
            <input
              ref={fileInputRef}
              type="file"
              accept={ACCEPTED_FORMATS}
              multiple
              className="hidden"
              onChange={(e) => e.target.files && addFiles(e.target.files)}
            />
          </div>

          {/* Uploaded Items Grid */}
          {value.length > 0 && (
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <h4 className="text-sm font-bold text-slate-800">
                  {value.length} panorama{value.length !== 1 ? 's' : ''} added
                </h4>
                {pendingCount > 0 && propertyId && (
                  <button
                    type="button"
                    onClick={uploadAll}
                    disabled={uploadingAll}
                    className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 disabled:opacity-60 text-white text-xs font-bold rounded-xl shadow-md shadow-red-600/30 transition-all cursor-pointer"
                  >
                    {uploadingAll ? <Loader2 className="w-4 h-4 animate-spin" /> : <Upload className="w-4 h-4" />}
                    Upload {pendingCount} Image{pendingCount !== 1 ? 's' : ''} to Cloud
                  </button>
                )}
              </div>

              {value.map((item, idx) => (
                <div
                  key={idx}
                  className={`flex flex-col sm:flex-row gap-4 p-4 rounded-2xl border transition-all ${
                    item.error
                      ? 'border-red-200 bg-red-50'
                      : item.uploaded
                        ? 'border-emerald-200 bg-emerald-50/30'
                        : item.is_cover
                          ? 'border-red-300 bg-red-50/50'
                          : 'border-slate-200 bg-white'
                  }`}
                >
                  {/* Thumbnail */}
                  <div className="relative w-full sm:w-28 h-20 rounded-xl overflow-hidden shrink-0 border border-slate-200">
                    <img
                      src={item.preview}
                      alt={item.room_name}
                      className="w-full h-full object-cover"
                      loading="lazy"
                    />
                    {item.uploading && (
                      <div className="absolute inset-0 bg-black/50 flex items-center justify-center">
                        <Loader2 className="w-5 h-5 text-white animate-spin" />
                      </div>
                    )}
                    {item.uploaded && (
                      <div className="absolute top-1.5 right-1.5">
                        <CheckCircle2 className="w-4 h-4 text-emerald-500 bg-white rounded-full" />
                      </div>
                    )}
                    {item.is_cover && (
                      <div className="absolute bottom-1 left-1 bg-red-600 text-white text-[9px] font-black px-1.5 py-0.5 rounded-full">
                        COVER
                      </div>
                    )}
                  </div>

                  {/* Fields */}
                  <div className="flex-1 grid grid-cols-1 sm:grid-cols-3 gap-3">
                    <div>
                      <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Room Name</label>
                      <select
                        value={item.room_name}
                        onChange={(e) => updateItem(idx, { room_name: e.target.value })}
                        className="w-full mt-1 text-xs px-2.5 py-1.5 border border-slate-200 rounded-xl bg-white text-slate-800 focus:outline-none focus:border-red-600"
                      >
                        {ROOM_OPTIONS.map((r) => (
                          <option key={r} value={r}>
                            {r}
                          </option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">
                        Title / Label
                      </label>
                      <input
                        type="text"
                        value={item.title}
                        onChange={(e) => updateItem(idx, { title: e.target.value })}
                        placeholder="e.g. Spacious Living Area"
                        className="w-full mt-1 text-xs px-2.5 py-1.5 border border-slate-200 rounded-xl bg-white text-slate-800 focus:outline-none focus:border-red-600"
                      />
                    </div>
                    <div>
                      <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Floor</label>
                      <input
                        type="number"
                        min={1}
                        max={50}
                        value={item.floor_number}
                        onChange={(e) => updateItem(idx, { floor_number: Number(e.target.value) })}
                        className="w-full mt-1 text-xs px-2.5 py-1.5 border border-slate-200 rounded-xl bg-white text-slate-800 focus:outline-none focus:border-red-600"
                      />
                    </div>
                  </div>

                  {/* Error */}
                  {item.error && (
                    <div className="col-span-full flex items-center gap-2 text-xs text-red-600 font-semibold mt-1">
                      <AlertCircle className="w-3.5 h-3.5" />
                      {item.error}
                    </div>
                  )}

                  {/* Actions */}
                  <div className="flex sm:flex-col items-center justify-center gap-2 shrink-0">
                    <button
                      type="button"
                      onClick={() => updateItem(idx, { is_cover: true })}
                      className={`p-2 rounded-xl transition-all cursor-pointer ${item.is_cover ? 'bg-red-600 text-white' : 'bg-slate-100 text-slate-500 hover:bg-amber-50 hover:text-amber-600'}`}
                      title={item.is_cover ? 'Cover Image' : 'Set as Cover'}
                    >
                      <Star className="w-4 h-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => moveItem(idx, -1)}
                      disabled={idx === 0}
                      className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-all cursor-pointer disabled:opacity-30"
                      title="Move Up"
                    >
                      <ChevronUp className="w-4 h-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => moveItem(idx, 1)}
                      disabled={idx === value.length - 1}
                      className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-slate-200 transition-all cursor-pointer disabled:opacity-30"
                      title="Move Down"
                    >
                      <ChevronDown className="w-4 h-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => setPreviewItem(item)}
                      className="p-2 rounded-xl bg-slate-100 text-slate-500 hover:bg-blue-50 hover:text-blue-600 transition-all cursor-pointer"
                      title="Preview"
                    >
                      <Eye className="w-4 h-4" />
                    </button>
                    <button
                      type="button"
                      onClick={() => removeItem(idx)}
                      className="p-2 rounded-xl bg-slate-100 text-red-500 hover:bg-red-50 transition-all cursor-pointer"
                      title="Remove"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Preview Modal */}
          {previewItem && (
            <div
              className="fixed inset-0 z-[9998] bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"
              onClick={() => setPreviewItem(null)}
            >
              <div
                className="relative max-w-3xl w-full rounded-3xl overflow-hidden shadow-2xl"
                onClick={(e) => e.stopPropagation()}
              >
                <img src={previewItem.preview} alt={previewItem.room_name} className="w-full object-cover" />
                <button
                  type="button"
                  onClick={() => setPreviewItem(null)}
                  className="absolute top-4 right-4 p-2 bg-black/70 rounded-full text-white hover:bg-black cursor-pointer"
                >
                  <X className="w-5 h-5" />
                </button>
                <div className="absolute bottom-4 left-4 bg-black/70 text-white text-xs font-bold px-3 py-1.5 rounded-full">
                  {previewItem.room_name} · Floor {previewItem.floor_number}
                </div>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
}

/**
 * Enterprise 360° Panorama Viewer Component for RealtyNow
 * Uses CSS 3D transforms for equirectangular panorama rendering with mouse/touch/gyroscope support.
 * No external 360-viewer dependency required — pure React + CSS 3D.
 */
import React, { useRef, useEffect, useState, useCallback } from 'react';
import type { VirtualTour } from '../../lib/types';
import {
  Maximize2,
  Minimize2,
  RotateCcw,
  ZoomIn,
  ZoomOut,
  ChevronLeft,
  ChevronRight,
  Eye,
  Camera,
  Layers,
  Home,
} from 'lucide-react';

interface VirtualTourViewerProps {
  tours: VirtualTour[];
  initialIndex?: number;
  propertyId?: string;
  onViewRecord?: (tourId: string) => void;
}

const ROOM_LABEL_COLORS: Record<string, string> = {
  'Living Room': 'from-red-600 to-rose-700',
  'Master Bedroom': 'from-blue-700 to-indigo-800',
  Bedroom: 'from-indigo-600 to-blue-700',
  Kitchen: 'from-amber-600 to-orange-700',
  Bathroom: 'from-teal-600 to-cyan-700',
  Balcony: 'from-emerald-600 to-green-700',
  'Dining Room': 'from-purple-600 to-violet-700',
  Lobby: 'from-slate-600 to-slate-800',
  Terrace: 'from-sky-600 to-blue-600',
  'Study Room': 'from-rose-700 to-pink-700',
};

export function VirtualTourViewer({ tours, initialIndex = 0, propertyId, onViewRecord }: VirtualTourViewerProps) {
  const canvasRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);
  const [current, setCurrent] = useState(initialIndex);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [zoom, setZoom] = useState(1);
  const [autoRotate, setAutoRotate] = useState(false);

  // Drag state
  const drag = useRef({ active: false, startX: 0, startY: 0, posX: 0, posY: 0 });
  const pos = useRef({ x: 0, y: 0 });
  const rafId = useRef<number | null>(null);

  const currentTour = tours[current];

  // Auto-rotate
  useEffect(() => {
    if (!autoRotate) return;
    const interval = setInterval(() => {
      pos.current.x += 0.15;
      applyTransform();
    }, 16);
    return () => clearInterval(interval);
  }, [autoRotate]);

  const applyTransform = useCallback(() => {
    if (!imgRef.current) return;
    const clampY = Math.max(-60, Math.min(60, pos.current.y));
    imgRef.current.style.transform = `translate(calc(-50% + ${-pos.current.x}px), calc(-50% + ${clampY * 0.5}px)) scale(${zoom})`;
  }, [zoom]);

  useEffect(() => {
    applyTransform();
  }, [zoom, applyTransform]);

  // Mouse handlers
  const onMouseDown = (e: React.MouseEvent) => {
    drag.current = { active: true, startX: e.clientX, startY: e.clientY, posX: pos.current.x, posY: pos.current.y };
    setAutoRotate(false);
  };

  const onMouseMove = useCallback(
    (e: MouseEvent) => {
      if (!drag.current.active) return;
      if (rafId.current) cancelAnimationFrame(rafId.current);
      rafId.current = requestAnimationFrame(() => {
        pos.current.x = drag.current.posX + (drag.current.startX - e.clientX) * 0.4;
        pos.current.y = drag.current.posY + (e.clientY - drag.current.startY) * 0.4;
        applyTransform();
      });
    },
    [applyTransform],
  );

  const onMouseUp = () => {
    drag.current.active = false;
  };

  // Touch handlers
  const lastTouch = useRef({ x: 0, y: 0 });
  const onTouchStart = (e: React.TouchEvent) => {
    lastTouch.current = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    drag.current = {
      active: true,
      startX: e.touches[0].clientX,
      startY: e.touches[0].clientY,
      posX: pos.current.x,
      posY: pos.current.y,
    };
    setAutoRotate(false);
  };
  const onTouchMove = (e: React.TouchEvent) => {
    if (!drag.current.active) return;
    e.preventDefault();
    pos.current.x = drag.current.posX + (drag.current.startX - e.touches[0].clientX) * 0.5;
    pos.current.y = drag.current.posY + (e.touches[0].clientY - drag.current.startY) * 0.5;
    applyTransform();
  };
  const onTouchEnd = () => {
    drag.current.active = false;
  };

  useEffect(() => {
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
    };
  }, [onMouseMove]);

  // Gyroscope support
  useEffect(() => {
    const onDeviceOrientation = (e: DeviceOrientationEvent) => {
      if (!e.gamma) return;
      pos.current.x = (e.alpha ?? 0) * 1.5;
      pos.current.y = (e.beta ?? 0) * 0.5;
      applyTransform();
    };
    window.addEventListener('deviceorientation', onDeviceOrientation);
    return () => window.removeEventListener('deviceorientation', onDeviceOrientation);
  }, [applyTransform]);

  // Reset view on tour change
  useEffect(() => {
    pos.current = { x: 0, y: 0 };
    setIsLoading(true);
    setZoom(1);
    applyTransform();
    if (onViewRecord && currentTour) {
      onViewRecord(currentTour.id);
    }
  }, [current]);

  const goPrev = () => setCurrent((c) => (c - 1 + tours.length) % tours.length);
  const goNext = () => setCurrent((c) => (c + 1) % tours.length);
  const resetView = () => {
    pos.current = { x: 0, y: 0 };
    setZoom(1);
    applyTransform();
  };
  const toggleFullscreen = () => {
    setIsFullscreen((f) => !f);
    if (!document.fullscreenElement && canvasRef.current) {
      canvasRef.current.requestFullscreen?.();
    } else {
      document.exitFullscreen?.();
    }
  };

  if (!currentTour) {
    return (
      <div className="flex items-center justify-center h-72 bg-slate-100 rounded-3xl text-slate-400 text-sm">
        No 360° tour images available.
      </div>
    );
  }

  const gradClass = ROOM_LABEL_COLORS[currentTour.room_name] || 'from-red-600 to-rose-700';

  return (
    <div
      ref={canvasRef}
      className={`relative w-full select-none overflow-hidden font-sans rounded-3xl border border-slate-200 shadow-2xl bg-slate-950 transition-all ${isFullscreen ? 'fixed inset-0 z-[9999] rounded-none border-0' : 'aspect-[16/7]'}`}
      style={{ touchAction: 'none' }}
    >
      {/* 360° Panorama Image */}
      <div
        className="absolute inset-0 overflow-hidden cursor-grab active:cursor-grabbing"
        onMouseDown={onMouseDown}
        onTouchStart={onTouchStart}
        onTouchMove={onTouchMove}
        onTouchEnd={onTouchEnd}
      >
        {/* Loading skeleton */}
        {isLoading && (
          <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-slate-950 animate-pulse gap-3">
            <div className="w-16 h-16 rounded-full border-4 border-red-600/40 border-t-red-600 animate-spin" />
            <p className="text-slate-400 text-sm font-semibold tracking-widest uppercase">Loading 360° Experience...</p>
          </div>
        )}
        {/* Equirectangular panorama render using wide image + X-shift drag */}
        <img
          ref={imgRef}
          src={currentTour.image_url}
          alt={currentTour.room_name}
          draggable={false}
          onLoad={() => setIsLoading(false)}
          className="absolute top-1/2 left-1/2 max-w-none pointer-events-none transition-opacity duration-300"
          style={{
            height: '100%',
            width: 'auto',
            minWidth: '200%',
            transform: 'translate(-50%, -50%) scale(1)',
            willChange: 'transform',
            opacity: isLoading ? 0 : 1,
          }}
        />
      </div>

      {/* Top gradient overlay */}
      <div className="absolute top-0 left-0 right-0 h-20 bg-gradient-to-b from-black/70 to-transparent pointer-events-none z-10" />
      <div className="absolute bottom-0 left-0 right-0 h-24 bg-gradient-to-t from-black/80 to-transparent pointer-events-none z-10" />

      {/* 360° Badge + Room Label */}
      <div className="absolute top-4 left-5 z-20 flex items-center gap-2">
        <div
          className={`flex items-center gap-1.5 bg-gradient-to-r ${gradClass} px-3 py-1.5 rounded-full text-white text-xs font-extrabold shadow-lg`}
        >
          <Camera className="w-3.5 h-3.5" />
          <span>360°</span>
        </div>
        <div className="bg-black/60 backdrop-blur-sm px-3 py-1.5 rounded-full text-white text-xs font-bold flex items-center gap-1.5 border border-white/10">
          <Home className="w-3.5 h-3.5 text-slate-300" />
          {currentTour.room_name}
          {currentTour.floor_number > 1 && <span className="text-slate-400">· Floor {currentTour.floor_number}</span>}
        </div>
      </div>

      {/* Controls: Top Right */}
      <div className="absolute top-4 right-5 z-20 flex items-center gap-2">
        <button
          type="button"
          onClick={() => setAutoRotate((a) => !a)}
          className={`p-2 rounded-xl backdrop-blur-md border transition-all cursor-pointer ${autoRotate ? 'bg-red-600 border-red-500 text-white shadow-lg shadow-red-600/40' : 'bg-black/50 border-white/10 text-white hover:bg-white/10'}`}
          title={autoRotate ? 'Stop Auto-Rotate' : 'Auto-Rotate'}
        >
          <RotateCcw className={`w-4 h-4 ${autoRotate ? 'animate-spin' : ''}`} />
        </button>
        <button
          type="button"
          onClick={() => setZoom((z) => Math.min(2.5, z + 0.2))}
          className="p-2 rounded-xl bg-black/50 backdrop-blur-md border border-white/10 text-white hover:bg-white/10 transition-all cursor-pointer"
          title="Zoom In"
        >
          <ZoomIn className="w-4 h-4" />
        </button>
        <button
          type="button"
          onClick={() => setZoom((z) => Math.max(0.6, z - 0.2))}
          className="p-2 rounded-xl bg-black/50 backdrop-blur-md border border-white/10 text-white hover:bg-white/10 transition-all cursor-pointer"
          title="Zoom Out"
        >
          <ZoomOut className="w-4 h-4" />
        </button>
        <button
          type="button"
          onClick={resetView}
          className="p-2 rounded-xl bg-black/50 backdrop-blur-md border border-white/10 text-white hover:bg-white/10 transition-all cursor-pointer"
          title="Reset View"
        >
          <Eye className="w-4 h-4" />
        </button>
        <button
          type="button"
          onClick={toggleFullscreen}
          className="p-2 rounded-xl bg-black/50 backdrop-blur-md border border-white/10 text-white hover:bg-white/10 transition-all cursor-pointer"
          title={isFullscreen ? 'Exit Fullscreen' : 'Fullscreen'}
        >
          {isFullscreen ? <Minimize2 className="w-4 h-4" /> : <Maximize2 className="w-4 h-4" />}
        </button>
      </div>

      {/* Navigation arrows */}
      {tours.length > 1 && (
        <>
          <button
            type="button"
            onClick={goPrev}
            className="absolute left-4 top-1/2 -translate-y-1/2 z-20 p-2.5 rounded-xl bg-black/60 backdrop-blur-md border border-white/10 text-white hover:bg-red-600 hover:border-red-500 transition-all cursor-pointer shadow-lg"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
          <button
            type="button"
            onClick={goNext}
            className="absolute right-4 top-1/2 -translate-y-1/2 z-20 p-2.5 rounded-xl bg-black/60 backdrop-blur-md border border-white/10 text-white hover:bg-red-600 hover:border-red-500 transition-all cursor-pointer shadow-lg"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </>
      )}

      {/* Drag hint */}
      <div className="absolute bottom-20 left-1/2 -translate-x-1/2 z-20 pointer-events-none">
        <p className="text-white/50 text-xs font-semibold tracking-widest uppercase bg-black/30 px-3 py-1 rounded-full backdrop-blur-sm">
          ↔ Drag to explore · Pinch to zoom
        </p>
      </div>

      {/* Room Selector Thumbnails */}
      <div className="absolute bottom-4 left-0 right-0 z-20 flex items-center justify-center gap-2.5 px-4 overflow-x-auto pb-1">
        {tours.map((tour, idx) => (
          <button
            key={tour.id}
            type="button"
            onClick={() => setCurrent(idx)}
            className={`flex-shrink-0 flex flex-col items-center gap-1 cursor-pointer transition-all ${current === idx ? 'scale-110' : 'opacity-70 hover:opacity-100'}`}
          >
            <div
              className={`w-14 h-10 rounded-xl overflow-hidden border-2 transition-all ${current === idx ? 'border-red-500 shadow-lg shadow-red-500/40' : 'border-white/20'}`}
            >
              <img
                src={tour.thumbnail_url || tour.image_url}
                alt={tour.room_name}
                className="w-full h-full object-cover"
                loading="lazy"
              />
            </div>
            <span
              className={`text-[10px] font-bold px-1.5 py-0.5 rounded-md max-w-[60px] truncate ${current === idx ? 'text-white bg-red-600/80' : 'text-white/60 bg-black/40'}`}
            >
              {tour.room_name.split(' ')[0]}
            </span>
          </button>
        ))}
      </div>

      {/* Tour counter pill */}
      <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 bg-black/50 backdrop-blur-md border border-white/10 px-3 py-1 rounded-full text-white text-xs font-bold flex items-center gap-1.5">
        <Layers className="w-3.5 h-3.5 text-red-400" />
        {current + 1} / {tours.length}
      </div>
    </div>
  );
}

import React, { createContext, useContext, useState, useEffect } from 'react';

type LocationState = {
  city: string | null;
  coordinates: { lat: number; lng: number } | null;
  isLocating: boolean;
  error: string | null;
};

type LocationContextType = LocationState & {
  setCity: (city: string) => void;
  detectLocation: () => Promise<void>;
};

const LocationContext = createContext<LocationContextType | undefined>(undefined);

const API_KEY = import.meta.env.VITE_GOOGLE_MAPS_API_KEY;

export function LocationProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<LocationState>(() => {
    const savedCity = localStorage.getItem('user_city');
    return {
      city: savedCity || null,
      coordinates: null,
      isLocating: false,
      error: null,
    };
  });

  const detectLocation = async () => {
    setState((s) => ({ ...s, isLocating: true, error: null }));

    if (!navigator.geolocation) {
      setState((s) => ({ ...s, isLocating: false, error: 'Geolocation is not supported by your browser.' }));
      return;
    }

    try {
      const position = await new Promise<GeolocationPosition>((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(resolve, reject, {
          enableHighAccuracy: true,
          timeout: 5000,
          maximumAge: 0
        });
      });

      const { latitude, longitude } = position.coords;
      setState((s) => ({ ...s, coordinates: { lat: latitude, lng: longitude } }));

      // Reverse geocode using OpenStreetMap Nominatim API (Free, no key required)
      const response = await fetch(
        `https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}&zoom=10&addressdetails=1`,
        {
          headers: {
            'Accept-Language': 'en-US,en;q=0.9',
            // User-Agent is required by Nominatim usage policy
            'User-Agent': 'RealtyNow/1.0 (contact@realtynow.in)'
          }
        }
      );
      const data = await response.json();

      if (data && data.address) {
        // Nominatim returns city in various fields depending on the region
        const foundCity = data.address.city || data.address.town || data.address.state_district || data.address.county;

        if (foundCity) {
          // Clean up the city name (e.g., "Hyderabad District" -> "Hyderabad")
          const cleanCity = foundCity.replace(/ (District|City|Mandal)$/i, '');
          setState((s) => ({ ...s, city: cleanCity, isLocating: false }));
          localStorage.setItem('user_city', cleanCity);
          return;
        }
      }

      // Fallback if geocoding fails to find a city name
      setState((s) => ({ ...s, isLocating: false, error: 'Could not determine city name from coordinates.' }));
    } catch (err: any) {
      console.warn('Geolocation error:', err);
      setState((s) => ({ 
        ...s, 
        isLocating: false, 
        error: err.code === 1 ? 'Location permission denied.' : 'Failed to fetch location.'
      }));
    }
  };

  const setCity = (city: string) => {
    setState((s) => ({ ...s, city, error: null }));
    localStorage.setItem('user_city', city);
  };

  // Auto-detect on mount if no city is saved
  useEffect(() => {
    if (!state.city && !state.error && !state.isLocating) {
      // Small delay to allow initial render
      const timer = setTimeout(() => {
        detectLocation();
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [state.city, state.error, state.isLocating]);

  return (
    <LocationContext.Provider value={{ ...state, setCity, detectLocation }}>
      {children}
    </LocationContext.Provider>
  );
}

export function useLocationContext() {
  const context = useContext(LocationContext);
  if (context === undefined) {
    throw new Error('useLocationContext must be used within a LocationProvider');
  }
  return context;
}

import { supabase } from './supabase';
import i18n from './i18n/i18n';

export type AITask =
  | 'chat'
  | 'parse_search'
  | 'recommend'
  | 'description'
  | 'title'
  | 'seo'
  | 'lead_summary'
  | 'translate'
  | 'market_insights'
  | 'email';

export interface AIRequest {
  task: AITask;
  payload: Record<string, unknown>;
}

export interface AIResponse {
  result: string;
  error?: string;
}

export interface ParsedSearchFilter {
  city?: string;
  locality?: string;
  purpose?: 'Sale' | 'Rent';
  bedrooms?: number;
  max_price?: number;
  property_type?: string;
  amenities?: string[];
}

function getSystemAndUserPrompt(task: AITask, payload: Record<string, unknown>): { system: string; user: string } {
  const p = payload;
  const currentLangCode = localStorage.getItem('realtynow_language') || i18n.language || 'en';
  const langNames: Record<string, string> = {
    hi: 'Hindi (हिंदी)',
    te: 'Telugu (తెలుగు)',
    ta: 'Tamil (தமிழ்)',
    kn: 'Kannada (ಕನ್ನಡ)',
    ml: 'Malayalam (മലയാളം)',
    mr: 'Marathi (मराठी)',
    bn: 'Bengali (বাংলা)',
    gu: 'Gujarati (ગુજરાતી)',
    pa: 'Punjabi (ਪੰਜਾਬੀ)',
    en: 'English',
  };
  const targetLang = langNames[currentLangCode] || 'English';
  const langSuffix =
    currentLangCode !== 'en' && task !== 'parse_search'
      ? ` IMPORTANT INSTRUCTION: You MUST write your ENTIRE response in ${targetLang} language.`
      : '';

  switch (task) {
    case 'parse_search':
      return {
        system:
          'You are an AI real estate search parser for India. Extract search parameters into raw JSON with fields: city (string), locality (string), purpose ("Sale" or "Rent"), bedrooms (number), max_price (number in INR), property_type (string). Return ONLY valid JSON, no markdown code blocks.',
        user: `Parse this natural language property search query into JSON: "${p.query ?? p.q ?? ''}"`,
      };

    case 'market_insights':
      return {
        system: `You are an Indian real estate market analyst. Generate concise market insights for a city/locality. Include average price per sqft, 1-year appreciation estimate, top infrastructure advantages, and rental yield percentage. Bullet points under 150 words.${langSuffix}`,
        user: `Generate market insights for: locality="${p.locality ?? ''}", city="${p.city ?? ''}", property_type="${p.type ?? ''}".`,
      };

    case 'description':
      return {
        system: `You are an expert real estate copywriter. Write a compelling, accurate property description. 120-180 words. Plain text without markdown formatting or bullet points.${langSuffix}`,
        user: `Write a property description for: title="${p.title ?? ''}", type=${p.type ?? ''}, purpose=${p.purpose ?? ''}, bedrooms=${p.bedrooms ?? ''}, bathrooms=${p.bathrooms ?? ''}, area=${p.area ?? ''} sqft, city=${p.city ?? ''}, locality=${p.locality ?? ''}, furnishing=${p.furnishing ?? ''}, amenities=${Array.isArray(p.amenities) ? p.amenities.join(', ') : (p.amenities ?? '')}.`,
      };

    case 'seo':
      return {
        system: `You are an SEO specialist. Write a concise, click-worthy meta description under 160 characters optimized for real estate search. Plain text only.${langSuffix}`,
        user: `Create an SEO meta description for property titled "${p.title ?? ''}" in ${p.locality ?? ''}, ${p.city ?? ''}.`,
      };

    case 'title':
      return {
        system: `You are a real estate listing expert. Generate a catchy, professional property title under 80 characters. Plain text, no quotes.${langSuffix}`,
        user: `Create a listing title for a ${p.purpose ?? ''} ${p.type ?? ''} with ${p.bedrooms ?? ''} BHK in ${p.locality ?? ''}, ${p.city ?? ''}.`,
      };

    case 'lead_summary':
      return {
        system: `You are a CRM AI assistant. Summarize this real estate customer inquiry in 2-3 actionable bullet points for an agent.${langSuffix}`,
        user: `Customer Enquiry: ${JSON.stringify(p)}`,
      };

    case 'email':
      return {
        system: `Write a warm, professional follow-up email to a real estate lead. Plain text without subject line.${langSuffix}`,
        user: `Write an email to ${p.name ?? 'the client'} regarding property "${p.property ?? ''}".`,
      };

    case 'recommend':
      return {
        system: `You are an AI property matchmaker in India. Recommend 3 suitable localities or property configurations based on the user preferences. 3 bullet points, concise text.${langSuffix}`,
        user: `User search preferences: ${String(p.message ?? p.q ?? JSON.stringify(p))}`,
      };

    case 'translate':
      return {
        system:
          'Translate the real estate text accurately into the requested Indian language. Return only the translated text.',
        user: `Translate the following text into ${p.language ?? targetLang}: "${p.text ?? ''}"`,
      };

    case 'chat':
    default:
      return {
        system: `You are RealtyNow's intelligent AI real estate assistant in India. Be concise, friendly, helpful, and accurate. Provide actionable real estate guidance on buying, renting, pricing trends, localities, documentation, and property services. Keep replies under 120 words.${langSuffix}`,
        user: `${p.message ?? p.q ?? JSON.stringify(p)}${p.context ? `\nContext: ${p.context}` : ''}`,
      };
  }
}

export async function callAI(task: AITask, payload: Record<string, unknown>): Promise<string> {
  const customKey = (import.meta.env.VITE_AI_API_KEY || import.meta.env.VITE_OPENROUTER_API_KEY) as string | undefined;

  // Direct OpenRouter client-side call if key is present
  if (customKey && customKey.trim().length > 0) {
    try {
      const { system, user } = getSystemAndUserPrompt(task, payload);
      const res = await fetch('https://openrouter.ai/api/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${customKey.trim()}`,
          'HTTP-Referer': 'https://realtynow.in',
          'X-Title': 'RealtyNow AI',
        },
        body: JSON.stringify({
          model: 'openai/gpt-4o-mini',
          messages: [
            { role: 'system', content: system },
            { role: 'user', content: user },
          ],
          temperature: 0.7,
          max_tokens: 600,
        }),
      });

      if (res.ok) {
        const data = await res.json();
        const content = data?.choices?.[0]?.message?.content;
        if (typeof content === 'string' && content.trim()) {
          return content.trim();
        }
      }
    } catch {
      /* Fallback to Edge function */
    }
  }

  // Edge Function fallback
  const { data: sessionData } = await supabase.auth.getSession();
  const token = sessionData.session?.access_token;

  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
  const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
  const response = await fetch(`${supabaseUrl}/functions/v1/ai-agent`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token ?? supabaseKey}`,
      apikey: supabaseKey,
    },
    body: JSON.stringify({ task, payload }),
  });

  if (!response.ok) {
    return fallbackAIResponse(task, payload);
  }

  const data = (await response.json()) as AIResponse;
  return data.result || fallbackAIResponse(task, payload);
}

function fallbackAIResponse(task: AITask, payload: Record<string, unknown>): string {
