import React, { createContext, useContext, useState, useEffect, useMemo, useCallback } from 'react';
import i18n, { SUPPORTED_LANGUAGES, LanguageMeta } from './i18n';
import { supabase } from '../supabase';
import { useAuth } from '../auth';

interface LanguageContextType {
  currentLanguage: LanguageMeta;
  changeLanguage: (code: string) => Promise<void>;
  supportedLanguages: LanguageMeta[];
  loading: boolean;
  t: (key: string, fallback?: string) => string;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

const ALL_NAMESPACES = [
  'common',
  'home',
  'auth',
  'property',
  'dashboard',
  'profile',
  'agent',
  'admin',
  'validation',
  'notifications',
  'ai',
];

const SUPPORTED_CODES = new Set(['en', 'hi', 'te', 'ta', 'kn', 'ml', 'mr', 'bn', 'gu', 'pa']);

export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { user } = useAuth();
  const [langCode, setLangCode] = useState<string>(() => {
    const saved = localStorage.getItem('realtynow_language');
    // If no saved preference or saved value is unsupported, default to English
    if (!saved || !SUPPORTED_CODES.has(saved)) {
      localStorage.setItem('realtynow_language', 'en');
      return 'en';
    }
    return saved;
  });
  const [loading, setLoading] = useState<boolean>(false);

  // Subscribe to i18n languageChanged event for instant reactive UI updates
  useEffect(() => {
    const handleLangChange = (lng: string) => {
      setLangCode(lng);
      document.documentElement.lang = lng;
    };
    i18n.on('languageChanged', handleLangChange);

    // Initial sync — enforce English as fallback if localStorage value is missing/unsupported
    const rawLang = localStorage.getItem('realtynow_language') || 'en';
    const initialLang = SUPPORTED_CODES.has(rawLang) ? rawLang : 'en';
    if (initialLang !== rawLang) {
      localStorage.setItem('realtynow_language', 'en');
    }
    if (i18n.language !== initialLang) {
      i18n.changeLanguage(initialLang);
    }
    document.documentElement.lang = initialLang;

    return () => {
      i18n.off('languageChanged', handleLangChange);
    };
  }, []);

  // Sync user language preference from Supabase user_preferences table on login
  useEffect(() => {
    if (!user?.id) return;
    const userId = user.id;
    async function syncPreference() {
      try {
        const { data } = await supabase
          .from('user_preferences')
          .select('language_code')
          .eq('user_id', userId)
          .single();

        if (data && data.language_code && data.language_code !== langCode) {
          const match = SUPPORTED_LANGUAGES.find((l) => l.code === data.language_code);
          if (match) {
            await changeLanguage(match.code);
          }
        }
      } catch {
        /* silent sync catch */
      }
    }
    syncPreference();
  }, [user?.id]);

  const currentLanguage = useMemo(() => {
    return SUPPORTED_LANGUAGES.find((l) => l.code === langCode) || SUPPORTED_LANGUAGES[0];
  }, [langCode]);

  const changeLanguage = async (code: string) => {
    const target = SUPPORTED_LANGUAGES.find((l) => l.code === code);
    if (!target) return;

    setLoading(true);
    try {
      await i18n.changeLanguage(code);
      setLangCode(code);
      localStorage.setItem('realtynow_language', code);
      document.documentElement.lang = code;

      // Persist to Supabase database if authenticated
      if (user) {
        await supabase.from('user_preferences').upsert({
          user_id: user.id,
          language_code: code,
          updated_at: new Date().toISOString(),
        });
      }
    } catch (err) {
      console.error('Error changing language:', err);
    } finally {
      setLoading(false);
    }
  };

  const t = useCallback(
    (key: string, fallback?: string): string => {
      if (!key) return fallback || '';

      // 1. Dot notation namespace resolution (e.g., "common.sale", "home.heroTitle", "property.bedrooms")
      if (key.includes('.')) {
        const parts = key.split('.');
        const ns = parts[0];
        const subKey = parts.slice(1).join('.');

        const nsVal = i18n.t(subKey, { ns, lng: langCode, defaultValue: '' });
        if (nsVal && nsVal !== subKey && nsVal !== key) {
          return nsVal;
        }
      }

      // 2. Multi-namespace fallback search in active language
      for (const ns of ALL_NAMESPACES) {
        const val = i18n.t(key, { ns, lng: langCode, defaultValue: '' });
        if (val && val !== key && val !== `${ns}:${key}`) {
          return val;
        }
      }

      return fallback || key;
    },
    [langCode],
  );

  const value = useMemo(
    () => ({
      currentLanguage,
      changeLanguage,
      supportedLanguages: SUPPORTED_LANGUAGES,
      loading,
      t,
    }),
    [currentLanguage, loading, t],
  );

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
};

export const useLanguageContext = (): LanguageContextType => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguageContext must be used within a LanguageProvider');
  }
  return context;
};

import { useEffect, useRef, useState } from 'react';
import type { RealtimeChannel } from '@supabase/supabase-js';
import { supabase } from './supabase';

/**
 * Subscribe to realtime changes on a table filtered by a column.
 * Returns a counter that increments on every change, so consumers can
 * refetch via react-query's `refetch` or invalidate query keys.
 */
export function useRealtimeCount(
  table: string,
  filter?: { column: string; value: string },
  event: 'INSERT' | 'UPDATE' | 'DELETE' | '*' = '*',
): number {
  const [count, setCount] = useState(0);
  const channelRef = useRef<RealtimeChannel | null>(null);

  useEffect(() => {
    const channelName = (filter?.value ? `realtime-${table}-${filter.column}-${filter.value}` : `realtime-${table}-all`) + `-${Math.random().toString(36).substring(7)}`;

    const channel = supabase.channel(channelName);

    if (filter) {
      channel.on(
        'postgres_changes',
        { event, schema: 'public', table, filter: `${filter.column}=eq.${filter.value}` },
        () => setCount((c) => c + 1),
      );
    } else {
      channel.on('postgres_changes', { event, schema: 'public', table }, () => setCount((c) => c + 1));
    }

    channel.subscribe();
    channelRef.current = channel;

    return () => {
      supabase.removeChannel(channel);
      channelRef.current = null;
    };
  }, [table, filter?.column, filter?.value, event]);

  return count;
}

/**
 * Subscribe to realtime changes on multiple tables.
 * Returns a single counter that increments on any table change.
 */
export function useRealtimeMulti(tables: string[], filter?: { column: string; value: string }): number {
  const [count, setCount] = useState(0);
  const channelRef = useRef<RealtimeChannel | null>(null);

  useEffect(() => {
    const channelName = `realtime-multi-${tables.join('-')}-${Math.random().toString(36).substring(7)}`;
    const channel = supabase.channel(channelName);

    tables.forEach((table) => {
      if (filter) {
        channel.on(
          'postgres_changes',
          { event: '*', schema: 'public', table, filter: `${filter.column}=eq.${filter.value}` },
          () => setCount((c) => c + 1),
        );
      } else {
        channel.on('postgres_changes', { event: '*', schema: 'public', table }, () => setCount((c) => c + 1));
      }
    });

    channel.subscribe();
    channelRef.current = channel;

    return () => {
      supabase.removeChannel(channel);
      channelRef.current = null;
    };
  }, [tables.join(','), filter?.column, filter?.value]);

  return count;
}

/**
 * Subscribe to notifications for the current user.
 * Returns the unread count and a refetch trigger.
 */
export function useRealtimeNotifications(userId: string | undefined) {
  const [unreadCount, setUnreadCount] = useState(0);
  const [refetchFlag, setRefetchFlag] = useState(0);
  const channelRef = useRef<RealtimeChannel | null>(null);

  useEffect(() => {
    if (!userId) return;

    const channel = supabase
      .channel(`notifications-${userId}-${Math.random().toString(36).substring(7)}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'notifications', filter: `user_id=eq.${userId}` },
        (payload) => {
          setRefetchFlag((f) => f + 1);
          (async () => {
            const { count } = await supabase
              .from('notifications')
              .select('*', { count: 'exact', head: true })
              .eq('user_id', userId)
              .is('read_at', null);
            setUnreadCount(count ?? 0);
          })();

          if (payload.eventType === 'INSERT') {
            const newNotif = payload.new as any;
            if (Notification.permission === 'granted') {
              new Notification(newNotif.title, {
                body: newNotif.body,
                icon: '/pwa-192x192.png',
              });
            }
          }
        },
      )
      .subscribe();

    channelRef.current = channel;

    return () => {
      supabase.removeChannel(channel);
      channelRef.current = null;
    };
  }, [userId]);

  return { unreadCount, refetchFlag, setUnreadCount };
}

import { RealtimeChannel } from '@supabase/supabase-js';
import { supabase } from './supabase';

export type SubscriptionConfig = {
  event: 'INSERT' | 'UPDATE' | 'DELETE' | '*';
  schema: string;
  table: string;
  filter?: string;
};

class RealtimeManager {
  private channels = new Map<
    string,
    {
      channel: RealtimeChannel;
      callbacks: Set<(payload: any) => void>;
    }
  >();

  /**
   * Safely subscribe to a Supabase Realtime channel.
   * Prevents "cannot add postgres_changes callbacks after subscribe" by centralizing listeners.
   */
  subscribe(channelName: string, config: SubscriptionConfig, callback: (payload: any) => void) {
    const existingEntry = this.channels.get(channelName);

    if (existingEntry) {
      console.warn(`[RealtimeManager] Duplicate realtime channel detected. Reusing: ${channelName}`);
      existingEntry.callbacks.add(callback);
      return;
    }

    // Clean up stale channels from Supabase before recreating
    const existingSupabaseChannels = supabase.getChannels();
    const staleChannel = existingSupabaseChannels.find((c) => c.topic === `realtime:${channelName}`);
    if (staleChannel) {
      console.warn(`[RealtimeManager] Removing stale realtime channel: ${channelName}`);
      supabase.removeChannel(staleChannel);
    }

    const channel = supabase.channel(channelName);
    const callbacks = new Set<(payload: any) => void>();
    callbacks.add(callback);

    channel.on('postgres_changes', config, (payload) => {
      callbacks.forEach((cb) => cb(payload));
    });

    channel.subscribe((status, err) => {
      if (err) {
        console.error(`[RealtimeManager] Error subscribing to ${channelName}:`, err);
      } else if (status === 'SUBSCRIBED') {
        console.log(`[RealtimeManager] Successfully subscribed to ${channelName}`);
      }
    });

    this.channels.set(channelName, { channel, callbacks });
  }

  /**
   * Safely unsubscribe a specific callback from a channel, or completely remove the channel if it's the last listener.
   */
  unsubscribe(channelName: string, callback?: (payload: any) => void) {
    const entry = this.channels.get(channelName);
    if (!entry) return;

    if (callback) {
      entry.callbacks.delete(callback);
      // If there are still listeners, do not remove the channel
      if (entry.callbacks.size > 0) return;
    }

    console.log(`[RealtimeManager] Unsubscribing and removing channel: ${channelName}`);
    supabase.removeChannel(entry.channel);
    this.channels.delete(channelName);
  }

  /**
   * Complete cleanup of all channels (e.g., on user logout)
   */
  cleanup() {
    console.log(`[RealtimeManager] Cleaning up all ${this.channels.size} channels...`);
    this.channels.forEach((entry) => {
      supabase.removeChannel(entry.channel);
    });
    this.channels.clear();
  }
}

export const realtimeManager = new RealtimeManager();

