              />

              <div className="grid gap-3 sm:grid-cols-2">
                <Input
                  label="SEO Alt Text"
                  value={form.seo_alt_text}
                  onChange={(e) => setForm((f) => ({ ...f, seo_alt_text: e.target.value }))}
                  placeholder="Alt text for screen readers..."
                />
                <Input
                  label="Image Caption"
                  value={form.image_caption}
                  onChange={(e) => setForm((f) => ({ ...f, image_caption: e.target.value }))}
                  placeholder="Caption under banner..."
                />
              </div>
            </div>
          )}

          {/* TAB 3: CTA & REDIRECTION */}
          {modalTab === 'redirection' && (
            <div className="space-y-4">
              <div className="grid gap-3 sm:grid-cols-2">
                <Input
                  label="CTA Button Text *"
                  value={form.cta_text}
                  onChange={(e) => setForm((f) => ({ ...f, cta_text: e.target.value }))}
                  placeholder="e.g. Explore Properties"
                />
                <Select
                  label="Redirect Type"
                  value={form.redirect_type}
                  onChange={(e) => setForm((f) => ({ ...f, redirect_type: e.target.value }))}
                >
                  <option value="External URL">External URL / Custom Link</option>
                  <option value="Property">Direct Property Listing</option>
                  <option value="Category">Property Purpose / Category</option>
                  <option value="Custom Page">Custom Promotional Landing Page</option>
                </Select>
              </div>

              {form.redirect_type === 'Property' && (
                <div>
                  <label className="label">Select Property Listing</label>
                  <Select
                    value={form.property_id}
                    onChange={(e) => setForm((f) => ({ ...f, property_id: e.target.value }))}
                  >
                    <option value="">-- Choose Live Property --</option>
                    {(properties ?? []).map((p) => (
                      <option key={p.id} value={p.id}>
                        {p.title} ({p.purpose} - ₹{p.price})
                      </option>
                    ))}
                  </Select>
                </div>
              )}

              {form.redirect_type === 'Category' && (
                <div>
                  <label className="label">Select Category / Purpose</label>
                  <Select
                    value={form.category_name}
                    onChange={(e) => setForm((f) => ({ ...f, category_name: e.target.value }))}
                  >
                    <option value="Buy">Buy Properties</option>
                    <option value="Rent">Rent Properties</option>
                    <option value="Commercial">Commercial Spaces</option>
                    <option value="Plots">Plots & Lands</option>
                    <option value="Projects">Builder Projects</option>
                  </Select>
                </div>
              )}

              <Input
                label="Redirect Link URL"
                value={form.cta_link}
                onChange={(e) => setForm((f) => ({ ...f, cta_link: e.target.value }))}
                placeholder="https://realtynow.in/promotions/monsoon-deals"
              />
            </div>
          )}

          {/* TAB 4: SCHEDULE & TARGETING */}
          {modalTab === 'schedule' && (
            <div className="space-y-4">
              <div className="grid gap-3 sm:grid-cols-2">
                <Input
                  label="Start Date & Time"
                  type="datetime-local"
                  value={form.start_date}
                  onChange={(e) => setForm((f) => ({ ...f, start_date: e.target.value }))}
                />
                <Input
                  label="End Date & Time (Optional)"
                  type="datetime-local"
                  value={form.end_date}
                  onChange={(e) => setForm((f) => ({ ...f, end_date: e.target.value }))}
                />
              </div>

              <div className="grid gap-3 sm:grid-cols-3">
                <Input
                  label="Banner Priority (1-5)"
                  type="number"
                  min="1"
                  max="5"
                  value={form.priority}
                  onChange={(e) => setForm((f) => ({ ...f, priority: parseInt(e.target.value) || 1 }))}
                />
                <Input
                  label="Display Order"
                  type="number"
                  min="0"
                  value={form.display_order}
                  onChange={(e) => setForm((f) => ({ ...f, display_order: parseInt(e.target.value) || 0 }))}
                />
                <Input
                  label="Impression Limit (0 = Unlimited)"
                  type="number"
                  min="0"
                  value={form.impression_limit}
                  onChange={(e) => setForm((f) => ({ ...f, impression_limit: parseInt(e.target.value) || 0 }))}
                />
              </div>

              <div className="grid gap-3 sm:grid-cols-3">
                <Select
                  label="Target Audience"
                  value={form.target_audience}
                  onChange={(e) => setForm((f) => ({ ...f, target_audience: e.target.value }))}
                >
                  <option value="All Users">All Users</option>
                  <option value="Buyers">Buyers Only</option>
                  <option value="Sellers">Sellers Only</option>
                  <option value="Agents">Agents Only</option>
                  <option value="Guests">Guests / Visitors</option>
                </Select>

                <Select
                  label="City Targeting"
                  value={form.city_targeting}
                  onChange={(e) => setForm((f) => ({ ...f, city_targeting: e.target.value }))}
                >
                  <option value="All Cities">All Cities</option>
                  <option value="Hyderabad">Hyderabad</option>
                  <option value="Bangalore">Bangalore</option>
                  <option value="Mumbai">Mumbai</option>
                  <option value="Delhi NCR">Delhi NCR</option>
                </Select>

                <Select
                  label="Device Targeting"
                  value={form.device_targeting}
                  onChange={(e) => setForm((f) => ({ ...f, device_targeting: e.target.value }))}
                >
                  <option value="All Devices">All Devices</option>
                  <option value="Desktop Only">Desktop Only</option>
                  <option value="Mobile Only">Mobile Only</option>
                </Select>
              </div>

              <div className="flex flex-wrap gap-4 pt-2">
                <label className="flex items-center gap-2 text-xs font-bold text-navy-800 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={form.is_active}
                    onChange={(e) => setForm((f) => ({ ...f, is_active: e.target.checked }))}
                    className="h-4 w-4 rounded border-navy-300 text-red-600 focus:ring-red-500"
                  />
                  Is Active & Live
                </label>
                <label className="flex items-center gap-2 text-xs font-bold text-navy-800 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={form.auto_publish}
                    onChange={(e) => setForm((f) => ({ ...f, auto_publish: e.target.checked }))}
                    className="h-4 w-4 rounded border-navy-300 text-red-600 focus:ring-red-500"
                  />
                  Auto Publish Immediately
                </label>
              </div>

              <Input
                label="Banner Tags (comma-separated)"
                value={form.banner_tags}
                onChange={(e) => setForm((f) => ({ ...f, banner_tags: e.target.value }))}
                placeholder="luxury, discount, hyderabad, monsoon"
              />
              <Textarea
                label="Internal Comments / Notes"
                value={form.internal_comments}
                onChange={(e) => setForm((f) => ({ ...f, internal_comments: e.target.value }))}
                placeholder="Notes for admin team..."
              />
            </div>
          )}

          {/* TAB 5: REAL-TIME LIVE PREVIEW */}
          {modalTab === 'preview' && (
            <div className="space-y-4 bg-slate-900 p-4 rounded-2xl text-white">
              <p className="text-xs font-bold text-red-400 uppercase tracking-wider">
                ✨ Real-Time Banner Preview on Home Page
              </p>

              <div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-red-950 via-slate-900 to-navy-950 p-6 sm:p-8 border border-white/10 shadow-2xl">
                {form.image_desktop && (
                  <img
                    src={form.image_desktop}
                    alt="Preview background"
                    className="absolute inset-0 h-full w-full object-cover opacity-30 mix-blend-overlay"
                  />
                )}
                <div className="relative z-10 max-w-xl">
                  <span className="inline-block rounded-full bg-red-600 px-3 py-1 text-[10px] font-bold uppercase tracking-widest text-white mb-2 shadow-md">
                    Featured Advertisement
                  </span>
                  <h3 className="font-display text-2xl sm:text-3xl font-extrabold text-white leading-tight">
                    {form.title || 'Your Banner Title Here'}
                  </h3>
                  {form.subtitle && <p className="mt-1.5 text-sm font-medium text-slate-300">{form.subtitle}</p>}
                  {form.description && <p className="mt-2 text-xs text-slate-400 line-clamp-2">{form.description}</p>}
                  <div className="mt-5">
                    <button
                      type="button"
                      className="rounded-xl bg-gradient-to-r from-red-600 to-rose-600 px-6 py-3 text-xs font-bold text-white shadow-lg shadow-red-600/40 hover:scale-105 transition-all"
                    >
                      {form.cta_text || 'Explore Properties'} →
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </Modal>
    </DashboardLayout>
  );
}

import { useState, useEffect } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  Users, Phone, Mail, Calendar, TrendingUp, TrendingDown,
  Clock, CheckCircle2, XCircle, AlertTriangle, Filter,
  Search, Plus, ArrowRight, ChevronDown, SlidersHorizontal,
  PhoneCall, MessageSquare, Target, Award, Flame, RefreshCw,
  Eye, Edit2, UserCheck
} from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { DashboardLayout, PageHeader, StatCard } from '../../components/dashboard-layout';
import { useLanguageContext } from '../../lib/i18n/language-context';
import { Card, Badge, Button, Input, Select, EmptyState } from '../../components/ui';
import { formatDate, formatPrice, formatNumber } from '../../lib/utils';
import { useRealtimeCount } from '../../lib/realtime';
import { getAdminSections } from '../portal/sections';

type LeadStatus = 'new' | 'assigned' | 'contacted' | 'site_visit' | 'negotiation' | 'won' | 'lost' | 'closed' | 'spam';

interface Lead {
  id: string;
  name: string | null;
  email: string | null;
  phone: string | null;
  message: string | null;
  lead_status: LeadStatus;
  priority: 'low' | 'medium' | 'high' | 'urgent';
  source: string | null;
  budget_min: number | null;
  budget_max: number | null;
  assigned_to: string | null;
  follow_up_at: string | null;
  contact_count: number;
  conversion_value: number | null;
  created_at: string;
  updated_at: string;
  property?: { id: string; title: string };
  assignee?: { id: string; first_name: string; last_name: string; phone: string; email: string };
}

interface PipelineStats {
  total: number; new: number; assigned: number; contacted: number;
  site_visit: number; negotiation: number; won: number; lost: number;
  closed: number; overdue: number; total_revenue: number; conversion_rate: number;
}

const STAGE_CONFIG: Record<LeadStatus, { label: string; color: string; bg: string; border: string; icon: React.ReactNode }> = {
  new:         { label: 'New',         color: 'text-blue-400',   bg: 'bg-blue-500/10',   border: 'border-blue-500/30',   icon: <Flame className="w-4 h-4" /> },
  assigned:    { label: 'Assigned',    color: 'text-purple-400', bg: 'bg-purple-500/10', border: 'border-purple-500/30', icon: <UserCheck className="w-4 h-4" /> },
  contacted:   { label: 'Contacted',   color: 'text-cyan-400',   bg: 'bg-cyan-500/10',   border: 'border-cyan-500/30',   icon: <Phone className="w-4 h-4" /> },
  site_visit:  { label: 'Site Visit',  color: 'text-yellow-400', bg: 'bg-yellow-500/10', border: 'border-yellow-500/30', icon: <Eye className="w-4 h-4" /> },
  negotiation: { label: 'Negotiation', color: 'text-orange-400', bg: 'bg-orange-500/10', border: 'border-orange-500/30', icon: <SlidersHorizontal className="w-4 h-4" /> },
  won:         { label: 'Won',         color: 'text-green-400',  bg: 'bg-green-500/10',  border: 'border-green-500/30',  icon: <CheckCircle2 className="w-4 h-4" /> },
  lost:        { label: 'Lost',        color: 'text-red-400',    bg: 'bg-red-500/10',    border: 'border-red-500/30',    icon: <XCircle className="w-4 h-4" /> },
  closed:      { label: 'Closed',      color: 'text-gray-400',   bg: 'bg-gray-500/10',   border: 'border-gray-500/30',   icon: <CheckCircle2 className="w-4 h-4" /> },
  spam:        { label: 'Spam',        color: 'text-gray-500',   bg: 'bg-gray-600/10',   border: 'border-gray-600/20',   icon: <XCircle className="w-4 h-4" /> },
};

const PRIORITY_CONFIG = {
  urgent: { label: 'Urgent', color: 'text-red-400',    dot: 'bg-red-500' },
  high:   { label: 'High',   color: 'text-orange-400', dot: 'bg-orange-500' },
  medium: { label: 'Medium', color: 'text-yellow-400', dot: 'bg-yellow-500' },
  low:    { label: 'Low',    color: 'text-gray-400',   dot: 'bg-gray-500' },
};

const PIPELINE_STAGES: LeadStatus[] = ['new', 'assigned', 'contacted', 'site_visit', 'negotiation', 'won'];

// ─── Lead Card Component ──────────────────────────────────────────────────────
function LeadCard({ lead, onStatusChange, onAssign }: {
  lead: Lead;
  onStatusChange: (id: string, status: LeadStatus) => void;
  onAssign: (lead: Lead) => void;
}) {
  const cfg = STAGE_CONFIG[lead.lead_status];
  const prio = PRIORITY_CONFIG[lead.priority];
  const isOverdue = lead.follow_up_at && new Date(lead.follow_up_at) < new Date() && !['won','lost','closed'].includes(lead.lead_status);

  return (
    <div 
      draggable
      onDragStart={(e) => {
        e.dataTransfer.setData('leadId', lead.id);
        e.dataTransfer.effectAllowed = 'move';
      }}
      className={`bg-slate-800/60 border rounded-xl p-4 hover:bg-slate-800/90 transition-all duration-200 cursor-grab active:cursor-grabbing group ${isOverdue ? 'border-red-500/50' : 'border-slate-700/50'}`}
    >
      {/* Header */}
      <div className="flex items-start justify-between mb-3">
        <div className="flex-1 min-w-0">
          <p className="text-white font-semibold text-sm truncate">{lead.name || 'Anonymous'}</p>
          <div className="flex items-center gap-2 mt-1">
            <span className={`inline-flex items-center gap-1 text-xs font-medium ${prio.color}`}>
              <span className={`w-1.5 h-1.5 rounded-full ${prio.dot}`}></span>
              {prio.label}
            </span>
            {isOverdue && <span className="text-xs text-red-400 font-medium flex items-center gap-1"><AlertTriangle className="w-3 h-3" />Overdue</span>}
          </div>
        </div>
        <button onClick={() => onAssign(lead)} className="opacity-0 group-hover:opacity-100 transition-opacity p-1.5 rounded-lg bg-blue-500/20 hover:bg-blue-500/40 text-blue-400">
          <Edit2 className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Contact */}
      <div className="space-y-1.5 mb-3">
        {lead.phone && (
          <a href={`tel:${lead.phone}`} className="flex items-center gap-2 text-xs text-slate-400 hover:text-blue-400 transition-colors">
            <Phone className="w-3 h-3 shrink-0" />{lead.phone}
          </a>
        )}
        {lead.email && (
          <div className="flex items-center gap-2 text-xs text-slate-500 truncate">
            <Mail className="w-3 h-3 shrink-0" />{lead.email}
          </div>
        )}
        {(lead.budget_min || lead.budget_max) && (
          <div className="flex items-center gap-2 text-xs text-slate-400">
            <Target className="w-3 h-3 shrink-0" />
            Budget: {lead.budget_max ? formatPrice(lead.budget_max) : 'N/A'}
          </div>
        )}
      </div>

      {/* Property */}
      {lead.property && (
        <div className="mb-3 p-2 rounded-lg bg-slate-700/40 border border-slate-600/30">
          <p className="text-xs text-slate-400 truncate">{lead.property.title}</p>
        </div>
      )}

      {/* Footer */}
      <div className="flex items-center justify-between pt-2 border-t border-slate-700/50">
        <span className="text-xs text-slate-500">{lead.source || 'website'}</span>
        <span className="text-xs text-slate-500">{formatDate(lead.created_at)}</span>
      </div>

      {/* Quick status actions */}
      {lead.lead_status === 'new' && (
        <div className="mt-2 flex gap-2">
          <button
            onClick={() => onStatusChange(lead.id, 'contacted')}
            className="flex-1 text-xs py-1.5 rounded-lg bg-blue-500/20 hover:bg-blue-500/40 text-blue-400 transition-colors font-medium flex items-center justify-center gap-1"
          >
            <PhoneCall className="w-3 h-3" /> Mark Contacted
          </button>
        </div>
      )}
    </div>
  );
}

// ─── Pipeline Column ──────────────────────────────────────────────────────────
function PipelineColumn({ stage, leads, onStatusChange, onAssign }: {
  stage: LeadStatus;
  leads: Lead[];
  onStatusChange: (id: string, status: LeadStatus) => void;
  onAssign: (lead: Lead) => void;
}) {
  const [isDragOver, setIsDragOver] = useState(false);
  const cfg = STAGE_CONFIG[stage];

  return (
    <div 
      className={`flex-shrink-0 w-72 rounded-xl transition-colors ${isDragOver ? 'bg-slate-800/30 ring-2 ring-slate-600 border border-dashed border-slate-500' : ''}`}
      onDragOver={(e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        setIsDragOver(true);
      }}
      onDragLeave={() => setIsDragOver(false)}
      onDrop={(e) => {
        e.preventDefault();
        setIsDragOver(false);
        const leadId = e.dataTransfer.getData('leadId');
        if (leadId) {
          onStatusChange(leadId, stage);
        }
      }}
    >
      {/* Column header */}
      <div className={`flex items-center justify-between mb-3 px-3 py-2 rounded-xl ${cfg.bg} border ${cfg.border}`}>
        <div className="flex items-center gap-2">
          <span className={cfg.color}>{cfg.icon}</span>
          <span className={`text-sm font-semibold ${cfg.color}`}>{cfg.label}</span>
        </div>
        <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${cfg.bg} ${cfg.color} border ${cfg.border}`}>
          {leads.length}
        </span>
      </div>

      {/* Cards */}
      <div className="space-y-3 max-h-[calc(100vh-320px)] overflow-y-auto pr-1">
        {leads.length === 0 ? (
          <div className="text-center py-8 text-slate-600 text-sm">No leads here</div>
        ) : (
          leads.map(lead => (
            <LeadCard key={lead.id} lead={lead} onStatusChange={onStatusChange} onAssign={onAssign} />
          ))
        )}
      </div>
    </div>
  );
}

