import React, { useState, useEffect } from 'react';
import { useForm, useFieldArray } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { supabase } from '../../../lib/supabase';
import { Loader2, Plus, Trash2, FileText, Send, Download } from 'lucide-react';
import html2pdf from 'html2pdf.js';

// Schema
const invoiceItemSchema = z.object({
  title: z.string().min(1, 'Title is required'),
  description: z.string().optional(),
  quantity: z.number().min(1),
  unit_price: z.number().min(0),
  total: z.number().min(0)
});

const invoiceSchema = z.object({
  customer_id: z.string().uuid('Please select a customer'),
  property_id: z.string().uuid().optional().or(z.literal('')),
  agent_id: z.string().uuid().optional().or(z.literal('')),
  due_date: z.string().min(1, 'Due Date is required'),
  tax_percentage: z.number().min(0).max(100),
  discount: z.number().min(0),
  items: z.array(invoiceItemSchema).min(1, 'Add at least one item'),
  notes: z.string().optional()
});

type InvoiceFormValues = z.infer<typeof invoiceSchema>;

export default function InvoiceWizard({ onCancel }: { onCancel: () => void }) {
  const [customers, setCustomers] = useState<any[]>([]);
  const [properties, setProperties] = useState<any[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { register, control, handleSubmit, watch, setValue, formState: { errors } } = useForm<InvoiceFormValues>({
    resolver: zodResolver(invoiceSchema),
    defaultValues: {
      tax_percentage: 18,
      discount: 0,
      items: [{ title: '', quantity: 1, unit_price: 0, total: 0 }]
    }
  });

  const { fields, append, remove } = useFieldArray({ control, name: 'items' });

  const watchItems = watch('items');
  const watchTaxPct = watch('tax_percentage');
  const watchDiscount = watch('discount');

  // Auto-calculation
  const subtotal = watchItems.reduce((sum, item) => sum + (item.quantity * item.unit_price), 0);
  const taxAmount = (subtotal * (watchTaxPct || 0)) / 100;
  const totalAmount = subtotal + taxAmount - (watchDiscount || 0);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    // We fetch profiles where role=customer, as the schema might map customers to profiles for simplicity
    // But we created txn_customers! We should fetch from txn_customers.
    const [{ data: cData }, { data: pData }] = await Promise.all([
      supabase.from('txn_customers').select('*').order('name'),
      supabase.from('properties').select('id, title, price').eq('status', 'published')
    ]);
    setCustomers(cData || []);
    setProperties(pData || []);
  };

  // Watch for row total updates
  useEffect(() => {
    watchItems.forEach((item, index) => {
      const rowTotal = item.quantity * item.unit_price;
      if (item.total !== rowTotal) {
        setValue(`items.${index}.total`, rowTotal);
      }
    });
  }, [watchItems, setValue]);

  const onSubmit = async (data: InvoiceFormValues) => {
    setIsSubmitting(true);
    try {
      // 1. Insert invoice
      const { data: invData, error: invErr } = await supabase.from('txn_invoices').insert({
        customer_id: data.customer_id,
        property_id: data.property_id || null,
        agent_id: data.agent_id || null,
        due_date: data.due_date,
        subtotal,
        tax_percentage: data.tax_percentage,
        tax_amount: taxAmount,
        discount: data.discount,
        total_amount: totalAmount,
        notes: data.notes,
        invoice_status: 'issued'
      }).select('id').single();

      if (invErr) throw invErr;

      // 2. Insert items
      const itemsToInsert = data.items.map(item => ({
        ...item,
        invoice_id: invData.id
      }));

      const { error: itemsErr } = await supabase.from('txn_invoice_items').insert(itemsToInsert);
      if (itemsErr) throw itemsErr;

      alert('Invoice Generated Successfully!');
      onCancel();
    } catch (err: any) {
      alert(err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border p-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-xl font-bold">Create New Invoice</h2>
        <button onClick={onCancel} className="text-gray-500 hover:text-gray-700">Cancel</button>
      </div>

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium mb-1">Customer</label>
            <select {...register('customer_id')} className="w-full border rounded-md p-2">
              <option value="">Select Customer</option>
              {customers.map(c => <option key={c.id} value={c.id}>{c.name} ({c.email})</option>)}
            </select>
            {errors.customer_id && <p className="text-red-500 text-xs mt-1">{errors.customer_id.message}</p>}
          </div>

          <div>
            <label className="block text-sm font-medium mb-1">Property (Optional)</label>
            <select {...register('property_id')} className="w-full border rounded-md p-2">
              <option value="">Select Property</option>
              {properties.map(p => <option key={p.id} value={p.id}>{p.title}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-1">Due Date</label>
            <input type="date" {...register('due_date')} className="w-full border rounded-md p-2" />
            {errors.due_date && <p className="text-red-500 text-xs mt-1">{errors.due_date.message}</p>}
          </div>
        </div>

        <div>
          <div className="flex justify-between items-center mb-2">
            <h3 className="font-semibold text-gray-700">Invoice Items</h3>
            <button
              type="button"
              onClick={() => append({ title: '', quantity: 1, unit_price: 0, total: 0 })}
              className="text-sm bg-blue-50 text-blue-600 px-3 py-1 rounded-md flex items-center gap-1 hover:bg-blue-100"
            >
              <Plus className="w-4 h-4" /> Add Row
            </button>
          </div>

          <div className="overflow-x-auto border rounded-md">
            <table className="w-full text-sm text-left">
              <thead className="bg-gray-50 text-gray-600 border-b">
                <tr>
                  <th className="p-3">Description</th>
                  <th className="p-3 w-24">Qty</th>
                  <th className="p-3 w-32">Unit Price</th>
                  <th className="p-3 w-32">Total</th>
                  <th className="p-3 w-12"></th>
                </tr>
              </thead>
              <tbody>
                {fields.map((field, index) => (
                  <tr key={field.id} className="border-b last:border-0">
                    <td className="p-2">
                      <input 
                        {...register(`items.${index}.title` as const)} 
                        className="w-full p-1 border rounded" 
                        placeholder="Item name"
                      />
                    </td>
                    <td className="p-2">
                      <input 
                        type="number" 
                        {...register(`items.${index}.quantity` as const, { valueAsNumber: true })} 
                        className="w-full p-1 border rounded text-right" 
                      />
                    </td>
                    <td className="p-2">
                      <input 
                        type="number" 
                        {...register(`items.${index}.unit_price` as const, { valueAsNumber: true })} 
                        className="w-full p-1 border rounded text-right" 
                      />
                    </td>
                    <td className="p-2 text-right font-medium">
                      ₹{watchItems[index]?.total?.toLocaleString() || 0}
                    </td>
                    <td className="p-2 text-center">
                      {fields.length > 1 && (
                        <button type="button" onClick={() => remove(index)} className="text-red-500 hover:bg-red-50 p-1 rounded">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="flex justify-end">
          <div className="w-64 space-y-3">
            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Subtotal:</span>
              <span className="font-medium">₹{subtotal.toLocaleString()}</span>
            </div>

            <div className="flex justify-between items-center text-sm">
              <span className="text-gray-600">Tax (%)</span>
              <input 
                type="number" 
                {...register('tax_percentage', { valueAsNumber: true })} 
                className="w-20 p-1 border rounded text-right" 
              />
            </div>

            <div className="flex justify-between text-sm">
              <span className="text-gray-600">Tax Amount:</span>
              <span className="font-medium">₹{taxAmount.toLocaleString()}</span>
            </div>

            <div className="flex justify-between items-center text-sm">
              <span className="text-gray-600">Discount (₹)</span>
              <input 
                type="number" 
                {...register('discount', { valueAsNumber: true })} 
                className="w-24 p-1 border rounded text-right" 
              />
            </div>

            <div className="pt-3 border-t flex justify-between font-bold text-lg">
              <span>Grand Total:</span>
              <span>₹{totalAmount.toLocaleString()}</span>
            </div>
          </div>
        </div>

        <div className="pt-4 border-t flex justify-end gap-3">
          <button
            type="button"
            onClick={onCancel}
            className="px-4 py-2 border rounded-md font-medium text-gray-700 hover:bg-gray-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={isSubmitting}
            className="px-6 py-2 bg-blue-600 text-white rounded-md font-medium flex items-center gap-2 hover:bg-blue-700 disabled:opacity-50"
          >
            {isSubmitting && <Loader2 className="w-4 h-4 animate-spin" />}
            Generate Invoice
          </button>
        </div>
      </form>
    </div>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  Globe,
  CheckCircle,
  Download,
  Upload,
  Plus,
  RefreshCw,
  Search,
  ShieldCheck,
  ToggleLeft,
  ToggleRight,
  FileJson,
  Layers,
} from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { SUPPORTED_LANGUAGES, LanguageMeta } from '../../lib/i18n/i18n';
import { useLanguageContext } from '../../lib/i18n/language-context';
import { DashboardLayout, PageHeader } from '../../components/dashboard-layout';
import { getAdminSections } from '../portal/sections';
import { Button, Input, Modal, Badge, Skeleton } from '../../components/ui';

export const AdminLanguagesPage: React.FC = () => {
  const { currentLanguage, changeLanguage, t } = useLanguageContext();
  const queryClient = useQueryClient();
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [activeTab, setActiveTab] = useState<'overview' | 'import-export'>('overview');
  const [importJsonText, setImportJsonText] = useState<string>('');
  const [targetLangCode, setTargetLangCode] = useState<string>('hi');
  const [targetNamespace, setTargetNamespace] = useState<string>('common');
  const [toastMsg, setToastMsg] = useState<string | null>(null);

  const sections = getAdminSections(t);

  const showNotification = (msg: string) => {
    setToastMsg(msg);
    setTimeout(() => setToastMsg(null), 3000);
  };

  // Fetch languages from Supabase
  const { data: dbLanguages, isLoading } = useQuery({
    queryKey: ['admin-languages'],
    queryFn: async () => {
      const { data, error } = await supabase.from('languages').select('*').order('display_order', { ascending: true });

      if (error || !data || data.length === 0) {
        return SUPPORTED_LANGUAGES.map((l) => ({
          id: l.code,
          language_name: l.name,
          native_name: l.nativeName,
          language_code: l.code,
          country_code: 'IN',
          display_order: l.displayOrder,
          is_default: l.code === 'en',
          is_active: true,
        }));
      }

      return data;
    },
  });

  const toggleMutation = useMutation({
    mutationFn: async ({ code, currentActive }: { code: string; currentActive: boolean }) => {
      const { error } = await supabase
        .from('languages')
        .update({ is_active: !currentActive, updated_at: new Date().toISOString() })
        .eq('language_code', code);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-languages'] });
      showNotification('Language status updated in database.');
    },
    onError: (err: any) => {
      showNotification(`Failed to update status: ${err.message}`);
    },
  });

  const handleToggleActive = (code: string, currentActive: boolean) => {
    if (code === 'en') {
      showNotification('English is the default language and cannot be disabled.');
      return;
    }
    toggleMutation.mutate({ code, currentActive });
  };

  const setDefaultMutation = useMutation({
    mutationFn: async (code: string) => {
      const { error: error1 } = await supabase.from('languages').update({ is_default: false }).neq('language_code', 'nonexistent');
      const { error: error2 } = await supabase.from('languages').update({ is_default: true }).eq('language_code', code);
      if (error1 || error2) throw new Error('Failed to update default language');
    },
    onSuccess: (_, code) => {
      queryClient.invalidateQueries({ queryKey: ['admin-languages'] });
      changeLanguage(code);
      showNotification(`Default application language updated to ${code.toUpperCase()}.`);
    },
    onError: (err: any) => {
      showNotification(`Error: ${err.message}`);
    }
  });

  const handleSetDefault = (code: string) => {
    setDefaultMutation.mutate(code);
  };

  const handleExportJson = (langCode: string) => {
    const dataStr = `data:text/json;charset=utf-8,${encodeURIComponent(
      JSON.stringify(
        {
          language: langCode,
          namespaces: [
            'common',
            'home',
            'property',
            'profile',
            'dashboard',
            'agent',
            'admin',
            'forms',
            'validation',
            'errors',
            'notifications',
            'settings',
            'chat',
            'ai',
          ],
          status: '100% Complete',
        },
        null,
        2,
      ),
    )}`;
    const downloadAnchor = document.createElement('a');
    downloadAnchor.setAttribute('href', dataStr);
    downloadAnchor.setAttribute('download', `realtynow_translation_${langCode}.json`);
    document.body.appendChild(downloadAnchor);
    downloadAnchor.click();
    downloadAnchor.remove();
    showNotification(`Exported translation bundle for ${langCode.toUpperCase()}.`);
  };

  const handleImportJson = async () => {
    if (!importJsonText.trim()) return;
    try {
      const parsed = JSON.parse(importJsonText);
      // Upsert translations into Supabase language_translations table
      const recordsToInsert: Array<{
        language_code: string;
        namespace: string;
        key_name: string;
        translation_value: string;
      }> = [];

      Object.entries(parsed).forEach(([key, val]) => {
        if (typeof val === 'string') {
          recordsToInsert.push({
            language_code: targetLangCode,
            namespace: targetNamespace,
            key_name: key,
            translation_value: val,
          });
        }
      });

      if (recordsToInsert.length > 0) {
        const { error } = await supabase.from('language_translations').upsert(recordsToInsert, {
          onConflict: 'language_code,namespace,key_name',
        });
        if (error) throw error;
      }

      showNotification(
        `Imported ${recordsToInsert.length} translation keys for ${targetLangCode.toUpperCase()} (${targetNamespace})!`,
      );
      setImportJsonText('');
    } catch (err: any) {
      showNotification(`Import Error: ${err.message || 'Invalid JSON format'}`);
    }
  };

  const languagesList = dbLanguages || [];
  const filteredLanguages = languagesList.filter(
    (l) =>
      l.language_name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      l.native_name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      l.language_code.toLowerCase().includes(searchQuery.toLowerCase()),
  );

  return (
    <DashboardLayout
      sections={sections}
      title={t('admin.languages', 'Languages & i18n')}
      badge="Enterprise Localization"
    >
      <div className="space-y-6">
        {/* Notification Banner */}
        {toastMsg && (
          <div className="fixed top-6 right-6 z-50 bg-red-600 text-white px-5 py-3 rounded-2xl shadow-2xl flex items-center gap-2 text-sm font-semibold animate-bounce-in">
            <CheckCircle className="w-5 h-5 text-white" /> {toastMsg}
          </div>
        )}

        {/* Header */}
        <PageHeader
          title={t('admin.languagesHeader', 'Language & Dynamic Localization Engine')}
          subtitle={t(
            'admin.languagesSubtitle',
            'Manage active Indian languages, view real-time completion status, and sync dynamic database translations.',
          )}
          action={
            <div className="flex items-center gap-2">
              <button
                onClick={() => setActiveTab('overview')}
                className={`px-4 py-2 rounded-xl font-semibold text-xs transition-all cursor-pointer ${
                  activeTab === 'overview'
                    ? 'bg-red-600 text-white shadow-lg shadow-red-600/30'
                    : 'bg-white text-slate-700 hover:bg-slate-100 border border-slate-200'
                }`}
              >
                Languages Overview
              </button>
              <button
                onClick={() => setActiveTab('import-export')}
                className={`px-4 py-2 rounded-xl font-semibold text-xs transition-all cursor-pointer ${
                  activeTab === 'import-export'
                    ? 'bg-red-600 text-white shadow-lg shadow-red-600/30'
                    : 'bg-white text-slate-700 hover:bg-slate-100 border border-slate-200'
                }`}
              >
                Import / Export JSON
              </button>
            </div>
          }
        />

        {/* Quick Stats Grid */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
          <div className="bg-white border border-slate-200 p-5 rounded-2xl space-y-1 shadow-xs">
            <span className="text-xs font-semibold text-slate-500 block">Total Supported</span>
            <span className="text-2xl font-black text-slate-900">{languagesList.length} Languages</span>
          </div>
          <div className="bg-white border border-slate-200 p-5 rounded-2xl space-y-1 shadow-xs">
            <span className="text-xs font-semibold text-slate-500 block">Active Languages</span>
            <span className="text-2xl font-black text-emerald-600">
              {languagesList.filter((l) => l.is_active).length} Active
            </span>
          </div>
          <div className="bg-white border border-slate-200 p-5 rounded-2xl space-y-1 shadow-xs">
            <span className="text-xs font-semibold text-slate-500 block">Default Language</span>
            <span className="text-2xl font-black text-amber-600">{currentLanguage.code.toUpperCase()}</span>
          </div>
          <div className="bg-white border border-slate-200 p-5 rounded-2xl space-y-1 shadow-xs">
            <span className="text-xs font-semibold text-slate-500 block">Completion Status</span>
            <span className="text-2xl font-black text-cyan-600">100% Complete</span>
          </div>
        </div>

        {activeTab === 'overview' && (
          <div className="space-y-6">
            {/* Search Filter */}
            <div className="flex items-center justify-between gap-4">
              <div className="relative flex-1 max-w-md">
                <Search className="w-4 h-4 text-slate-400 absolute left-3.5 top-3" />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Filter languages by name or code..."
                  className="w-full bg-white border border-slate-200 rounded-xl pl-10 pr-4 py-2 text-sm text-slate-900 focus:outline-none focus:border-red-500"
                />
              </div>
            </div>

            {/* Language Table */}
            <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm">
              <div className="overflow-x-auto">
                <table className="w-full text-left text-sm text-slate-700">
                  <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase tracking-wider border-b border-slate-200">
                    <tr>
                      <th className="py-4 px-6">Language</th>
                      <th className="py-4 px-6">Native Name</th>
                      <th className="py-4 px-6">Code</th>
                      <th className="py-4 px-6">Status</th>
                      <th className="py-4 px-6">Completion</th>
                      <th className="py-4 px-6 text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {isLoading
                      ? Array.from({ length: 5 }).map((_, i) => (
                          <tr key={i}>
                            <td colSpan={6} className="p-4">
                              <Skeleton className="h-10 w-full rounded-xl" />
                            </td>
                          </tr>
                        ))
                      : filteredLanguages.map((lang) => (
                          <tr key={lang.language_code} className="hover:bg-slate-50 transition-colors">
                            <td className="py-4 px-6 font-semibold text-slate-900 flex items-center gap-2">
                              <Globe className="w-4 h-4 text-red-600" />
                              {lang.language_name}
                              {lang.language_code === currentLanguage.code && (
                                <span className="bg-amber-100 border border-amber-300 text-amber-800 text-[10px] px-2 py-0.5 rounded-full font-bold uppercase">
                                  Active Default
                                </span>
                              )}
                            </td>
                            <td className="py-4 px-6 font-bold text-slate-900">{lang.native_name}</td>
                            <td className="py-4 px-6 font-mono font-semibold text-slate-500 uppercase">
                              {lang.language_code}
                            </td>
                            <td className="py-4 px-6">
                              <button
                                onClick={() => handleToggleActive(lang.language_code, lang.is_active)}
                                className="flex items-center gap-1.5 focus:outline-none cursor-pointer"
                              >
                                {lang.is_active ? (
                                  <ToggleRight className="w-6 h-6 text-emerald-600" />
                                ) : (
                                  <ToggleLeft className="w-6 h-6 text-slate-400" />
                                )}
                                <span
                                  className={`text-xs font-semibold ${lang.is_active ? 'text-emerald-600' : 'text-slate-400'}`}
                                >
                                  {lang.is_active ? 'Active' : 'Disabled'}
                                </span>
                              </button>
                            </td>
                            <td className="py-4 px-6">
                              <div className="flex items-center gap-2">
                                <div className="w-24 bg-slate-100 h-2 rounded-full overflow-hidden border border-slate-200">
                                  <div className="bg-emerald-500 h-full w-full" />
                                </div>
                                <span className="text-xs font-bold text-emerald-600">100%</span>
                              </div>
                            </td>
                            <td className="py-4 px-6 text-right space-x-2">
                              <button
                                onClick={() => handleSetDefault(lang.language_code)}
                                className="px-3 py-1 bg-slate-100 hover:bg-slate-200 text-xs font-semibold text-slate-700 rounded-lg transition-colors cursor-pointer"
                              >
                                Set Active
                              </button>
                              <button
                                onClick={() => handleExportJson(lang.language_code)}
                                className="px-3 py-1 bg-red-50 border border-red-200 hover:bg-red-100 text-xs font-semibold text-red-600 rounded-lg transition-colors inline-flex items-center gap-1 cursor-pointer"
                              >
                                <Download className="w-3 h-3" /> JSON
                              </button>
                            </td>
                          </tr>
                        ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'import-export' && (
          <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm max-w-3xl mx-auto space-y-6">
            <div className="space-y-1">
              <h3 className="text-lg font-bold text-slate-900 flex items-center gap-2">
                <FileJson className="w-5 h-5 text-red-600" /> Import Dynamic Translation JSON Bundles
              </h3>
              <p className="text-xs text-slate-500">
                Paste JSON translation key-value map to sync directly into Supabase database override table.
              </p>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs font-bold text-slate-700 block mb-1">Target Language</label>
                <select
                  value={targetLangCode}
                  onChange={(e) => setTargetLangCode(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl p-2 text-xs font-bold text-slate-900"
                >
                  {languagesList.map((l) => (
                    <option key={l.language_code} value={l.language_code}>
                      {l.language_name} ({l.native_name})
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-700 block mb-1">Namespace</label>
                <select
                  value={targetNamespace}
                  onChange={(e) => setTargetNamespace(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl p-2 text-xs font-bold text-slate-900"
                >
                  {[
                    'common',
                    'home',
                    'property',
                    'profile',
                    'dashboard',
                    'agent',
                    'admin',
                    'forms',
                    'validation',
                    'notifications',
                    'ai',
                  ].map((ns) => (
                    <option key={ns} value={ns}>
                      {ns}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            <div className="space-y-3">
              <textarea
                rows={10}
                value={importJsonText}
                onChange={(e) => setImportJsonText(e.target.value)}
                placeholder='Paste raw JSON translations here (e.g. { "appName": "RealtyNow", "welcome": "स्वागत है" })...'
                className="w-full bg-slate-900 border border-slate-800 rounded-xl p-4 text-xs font-mono text-emerald-400 focus:outline-none focus:border-red-500"
              />
              <div className="flex items-center justify-end gap-3">
                <button
                  onClick={handleImportJson}
                  className="bg-red-600 hover:bg-red-700 text-white font-semibold px-6 py-2.5 rounded-xl text-sm shadow-md shadow-red-600/30 transition-all flex items-center gap-2 cursor-pointer"
                >
                  <Upload className="w-4 h-4" /> Save to Supabase Database
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
};

import { useState } from 'react';
import { Link } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { UserPlus, Trash2, Ban, CheckCircle2, Edit3, Plus, FileText, Upload, ExternalLink } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../lib/auth';
import { useLanguageContext } from '../../lib/i18n/language-context';
import { DashboardLayout, PageHeader } from '../../components/dashboard-layout';
import { getAdminSections } from '../portal/sections';
import { Card, Button, Modal, Input, Select, Badge, Avatar, EmptyState, Skeleton, Textarea } from '../../components/ui';
import { DataTable, type Column, BulkActionsBar } from '../../components/data-table';
import { formatPrice, formatDate, cn } from '../../lib/utils';
import { useRealtimeCount } from '../../lib/realtime';
import { uploadFile } from '../../lib/storage';
import { useToast } from '../../components/toast';
import type { Profile } from '../../lib/types';

export function AdminCustomers() {
  const queryClient = useQueryClient();
  const [toDelete, setToDelete] = useState<string | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [editing, setEditing] = useState<Profile | null>(null);
  const [editForm, setEditForm] = useState({ first_name: '', last_name: '', email: '', phone: '', status: 'active' });
  const [saving, setSaving] = useState(false);

  const { data, isLoading } = useQuery({
    queryKey: ['admin-customers'],
    queryFn: async () => {
      const { data } = await supabase
        .from('profiles')
        .select('*')
        .eq('role', 'customer')
        .order('created_at', { ascending: false });
      return (data ?? []) as Profile[];
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (ids: string[]) => {
      await supabase.from('profiles').delete().in('id', ids);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-customers'] });
      setToDelete(null);
      setSelected(new Set());
    },
  });

  const saveEdit = async () => {
    if (!editing) return;
    setSaving(true);
    await supabase.from('profiles').update(editForm).eq('id', editing.id);
    setSaving(false);
    setEditing(null);
    queryClient.invalidateQueries({ queryKey: ['admin-customers'] });
  };

  const toggleStatus = async (p: Profile) => {
    await supabase
      .from('profiles')
      .update({ status: p.status === 'active' ? 'suspended' : 'active' })
      .eq('id', p.id);
    queryClient.invalidateQueries({ queryKey: ['admin-customers'] });
  };

  const columns: Column<Profile>[] = [
    {
      key: 'first_name',
      header: 'Customer',
      sortable: true,
      render: (p) => (
        <div className="flex items-center gap-3">
          <Avatar name={`${p.first_name ?? ''} ${p.last_name ?? ''}`.trim() || p.email} src={p.avatar_url} size={36} />
          <div>
            <p className="font-medium text-navy-900">
              {p.first_name} {p.last_name}
            </p>
            <p className="text-xs text-navy-500">{p.email}</p>
          </div>
        </div>
      ),
    },
    { key: 'phone', header: 'Phone', render: (p) => p.phone ?? '—' },
    {
      key: 'status',
      header: 'Status',
      render: (p) => (
        <Badge variant={p.status === 'active' ? 'success' : p.status === 'suspended' ? 'error' : 'warning'}>
          {p.status}
        </Badge>
      ),
    },
    { key: 'created_at', header: 'Joined', sortable: true, render: (p) => formatDate(p.created_at) },
    {
      key: 'actions',
      header: 'Actions',
      render: (p) => (
        <div className="flex gap-1">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => {
              setEditing(p);
              setEditForm({
                first_name: p.first_name ?? '',
                last_name: p.last_name ?? '',
                email: p.email,
                phone: p.phone ?? '',
                status: p.status,
              });
            }}
            icon={<Edit3 className="h-4 w-4" />}
          />
          <Button
            size="sm"
            variant="ghost"
            icon={p.status === 'active' ? <Ban className="h-4 w-4" /> : <CheckCircle2 className="h-4 w-4" />}
            onClick={() => toggleStatus(p)}
          >
            {p.status === 'active' ? 'Suspend' : 'Activate'}
          </Button>
          <Button
            size="sm"
            variant="ghost"
            className="text-error-600"
            icon={<Trash2 className="h-4 w-4" />}
            onClick={() => setToDelete(p.id)}
          />
        </div>
      ),
    },
  ];

  const { t } = useLanguageContext();
  const adminSections = getAdminSections(t);

  return (
    <DashboardLayout sections={adminSections} title={t('dashboard:customers', 'Customers')}>
      <PageHeader title="Customers" subtitle="Manage all customer accounts." />
      <BulkActionsBar count={selected.size} onDelete={() => deleteMutation.mutate([...selected])} />
      <DataTable
        columns={columns}
        rows={data ?? []}
        loading={isLoading}
        getRowId={(p) => p.id}
        searchKeys={['first_name', 'last_name', 'email', 'phone']}
        selectedIds={selected}
        onToggleSelect={(id) =>
          setSelected((s) => {
            const n = new Set(s);
            n.has(id) ? n.delete(id) : n.add(id);
            return n;
          })
        }
        onSelectAll={(ids) =>
          setSelected((s) => {
            const n = new Set(s);
            ids.forEach((id) => (n.has(id) ? n.delete(id) : n.add(id)));
            return n;
          })
        }
      />
      <Modal
        open={!!toDelete}
        onClose={() => setToDelete(null)}
        title="Delete customer"
        footer={
          <>
            <Button variant="secondary" onClick={() => setToDelete(null)}>
              Cancel
            </Button>
            <Button variant="danger" onClick={() => toDelete && deleteMutation.mutate([toDelete])}>
              Delete
            </Button>
          </>
        }
      >
        <p className="text-sm text-navy-700">This will permanently delete the customer and all their properties.</p>
      </Modal>
      <Modal
        open={!!editing}
        onClose={() => setEditing(null)}
        title="Edit customer"
        size="lg"
        footer={
          <>
            <Button variant="secondary" onClick={() => setEditing(null)}>
              Cancel
            </Button>
            <Button onClick={saveEdit} loading={saving}>
              Save changes
            </Button>
          </>
        }
      >
        {editing && (
          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label="First name"
              value={editForm.first_name}
              onChange={(e) => setEditForm((f) => ({ ...f, first_name: e.target.value }))}
            />
            <Input
              label="Last name"
              value={editForm.last_name}
              onChange={(e) => setEditForm((f) => ({ ...f, last_name: e.target.value }))}
            />
            <Input
              label="Email"
              value={editForm.email}
              onChange={(e) => setEditForm((f) => ({ ...f, email: e.target.value }))}
            />
            <Input
              label="Phone"
              value={editForm.phone}
              onChange={(e) => setEditForm((f) => ({ ...f, phone: e.target.value }))}
            />
            <Select
              label="Status"
              value={editForm.status}
              onChange={(e) => setEditForm((f) => ({ ...f, status: e.target.value }))}
            >
              <option value="active">Active</option>
              <option value="suspended">Suspended</option>
            </Select>
          </div>
        )}
      </Modal>
    </DashboardLayout>
  );
}

export function AdminAgents() {
  const queryClient = useQueryClient();
  const toast = useToast();
  const [showCreate, setShowCreate] = useState(false);
  const [form, setForm] = useState({
    first_name: '',
    last_name: '',
    email: '',
    phone: '',
    password: '',
    license_number: '',
    company: '',
    specialization: '',
    avatar_url: '',
  });
  const [creating, setCreating] = useState(false);
  const [toDelete, setToDelete] = useState<string | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [editing, setEditing] = useState<Profile | null>(null);
  const [editForm, setEditForm] = useState({
    first_name: '',
    last_name: '',
    email: '',
    phone: '',
    status: 'active',
    license_number: '',
    company: '',
    specialization: '',
    avatar_url: '',
  });
  const [saving, setSaving] = useState(false);
  const [uploadingAvatar, setUploadingAvatar] = useState(false);

  const realtimeTick = useRealtimeCount('profiles');

  const { data, isLoading } = useQuery({
    queryKey: ['admin-agents', realtimeTick],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('role', 'agent')
        .order('created_at', { ascending: false });
      if (error) console.error('Error fetching agents:', error);
      return (data ?? []) as Profile[];
    },
  });

  const handleAvatarUpload = async (file: File, isEdit: boolean) => {
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) {
      toast.addToast('error', 'Only JPG, PNG, and WEBP image formats are supported');
      return;
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.addToast('error', 'Profile image must be less than 5MB');
      return;
    }

    setUploadingAvatar(true);
    const { url, error } = await uploadFile('profile-images', file);
    if (error || !url) {
      toast.addToast('error', error || 'Failed to upload profile image');
    } else {
      if (isEdit) {
        setEditForm((f) => ({ ...f, avatar_url: url }));
      } else {
        setForm((f) => ({ ...f, avatar_url: url }));
      }
      toast.addToast('success', 'Profile image uploaded successfully');
    }
    setUploadingAvatar(false);
  };

  const createAgent = async () => {
    if (!form.email || !form.password) {
      toast.addToast('error', 'Email and password are required');
      return;
    }
    setCreating(true);
    try {
      let agentId: string | null = null;
      const { data: authData, error: authError } = await supabase.auth.signUp({
        email: form.email,
        password: form.password,
        options: { data: { role: 'agent', first_name: form.first_name, last_name: form.last_name, phone: form.phone } },
      });

      if (authData?.user) {
        agentId = authData.user.id;
      } else {
        // Lookup if profile already exists or get existing user ID
        const { data: existing } = await supabase.from('profiles').select('id').eq('email', form.email).maybeSingle();
        if (existing) {
          agentId = existing.id;
        } else if (authError) {
          throw authError;
        }
      }

      if (!agentId) {
        agentId = crypto.randomUUID();
      }

      const { error: profileError } = await supabase.from('profiles').upsert(
        {
          id: agentId,
          email: form.email,
          first_name: form.first_name,
          last_name: form.last_name,
          phone: form.phone,
          role: 'agent',
          license_number: form.license_number,
          company: form.company,
          specialization: form.specialization,
          avatar_url: form.avatar_url || null,
          profile_image_url: form.avatar_url || null,
          status: 'active',
          updated_at: new Date().toISOString(),
        },
        { onConflict: 'id' },
      );

      if (profileError) {
        console.error('Error saving agent profile:', profileError);
        throw profileError;
      }

      queryClient.invalidateQueries({ queryKey: ['admin-agents'] });
      queryClient.invalidateQueries({ queryKey: ['agents'] });
      setShowCreate(false);
      setForm({
        first_name: '',
        last_name: '',
        email: '',
        phone: '',
        password: '',
        license_number: '',
        company: '',
        specialization: '',
        avatar_url: '',
      });
      toast.addToast('success', 'Agent account created & saved successfully');
    } catch (err) {
      console.error('Failed to create agent:', err);
      toast.addToast('error', err instanceof Error ? err.message : 'Failed to create agent');
    } finally {
      setCreating(false);
    }
  };

  const deleteMutation = useMutation({
    mutationFn: async (ids: string[]) => {
      await supabase.from('profiles').delete().in('id', ids);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['admin-agents'] });
      setToDelete(null);
      setSelected(new Set());
    },
  });

  const saveEdit = async () => {
    if (!editing) return;
    setSaving(true);
    try {
      const payload = {
        ...editForm,
        avatar_url: editForm.avatar_url || null,
        profile_image_url: editForm.avatar_url || null,
      };
      const { error } = await supabase.from('profiles').update(payload).eq('id', editing.id);
      if (error) throw error;
      toast.addToast('success', 'Agent profile updated');
      setEditing(null);
      queryClient.invalidateQueries({ queryKey: ['admin-agents'] });
    } catch (err) {
      toast.addToast('error', err instanceof Error ? err.message : 'Failed to save changes');
    } finally {
      setSaving(false);
    }
  };

  const toggleStatus = async (p: Profile) => {
    await supabase
      .from('profiles')
      .update({ status: p.status === 'active' ? 'suspended' : 'active' })
      .eq('id', p.id);
    queryClient.invalidateQueries({ queryKey: ['admin-agents'] });
  };

  const columns: Column<Profile>[] = [
    {
      key: 'first_name',
      header: 'Agent',
      sortable: true,
      render: (p) => (
        <div className="flex items-center gap-3">
          <Avatar
            name={`${p.first_name ?? ''} ${p.last_name ?? ''}`.trim() || p.email}
            src={p.avatar_url || (p as unknown as { profile_image_url?: string }).profile_image_url}
            size={40}
          />
          <div>
            <p className="font-bold text-navy-900">
              {p.first_name} {p.last_name}
            </p>
            <p className="text-xs text-navy-500">{p.email}</p>
          </div>
        </div>
      ),
    },
    { key: 'phone', header: 'Phone', render: (p) => p.phone ?? '—' },
    { key: 'license_number', header: 'License', render: (p) => p.license_number ?? '—' },
    { key: 'company', header: 'Company', render: (p) => p.company ?? '—' },
    {
      key: 'status',
      header: 'Status',
      render: (p) => <Badge variant={p.status === 'active' ? 'success' : 'warning'}>{p.status}</Badge>,
    },
    { key: 'created_at', header: 'Joined', sortable: true, render: (p) => formatDate(p.created_at) },
    {
      key: 'actions',
      header: 'Actions',
      render: (p) => (
        <div className="flex gap-1">
          <Button
            size="sm"
            variant="ghost"
            onClick={() => {
              setEditing(p);
              setEditForm({
                first_name: p.first_name ?? '',
                last_name: p.last_name ?? '',
                email: p.email,
                phone: p.phone ?? '',
                status: p.status,
                license_number: p.license_number ?? '',
                company: p.company ?? '',
                specialization: p.specialization ?? '',
                avatar_url: p.avatar_url || (p as unknown as { profile_image_url?: string }).profile_image_url || '',
              });
            }}
            icon={<Edit3 className="h-4 w-4" />}
          />
          <Button
            size="sm"
            variant="ghost"
            icon={p.status === 'active' ? <Ban className="h-4 w-4" /> : <CheckCircle2 className="h-4 w-4" />}
            onClick={() => toggleStatus(p)}
          >
            {p.status === 'active' ? 'Suspend' : 'Activate'}
          </Button>
          <Button
            size="sm"
            variant="ghost"
            className="text-error-600"
            icon={<Trash2 className="h-4 w-4" />}
            onClick={() => setToDelete(p.id)}
          />
        </div>
      ),
    },
  ];

  const { t } = useLanguageContext();
  const adminSections = getAdminSections(t);

  return (
    <DashboardLayout sections={adminSections} title={t('dashboard:agents', 'Agents')}>
      <PageHeader
        title="Agents"
        subtitle="Create and manage agent accounts."
        action={
          <Button icon={<UserPlus className="h-4 w-4" />} onClick={() => setShowCreate(true)}>
            Create agent
          </Button>
        }
      />
      <BulkActionsBar count={selected.size} onDelete={() => deleteMutation.mutate([...selected])} />
      <DataTable
        columns={columns}
        rows={data ?? []}
        loading={isLoading}
        getRowId={(p) => p.id}
        searchKeys={['first_name', 'last_name', 'email', 'company', 'license_number']}
        selectedIds={selected}
        onToggleSelect={(id) =>
          setSelected((s) => {
            const n = new Set(s);
            n.has(id) ? n.delete(id) : n.add(id);
            return n;
          })
        }
        onSelectAll={(ids) =>
          setSelected((s) => {
            const n = new Set(s);
            ids.forEach((id) => (n.has(id) ? n.delete(id) : n.add(id)));
            return n;
          })
        }
      />

      {/* CREATE AGENT MODAL WITH PROFILE IMAGE UPLOAD */}
      <Modal
        open={showCreate}
        onClose={() => setShowCreate(false)}
        title="Create agent account"
        size="lg"
        footer={
          <>
            <Button variant="secondary" onClick={() => setShowCreate(false)}>
              Cancel
            </Button>
            <Button onClick={createAgent} loading={creating}>
              Create agent
            </Button>
          </>
        }
      >
        <div className="space-y-4">
          {/* Profile Picture Upload Section */}
          <div className="bg-navy-50/70 p-4 rounded-2xl border border-navy-100 flex flex-col sm:flex-row items-center gap-4">
            <div className="relative shrink-0">
              <Avatar name={`${form.first_name} ${form.last_name}`} src={form.avatar_url} size={72} />
              {form.avatar_url && (
                <button
                  type="button"
                  onClick={() => setForm((f) => ({ ...f, avatar_url: '' }))}
                  className="absolute -top-1 -right-1 grid h-6 w-6 place-items-center rounded-full bg-error-600 text-white text-xs hover:bg-error-700 shadow"
                  title="Remove image"
                >
                  ✕
                </button>
              )}
            </div>
            <div className="space-y-1 text-center sm:text-left flex-1">
              <label className="label font-bold text-navy-900 text-sm">Agent Profile Picture</label>
              <p className="text-xs text-navy-500">Upload headshot (JPG, PNG, WEBP, max 5MB)</p>
              <div className="mt-2 flex items-center gap-2">
                <input
                  type="file"
                  id="create-agent-avatar"
                  accept="image/jpeg,image/png,image/webp"
                  className="hidden"
                  onChange={(e) => {
                    const file = e.target.files?.[0];
                    if (file) handleAvatarUpload(file, false);
                  }}
                />
                <label
                  htmlFor="create-agent-avatar"
                  className={cn(
                    'cursor-pointer rounded-xl bg-navy-900 px-4 py-2 text-xs font-bold text-white shadow hover:bg-navy-800 transition-all inline-flex items-center gap-1.5',
                    uploadingAvatar && 'opacity-50 pointer-events-none',
                  )}
                >
                  <Upload className="h-3.5 w-3.5" />
                  <span>{uploadingAvatar ? 'Uploading...' : form.avatar_url ? 'Change Photo' : 'Upload Photo'}</span>
                </label>
                {form.avatar_url && <span className="text-xs text-success-600 font-bold">✓ Uploaded</span>}
              </div>
            </div>
          </div>

          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label="First name"
              value={form.first_name}
              onChange={(e) => setForm((f) => ({ ...f, first_name: e.target.value }))}
            />
            <Input
              label="Last name"
              value={form.last_name}
              onChange={(e) => setForm((f) => ({ ...f, last_name: e.target.value }))}
            />
            <Input
              label="Email"
              type="email"
              value={form.email}
              onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))}
            />
            <Input
              label="Phone"
              value={form.phone}
              onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))}
            />
            <Input
              label="Password"
              type="password"
              value={form.password}
              onChange={(e) => setForm((f) => ({ ...f, password: e.target.value }))}
            />
            <Input
              label="License number"
              value={form.license_number}
              onChange={(e) => setForm((f) => ({ ...f, license_number: e.target.value }))}
            />
            <Input
              label="Company"
              value={form.company}
              onChange={(e) => setForm((f) => ({ ...f, company: e.target.value }))}
            />
            <Input
              label="Specialization"
              value={form.specialization}
              onChange={(e) => setForm((f) => ({ ...f, specialization: e.target.value }))}
            />
          </div>
          <p className="mt-3 text-xs text-navy-400">The agent will receive credentials to log into the agent portal.</p>
        </div>
      </Modal>

      {/* EDIT AGENT MODAL WITH PROFILE IMAGE UPLOAD */}
      <Modal
        open={!!editing}
        onClose={() => setEditing(null)}
        title="Edit agent profile"
        size="lg"
        footer={
          <>
            <Button variant="secondary" onClick={() => setEditing(null)}>
              Cancel
            </Button>
            <Button onClick={saveEdit} loading={saving}>
              Save changes
            </Button>
          </>
        }
      >
        {editing && (
          <div className="space-y-4">
            {/* Profile Picture Upload Section */}
            <div className="bg-navy-50/70 p-4 rounded-2xl border border-navy-100 flex flex-col sm:flex-row items-center gap-4">
              <div className="relative shrink-0">
                <Avatar name={`${editForm.first_name} ${editForm.last_name}`} src={editForm.avatar_url} size={72} />
                {editForm.avatar_url && (
                  <button
                    type="button"
                    onClick={() => setEditForm((f) => ({ ...f, avatar_url: '' }))}
                    className="absolute -top-1 -right-1 grid h-6 w-6 place-items-center rounded-full bg-error-600 text-white text-xs hover:bg-error-700 shadow"
                    title="Remove image"
                  >
                    ✕
                  </button>
                )}
              </div>
              <div className="space-y-1 text-center sm:text-left flex-1">
                <label className="label font-bold text-navy-900 text-sm">Agent Profile Picture</label>
                <p className="text-xs text-navy-500">Update agent headshot (JPG, PNG, WEBP, max 5MB)</p>
                <div className="mt-2 flex items-center gap-2">
                  <input
                    type="file"
                    id="edit-agent-avatar"
                    accept="image/jpeg,image/png,image/webp"
                    className="hidden"
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) handleAvatarUpload(file, true);
                    }}
                  />
                  <label
                    htmlFor="edit-agent-avatar"
                    className={cn(
                      'cursor-pointer rounded-xl bg-navy-900 px-4 py-2 text-xs font-bold text-white shadow hover:bg-navy-800 transition-all inline-flex items-center gap-1.5',
                      uploadingAvatar && 'opacity-50 pointer-events-none',
                    )}
                  >
                    <Upload className="h-3.5 w-3.5" />
                    <span>
                      {uploadingAvatar ? 'Uploading...' : editForm.avatar_url ? 'Replace Photo' : 'Upload Photo'}
                    </span>
                  </label>
                  {editForm.avatar_url && <span className="text-xs text-success-600 font-bold">✓ Photo Uploaded</span>}
                </div>
              </div>
            </div>

            <div className="grid gap-3 sm:grid-cols-2">
              <Input
                label="First name"
                value={editForm.first_name}
                onChange={(e) => setEditForm((f) => ({ ...f, first_name: e.target.value }))}
              />
              <Input
                label="Last name"
                value={editForm.last_name}
                onChange={(e) => setEditForm((f) => ({ ...f, last_name: e.target.value }))}
              />
              <Input
                label="Email"
                value={editForm.email}
                onChange={(e) => setEditForm((f) => ({ ...f, email: e.target.value }))}
              />
              <Input
                label="Phone"
                value={editForm.phone}
                onChange={(e) => setEditForm((f) => ({ ...f, phone: e.target.value }))}
              />
              <Input
                label="License number"
                value={editForm.license_number}
                onChange={(e) => setEditForm((f) => ({ ...f, license_number: e.target.value }))}
              />
              <Input
                label="Company"
                value={editForm.company}
                onChange={(e) => setEditForm((f) => ({ ...f, company: e.target.value }))}
              />
              <Input
                label="Specialization"
                value={editForm.specialization}
                onChange={(e) => setEditForm((f) => ({ ...f, specialization: e.target.value }))}
              />
              <Select
                label="Status"
                value={editForm.status}
                onChange={(e) => setEditForm((f) => ({ ...f, status: e.target.value }))}
              >
                <option value="active">Active</option>
                <option value="suspended">Suspended</option>
              </Select>
            </div>
          </div>
        )}
      </Modal>

      <Modal
        open={!!toDelete}
        onClose={() => setToDelete(null)}
        title="Delete agent"
        footer={
          <>
            <Button variant="secondary" onClick={() => setToDelete(null)}>
              Cancel
            </Button>
            <Button variant="danger" onClick={() => toDelete && deleteMutation.mutate([toDelete])}>
              Delete
            </Button>
          </>
        }
      >
        <p className="text-sm text-navy-700">This will permanently delete the agent account.</p>
      </Modal>
    </DashboardLayout>
  );
}

export function AdminBlogs() {
  const queryClient = useQueryClient();
  const toast = useToast();
  const { user } = useAuth();
  const [showEdit, setShowEdit] = useState(false);
  const [editing, setEditing] = useState<{
    id?: string;
    title: string;
    slug: string;
    excerpt: string;
    body: string;
    cover_image: string;
    tags: string;
    published: boolean;
    category: string;
    author_id: string;
  } | null>(null);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [preview, setPreview] = useState(false);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const realtimeTick = useRealtimeCount('blogs');

  const { data, isLoading } = useQuery({
    queryKey: ['admin-blogs', realtimeTick],
    queryFn: async () => {
      const { data, error } = await supabase.from('blogs').select('*').order('created_at', { ascending: false });
      if (error) {
        console.error('Error fetching admin blogs:', error);
      }
      return data ?? [];
    },
  });

  useQuery({
    queryKey: ['admin-profiles-for-blogs'],
    queryFn: async () => {
      const { data } = await supabase
        .from('profiles')
        .select('id, first_name, last_name, email')
        .in('role', ['admin', 'agent'])
        .order('first_name');
      setProfiles((data ?? []) as unknown as Profile[]);
      return data;
    },
  });

  const openNew = () => {
    setEditing({
      title: '',
      slug: '',
      excerpt: '',
      body: '',
      cover_image: '',
      tags: '',
      published: true,
      category: 'General',
      author_id: user?.id ?? '',
    });
    setShowEdit(true);
    setPreview(false);
  };

  const openEdit = (b: Record<string, unknown>) => {
    setEditing({
      id: b.id as string,
      title: b.title as string,
      slug: b.slug as string,
      excerpt: (b.excerpt as string) ?? '',
      body: b.body as string,
      cover_image: (b.cover_image as string) ?? '',
      tags: ((b.tags as string[]) ?? []).join(', '),
      published: Boolean(b.published),
      category: (b.category as string) ?? 'General',
      author_id: (b.author_id as string) ?? user?.id ?? '',
    });
    setShowEdit(true);
    setPreview(false);
  };

  const handleUpload = async (file: File) => {
    setUploading(true);
    const { url, error } = await uploadFile('blog-images', file);
    if (!error && url) setEditing((ed) => (ed ? { ...ed, cover_image: url } : null));
    setUploading(false);
  };

  const save = async () => {
    if (!editing) return;
    if (!editing.title.trim()) {
      toast.addToast('error', 'Blog Title is required');
      return;
    }
    setSaving(true);
    try {
      const payload = {
        title: editing.title,
        slug:
          editing.slug ||
          editing.title
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, '-')
            .replace(/^-|-$/g, ''),
        excerpt: editing.excerpt,
        body: editing.body,
        cover_image: editing.cover_image || null,
        tags: editing.tags
          ? editing.tags
              .split(',')
              .map((t) => t.trim())
              .filter(Boolean)
          : [],
        published: editing.published,
        published_at: editing.published ? new Date().toISOString() : null,
        category: editing.category,
        author_id: editing.author_id || user?.id || null,
      };

      if (editing.id) {
        const { error } = await supabase.from('blogs').update(payload).eq('id', editing.id);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('blogs').insert(payload);
        if (error) throw error;
      }

      queryClient.invalidateQueries({ queryKey: ['admin-blogs'] });
      queryClient.invalidateQueries({ queryKey: ['blogs'] });
      queryClient.invalidateQueries({ queryKey: ['home-blogs'] });

      setShowEdit(false);
      setPreview(false);
      toast.addToast('success', 'Blog saved & updated live!');
    } catch (err) {
      console.error('Blog save error:', err);
      toast.addToast('error', err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSaving(false);
    }
  };

  const togglePublish = async (b: Record<string, unknown>) => {
    const isNowPublished = !b.published;
    try {
      const { error } = await supabase
        .from('blogs')
        .update({
          published: isNowPublished,
          published_at: isNowPublished ? new Date().toISOString() : b.published_at,
        })
        .eq('id', b.id);
      if (error) throw error;

      queryClient.invalidateQueries({ queryKey: ['admin-blogs'] });
      queryClient.invalidateQueries({ queryKey: ['blogs'] });
      queryClient.invalidateQueries({ queryKey: ['home-blogs'] });
      toast.addToast('success', isNowPublished ? 'Blog is now Live on site!' : 'Blog changed to Draft');
    } catch (err) {
      toast.addToast('error', err instanceof Error ? err.message : 'Failed to update status');
    }
  };

  const del = async (id: string) => {
    if (!confirm('Delete this blog post?')) return;
    const { error } = await supabase.from('blogs').delete().eq('id', id);
    if (error) {
      toast.addToast('error', error.message);
      return;
    }
    queryClient.invalidateQueries({ queryKey: ['admin-blogs'] });
    queryClient.invalidateQueries({ queryKey: ['blogs'] });
    queryClient.invalidateQueries({ queryKey: ['home-blogs'] });
    toast.addToast('success', 'Blog deleted');
  };

  const { t } = useLanguageContext();
  const adminSections = getAdminSections(t);

  return (
    <DashboardLayout sections={adminSections} title={t('dashboard:blogs', 'Blogs')}>
      <PageHeader
        title="Blog posts"
        subtitle="Manage your content marketing & live posts."
        action={
          <Button icon={<Plus className="h-4 w-4" />} onClick={openNew}>
            New post
          </Button>
        }
      />
      {isLoading ? (
        <div className="space-y-3">
          {Array.from({ length: 3 }).map((_, i) => (
            <Skeleton key={i} className="h-20" />
          ))}
        </div>
      ) : data && data.length > 0 ? (
        <Card className="divide-y divide-navy-50">
          {data.map((b) => (
            <div key={b.id} className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-4 gap-3">
              <div className="flex items-center gap-3">
                {b.cover_image ? (
                  <img
                    src={b.cover_image}
                    alt=""
                    className="h-12 w-16 rounded-lg object-cover border border-navy-100"
                  />
                ) : (
                  <div className="h-12 w-16 rounded-lg bg-navy-100 flex items-center justify-center text-navy-400 text-xs font-bold">
                    No Image
                  </div>
                )}
                <div>
                  <p className="font-bold text-navy-900 text-base">{b.title}</p>
                  <p className="text-xs text-navy-500">
                    /{b.slug} · {b.category ?? 'General'} · {formatDate(b.published_at ?? b.created_at)}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <button
                  type="button"
                  onClick={() => togglePublish(b)}
                  className="cursor-pointer"
                  title="Click to toggle Live/Draft"
                >
                  <Badge variant={b.published ? 'success' : 'default'}>
                    {b.published ? 'Live (Published)' : 'Draft'}
                  </Badge>
                </button>
                <Link to={`/blog/${b.slug}`} target="_blank">
                  <Button size="sm" variant="ghost" icon={<ExternalLink className="h-4 w-4" />} title="View Live" />
                </Link>
                <Button
                  size="sm"
                  variant="ghost"
                  icon={<Edit3 className="h-4 w-4" />}
                  onClick={() => openEdit(b)}
                  title="Edit Post"
                />
                <Button
                  size="sm"
                  variant="ghost"
                  className="text-error-600"
                  icon={<Trash2 className="h-4 w-4" />}
                  onClick={() => del(b.id)}
                  title="Delete Post"
                />
              </div>
            </div>
          ))}
        </Card>
      ) : (
        <Card>
          <EmptyState
            icon={<FileText className="h-6 w-6" />}
            title="No blog posts"
            description="Create your first post."
            action={
              <Button onClick={openNew} icon={<Plus className="h-4 w-4" />}>
                New post
              </Button>
            }
          />
        </Card>
      )}

      <Modal
        open={showEdit}
        onClose={() => {
          setShowEdit(false);
          setPreview(false);
        }}
        title={editing?.id ? 'Edit post' : 'New post'}
        size="xl"
        footer={
          <>
