        if (ap.status === 'active') stats[ap.package_id].active++;
      });
      (payments ?? []).forEach((p: any) => {
        // aggregate revenue by package via agent_package_id
      });
      return stats;
    },
  });

  const togglePackage = useMutation({
    mutationFn: async ({ id, active }: { id: string; active: boolean }) => {
