import { useAuth } from '../../lib/auth';
import { Button } from '../../components/ui';
import { uploadFile } from '../../lib/storage';
import type { KycIdType } from '../../lib/types';

const KYC_TYPES: { value: KycIdType; label: string }[] = [
  { value: 'aadhaar', label: 'Aadhaar Card' },
  { value: 'pan', label: 'PAN Card' },
  { value: 'passport', label: 'Passport' },
  { value: 'voter_id', label: 'Voter ID' },
  { value: 'driving_license', label: 'Driving License' },
];

const STEPS = [
  { id: 1, label: 'Basic Profile', icon: User, desc: 'Name, phone & photo' },
  { id: 2, label: 'Location', icon: MapPin, desc: 'Your city & address' },
  { id: 3, label: 'KYC (Optional)', icon: ShieldCheck, desc: 'ID verification' },
  { id: 4, label: 'Done!', icon: Sparkles, desc: 'Profile complete' },
];

function StepDot({ s, current }: { s: (typeof STEPS)[number]; current: number }) {
  const done = current > s.id;
  const active = current === s.id;
  return (
    <div className="flex flex-col items-center gap-1 min-w-[64px]">
      <div
        className={`h-10 w-10 rounded-full flex items-center justify-center border-2 transition-all ${done ? 'bg-success-500 border-success-500' : active ? 'bg-gold-400 border-gold-400' : 'bg-transparent border-white/20'}`}
      >
        {done ? (
          <CheckCircle2 className="h-5 w-5 text-white" />
        ) : (
          <s.icon className={`h-5 w-5 ${active ? 'text-white' : 'text-navy-400'}`} />
        )}
      </div>
      <span
        className={`text-[10px] text-center leading-tight ${active ? 'text-gold-300 font-semibold' : done ? 'text-success-400' : 'text-navy-500'}`}
      >
        {s.label}
      </span>
    </div>
  );
}

export function ProfileSetupPage() {
  const { user, profile, refreshProfile } = useAuth();
  const navigate = useNavigate();
  const [step, setStep] = useState(1);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Step 1
  const [firstName, setFirstName] = useState(profile?.first_name ?? '');
  const [lastName, setLastName] = useState(profile?.last_name ?? '');
  const [phone, setPhone] = useState(profile?.phone ?? '');
  const [bio, setBio] = useState(profile?.bio ?? '');
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [avatarPreview, setAvatarPreview] = useState(profile?.avatar_url ?? '');

  // Step 2
  const [city, setCity] = useState('');
  const [address, setAddress] = useState('');

  // Step 3 – KYC
  const [kycType, setKycType] = useState<KycIdType>('aadhaar');
  const [kycNumber, setKycNumber] = useState('');
  const [kycFront, setKycFront] = useState<File | null>(null);
  const [kycBack, setKycBack] = useState<File | null>(null);
  const [skipKyc, setSkipKyc] = useState(false);

  const handleAvatarChange = (f: File | null) => {
    setAvatarFile(f);
    if (f) setAvatarPreview(URL.createObjectURL(f));
  };

  const saveStep1 = async () => {
    if (!firstName.trim()) {
      setError('First name is required');
      return false;
    }
    if (!user) return false;
    setSaving(true);
    setError(null);
    try {
      let avatar_url = profile?.avatar_url ?? null;
      if (avatarFile) {
        const r = await uploadFile('profile-images', avatarFile, `${user.id}/avatar`);
        if (r.error) throw new Error(r.error);
        avatar_url = r.url;
      }
      const { error: e } = await supabase
        .from('profiles')
        .update({
          first_name: firstName.trim(),
          last_name: lastName.trim(),
          phone: phone.trim() || null,
          bio: bio.trim() || null,
          avatar_url,
        })
        .eq('id', user.id);
      if (e) throw new Error(e.message);
      await refreshProfile();
      return true;
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save');
      return false;
    } finally {
      setSaving(false);
    }
  };

  const saveStep2 = async () => {
    if (!user) return false;
    setSaving(true);
    setError(null);
    try {
      const { error: e } = await supabase
        .from('profiles')
        .update({
          company: city.trim() || null, // reusing company for city temporarily
        })
        .eq('id', user.id);
      // In a full implementation you'd have a separate address table
      if (e) throw new Error(e.message);
      return true;
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save');
      return false;
    } finally {
      setSaving(false);
    }
  };

  const saveKyc = async () => {
    if (skipKyc) return true;
    if (!user) return false;
    setSaving(true);
    setError(null);
    try {
      let front_url: string | null = null;
      let back_url: string | null = null;

      if (kycFront) {
        const r = await uploadFile('customer-documents', kycFront, `${user.id}/kyc-front`);
        if (r.error) throw new Error(r.error);
        front_url = r.url || r.path;
      }
      if (kycBack) {
        const r = await uploadFile('customer-documents', kycBack, `${user.id}/kyc-back`);
        if (r.error) throw new Error(r.error);
        back_url = r.url || r.path;
      }

      const { error: e } = await supabase.from('kyc_verifications').upsert(
        {
          user_id: user.id,
          id_type: kycType,
          id_number: kycNumber.trim() || null,
          front_url,
          back_url,
          status: 'pending',
        },
        { onConflict: 'user_id' },
      );
      if (e) throw new Error(e.message);
      return true;
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save KYC');
      return false;
    } finally {
      setSaving(false);
    }
  };

  const next = async () => {
    let ok = true;
    if (step === 1) ok = await saveStep1();
    if (step === 2) ok = await saveStep2();
    if (step === 3) ok = await saveKyc();
    if (ok) setStep((s) => s + 1);
  };

  const goToDashboard = () => navigate('/portal');

  return (
    <div className="min-h-screen bg-gradient-to-br from-navy-50 to-white">
      {/* Top bar */}
      <header className="border-b border-navy-100 bg-white/80 backdrop-blur-sm px-6 py-4 flex items-center justify-between sticky top-0 z-10">
        <div className="flex items-center gap-2">
          <Home className="h-5 w-5 text-navy-400" />
          <span className="text-sm font-medium text-navy-600">Profile Setup</span>
        </div>
        {step < 4 && (
          <button onClick={goToDashboard} className="text-sm text-navy-400 hover:text-navy-700 flex items-center gap-1">
            Skip for now <SkipForward className="h-3.5 w-3.5" />
          </button>
        )}
      </header>

      <div className="max-w-2xl mx-auto px-4 py-10">
        {/* Step indicators */}
        <div className="flex items-center justify-between mb-12 relative">
          {/* connector line */}
          <div className="absolute top-5 left-10 right-10 h-0.5 bg-navy-100 z-0">
            <div
              className="h-full bg-gold-400 transition-all duration-500"
              style={{ width: `${((step - 1) / (STEPS.length - 1)) * 100}%` }}
            />
          </div>
          {STEPS.map((s) => (
            <StepDot key={s.id} s={s} current={step} />
          ))}
        </div>

        <AnimatePresence mode="wait">
          <motion.div
            key={step}
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -16 }}
            transition={{ duration: 0.3 }}
          >
            {/* STEP 1 – Basic Profile */}
            {step === 1 && (
              <div className="card p-8">
                <h2 className="font-display text-2xl font-bold text-navy-900">Complete your profile</h2>
                <p className="mt-1 text-sm text-navy-500">Add a photo and your basic details to get started</p>

                {/* Avatar */}
                <div className="mt-6 flex flex-col items-center gap-3">
                  <div className="relative">
                    <div className="h-24 w-24 rounded-full bg-navy-100 overflow-hidden border-4 border-white shadow-md">
                      {avatarPreview ? (
                        <img src={avatarPreview} alt="Avatar" className="h-full w-full object-cover" />
                      ) : (
                        <div className="h-full w-full flex items-center justify-center">
                          <User className="h-10 w-10 text-navy-400" />
                        </div>
                      )}
                    </div>
                    <label className="absolute -bottom-1 -right-1 h-8 w-8 rounded-full bg-gold-400 flex items-center justify-center cursor-pointer shadow hover:bg-gold-500 transition-colors">
                      <Camera className="h-4 w-4 text-white" />
                      <input
                        type="file"
                        accept="image/*"
                        className="sr-only"
                        onChange={(e) => handleAvatarChange(e.target.files?.[0] ?? null)}
                      />
                    </label>
                  </div>
                  {avatarPreview && (
                    <button
                      onClick={() => {
                        setAvatarFile(null);
                        setAvatarPreview('');
                      }}
                      className="text-xs text-error-500 hover:underline"
                    >
                      Remove photo
                    </button>
                  )}
                </div>

                <div className="mt-6 space-y-4">
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-sm font-medium text-navy-700 mb-1.5">First Name *</label>
                      <input
                        value={firstName}
                        onChange={(e) => setFirstName(e.target.value)}
                        className="input w-full"
                        placeholder="Priya"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-navy-700 mb-1.5">Last Name</label>
                      <input
                        value={lastName}
                        onChange={(e) => setLastName(e.target.value)}
                        className="input w-full"
                        placeholder="Sharma"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-navy-700 mb-1.5">
                      <Phone className="inline h-3.5 w-3.5 mr-1" />
                      Mobile Number
                    </label>
                    <input
                      type="tel"
                      value={phone}
                      onChange={(e) => setPhone(e.target.value)}
                      className="input w-full"
                      placeholder="+91 98000 00000"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-navy-700 mb-1.5">About You (optional)</label>
                    <textarea
                      rows={2}
                      value={bio}
                      onChange={(e) => setBio(e.target.value)}
                      className="input w-full resize-none"
                      placeholder="Tell us a little about yourself…"
                    />
                  </div>
                </div>
                {error && <p className="mt-3 text-sm text-error-600">{error}</p>}
              </div>
            )}

            {/* STEP 2 – Location */}
            {step === 2 && (
              <div className="card p-8">
                <h2 className="font-display text-2xl font-bold text-navy-900">Your Location</h2>
                <p className="mt-1 text-sm text-navy-500">Help us show properties relevant to you</p>
                <div className="mt-6 space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-navy-700 mb-1.5">
                      <MapPin className="inline h-3.5 w-3.5 mr-1" />
                      City
                    </label>
                    <input
                      value={city}
                      onChange={(e) => setCity(e.target.value)}
                      className="input w-full"
                      placeholder="Hyderabad"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-navy-700 mb-1.5">Area / Locality (optional)</label>
                    <input
                      value={address}
                      onChange={(e) => setAddress(e.target.value)}
                      className="input w-full"
                      placeholder="Banjara Hills"
                    />
                  </div>
                  <div className="rounded-xl border border-navy-100 bg-navy-50 p-4 text-sm text-navy-600">
                    <MapPin className="h-4 w-4 text-gold-500 mb-1" />
                    <p className="font-medium text-navy-800">Why we ask this</p>
                    <p className="mt-0.5 text-xs">
                      We use your location to personalize property recommendations and connect you with local agents.
                    </p>
                  </div>
                </div>
                {error && <p className="mt-3 text-sm text-error-600">{error}</p>}
              </div>
            )}

            {/* STEP 3 – KYC */}
            {step === 3 && (
              <div className="card p-8">
                <div className="flex items-start justify-between gap-3 mb-1">
                  <h2 className="font-display text-2xl font-bold text-navy-900">Identity Verification</h2>
                  <span className="badge bg-navy-100 text-navy-600 text-xs">Optional</span>
                </div>
                <p className="text-sm text-navy-500">
                  Verify your identity to get a trust badge and unlock premium features
                </p>

                {/* Toggle skip */}
                <div className="mt-5 flex items-center gap-3 p-4 rounded-xl border border-navy-100 bg-navy-50">
                  <input
                    type="checkbox"
                    id="skip-kyc"
                    checked={skipKyc}
                    onChange={(e) => setSkipKyc(e.target.checked)}
                    className="h-4 w-4 rounded border-navy-300 text-gold-500 focus:ring-gold-400"
                  />
                  <label htmlFor="skip-kyc" className="text-sm text-navy-700 cursor-pointer">
                    Skip KYC for now — I'll do this later from my profile settings
                  </label>
                </div>

                {!skipKyc && (
                  <div className="mt-5 space-y-4">
                    <div>
                      <label className="block text-sm font-medium text-navy-700 mb-1.5">Document Type</label>
                      <select
                        value={kycType}
                        onChange={(e) => setKycType(e.target.value as KycIdType)}
                        className="input w-full"
                      >
                        {KYC_TYPES.map((t) => (
                          <option key={t.value} value={t.value}>
                            {t.label}
                          </option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-navy-700 mb-1.5">
                        Document Number (optional)
                      </label>
                      <input
                        value={kycNumber}
                        onChange={(e) => setKycNumber(e.target.value)}
                        className="input w-full"
                        placeholder="Enter your document number"
                      />
                    </div>

                    {/* Front upload */}
                    <div>
                      <label className="block text-sm font-medium text-navy-700 mb-1.5">Upload Front Side *</label>
                      <label className="flex items-center justify-center gap-2 rounded-xl border-2 border-dashed border-navy-200 bg-navy-50 px-4 py-5 cursor-pointer hover:border-gold-400 hover:bg-gold-50/30 transition-all">
                        <input
                          type="file"
                          accept="image/*,.pdf"
                          className="sr-only"
                          onChange={(e) => setKycFront(e.target.files?.[0] ?? null)}
                        />
                        {kycFront ? (
                          <div className="flex items-center gap-2 text-success-600">
                            <CheckCircle2 className="h-5 w-5" />
                            <span className="text-sm">{kycFront.name}</span>
                            <button
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                setKycFront(null);
                              }}
                              className="text-navy-400 hover:text-error-500"
                            >
                              <X className="h-4 w-4" />
                            </button>
                          </div>
                        ) : (
                          <>
                            <Upload className="h-5 w-5 text-navy-400" />
                            <span className="text-sm text-navy-500">Click to upload front</span>
                          </>
                        )}
                      </label>
                    </div>

                    {/* Back upload */}
                    <div>
                      <label className="block text-sm font-medium text-navy-700 mb-1.5">
                        Upload Back Side (if applicable)
                      </label>
                      <label className="flex items-center justify-center gap-2 rounded-xl border-2 border-dashed border-navy-200 bg-navy-50 px-4 py-5 cursor-pointer hover:border-gold-400 hover:bg-gold-50/30 transition-all">
                        <input
                          type="file"
                          accept="image/*,.pdf"
                          className="sr-only"
                          onChange={(e) => setKycBack(e.target.files?.[0] ?? null)}
                        />
                        {kycBack ? (
                          <div className="flex items-center gap-2 text-success-600">
                            <CheckCircle2 className="h-5 w-5" />
                            <span className="text-sm">{kycBack.name}</span>
                            <button
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                setKycBack(null);
                              }}
                              className="text-navy-400 hover:text-error-500"
                            >
                              <X className="h-4 w-4" />
                            </button>
                          </div>
                        ) : (
                          <>
                            <Upload className="h-5 w-5 text-navy-400" />
                            <span className="text-sm text-navy-500">Click to upload back (optional)</span>
                          </>
                        )}
                      </label>
                    </div>

                    <div className="rounded-xl border border-gold-200 bg-gold-50 p-3 text-xs text-gold-800 flex items-start gap-2">
                      <ShieldCheck className="h-4 w-4 mt-0.5 flex-shrink-0 text-gold-600" />
                      <p>
                        Your documents are encrypted and only accessible by our verification team. KYC review takes 1–2
                        business days.
                      </p>
                    </div>
                  </div>
                )}
                {error && <p className="mt-3 text-sm text-error-600">{error}</p>}
              </div>
            )}

            {/* STEP 4 – Done */}
            {step === 4 && (
              <div className="card p-10 text-center">
                <motion.div
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  transition={{ type: 'spring', stiffness: 200, damping: 15 }}
                  className="h-24 w-24 mx-auto rounded-full bg-gradient-to-br from-gold-400 to-gold-600 flex items-center justify-center mb-6 shadow-lg"
                >
                  <CheckCircle2 className="h-12 w-12 text-white" />
                </motion.div>
                <h2 className="font-display text-2xl font-bold text-navy-900">Profile Complete! 🎉</h2>
                <p className="mt-2 text-navy-500">
                  You're all set,{' '}
                  <span className="font-semibold text-navy-700">{firstName || profile?.first_name}</span>! Start
                  exploring properties or list your own.
                </p>
                <div className="mt-6 grid grid-cols-3 gap-3">
                  {[
                    { icon: Home, label: 'Browse Properties', to: '/search' },
                    { icon: Sparkles, label: 'AI Recommendations', to: '/portal' },
                    { icon: CreditCard, label: 'Pick a Plan', to: '/portal/subscription' },
                  ].map(({ icon: Icon, label, to }) => (
                    <Link
                      key={to}
                      to={to}
                      className="rounded-xl border border-navy-100 bg-navy-50 p-4 text-center hover:border-gold-300 hover:bg-gold-50/30 transition-all group"
                    >
                      <Icon className="h-6 w-6 text-navy-400 mx-auto mb-2 group-hover:text-gold-500 transition-colors" />
                      <p className="text-xs text-navy-600 font-medium">{label}</p>
                    </Link>
                  ))}
                </div>
                <Button
                  variant="gold"
                  size="lg"
                  className="mt-8 w-full"
                  onClick={goToDashboard}
                  icon={<Sparkles className="h-4 w-4" />}
                >
                  Go to My Dashboard
                </Button>
              </div>
            )}
          </motion.div>
        </AnimatePresence>

        {/* Navigation */}
        {step < 4 && (
          <div className="mt-6 flex items-center justify-between">
            {step > 1 ? (
              <button
                onClick={() => setStep((s) => s - 1)}
                className="flex items-center gap-2 text-sm text-navy-500 hover:text-navy-800 transition-colors"
              >
                <ArrowLeft className="h-4 w-4" /> Back
              </button>
            ) : (
              <div />
            )}
            <Button variant="gold" size="lg" loading={saving} icon={<ArrowRight className="h-4 w-4" />} onClick={next}>
              {step === 3 ? (skipKyc ? 'Complete Setup' : 'Submit KYC') : 'Continue'}
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useQuery, useMutation } from '@tanstack/react-query';
import { DashboardLayout, PageHeader } from '../../components/dashboard-layout';
import { supabase } from '../../lib/supabase';
import { queryClient } from '../../lib/queryClient';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../../lib/auth';
import { getPortalSections } from '../../lib/dashboard-links';
import { Wallet as WalletIcon, ArrowDownRight, ArrowUpRight, History, IndianRupee } from 'lucide-react';
import { format } from 'date-fns';
import { toast } from 'sonner';

export default function AgentWallet() {
  const { t } = useTranslation();
  const { user } = useAuth();
  const [isWithdrawModalOpen, setIsWithdrawModalOpen] = useState(false);
  const [withdrawAmount, setWithdrawAmount] = useState('');
  const [bankAccount, setBankAccount] = useState('');
  const [ifsc, setIfsc] = useState('');

  const { data: wallet, isLoading: walletLoading } = useQuery({
    queryKey: ['portal-wallet', user?.id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('wallets')
        .select('*')
        .eq('user_id', user!.id)
        .single();
      if (error && error.code !== 'PGRST116') throw error;
      return data;
    },
    enabled: !!user,
  });

  const { data: transactions, isLoading: txLoading } = useQuery({
    queryKey: ['portal-wallet-transactions', wallet?.id],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('wallet_transactions')
        .select('*')
        .eq('wallet_id', wallet!.id)
        .order('created_at', { ascending: false });
      if (error) throw error;
      return data;
    },
    enabled: !!wallet,
  });

  const withdrawMutation = useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.rpc('fn_request_withdrawal', {
        p_amount: Number(withdrawAmount),
        p_bank_details: { account: bankAccount, ifsc },
      });
      if (error) throw error;
      if (!data.success) throw new Error(data.message);
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['portal-wallet'] });
      queryClient.invalidateQueries({ queryKey: ['portal-wallet-transactions'] });
      setIsWithdrawModalOpen(false);
      setWithdrawAmount('');
      toast.success('Withdrawal requested successfully');
    },
    onError: (err: any) => toast.error(err.message),
  });

  const handleWithdrawSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (Number(withdrawAmount) > (wallet?.balance || 0)) {
      toast.error('Insufficient balance');
      return;
    }
    withdrawMutation.mutate();
  };

  return (
    <DashboardLayout sections={getPortalSections(t)} title="My Wallet" badge="Agent">
      <PageHeader title="My Wallet" subtitle="Manage your credits, commissions, and withdrawals." />

      <div className="mb-8 rounded-2xl bg-gradient-to-r from-navy-900 to-navy-800 p-8 text-white shadow-xl relative overflow-hidden">
        <div className="absolute top-0 right-0 opacity-10 p-4">
          <WalletIcon className="w-48 h-48" />
        </div>
        <div className="relative z-10">
          <h2 className="text-navy-200 font-medium tracking-wide uppercase text-sm mb-2">Available Balance</h2>
          <div className="flex items-center gap-2 mb-6">
            <IndianRupee className="w-8 h-8 text-primary-400" />
            <span className="text-5xl font-bold">{wallet?.balance || '0.00'}</span>
          </div>
          <button
            onClick={() => setIsWithdrawModalOpen(true)}
            disabled={!wallet || wallet.balance <= 0}
            className="rounded-xl bg-primary-600 px-6 py-3 font-semibold hover:bg-primary-500 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            Request Withdrawal
          </button>
        </div>
      </div>

      <div className="rounded-xl border border-navy-200 bg-white shadow-sm">
        <div className="border-b border-navy-200 p-4 flex items-center gap-2">
          <History className="w-5 h-5 text-navy-500" />
          <h3 className="font-bold">Transaction History</h3>
        </div>
        <table className="w-full text-left text-sm">
          <thead className="bg-navy-50">
            <tr>
              <th className="p-4 font-medium">Type</th>
              <th className="p-4 font-medium">Description</th>
              <th className="p-4 font-medium">Date</th>
              <th className="p-4 font-medium text-right">Amount</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-navy-100">
            {transactions?.map((tx) => (
              <tr key={tx.id} className="hover:bg-navy-50/50">
                <td className="p-4">
                  {tx.transaction_type === 'credit' ? (
                    <span className="flex items-center gap-1 text-green-600 font-medium bg-green-50 px-2 py-1 rounded-full w-max text-xs uppercase">
                      <ArrowDownRight className="w-3 h-3" /> Credit
                    </span>
                  ) : (
                    <span className="flex items-center gap-1 text-red-600 font-medium bg-red-50 px-2 py-1 rounded-full w-max text-xs uppercase">
                      <ArrowUpRight className="w-3 h-3" /> Debit
                    </span>
                  )}
                </td>
                <td className="p-4">{tx.description}</td>
                <td className="p-4 text-navy-500">{format(new Date(tx.created_at), 'MMM dd, yyyy HH:mm')}</td>
                <td className={`p-4 text-right font-bold ${tx.transaction_type === 'credit' ? 'text-green-600' : 'text-navy-900'}`}>
                  {tx.transaction_type === 'credit' ? '+' : '-'}₹{tx.amount}
                </td>
              </tr>
            ))}
            {(!transactions || transactions.length === 0) && (
              <tr>
                <td colSpan={4} className="p-8 text-center text-navy-500">No transactions found.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {isWithdrawModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="w-full max-w-md rounded-xl bg-white p-6 shadow-xl">
            <h2 className="mb-4 text-xl font-bold">Request Withdrawal</h2>
            <form onSubmit={handleWithdrawSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Amount to Withdraw (₹)</label>
                <input
                  type="number"
                  value={withdrawAmount}
                  onChange={(e) => setWithdrawAmount(e.target.value)}
                  max={wallet?.balance}
                  required
                  className="w-full rounded border p-2"
                />
                <p className="text-xs text-navy-500 mt-1">Available: ₹{wallet?.balance}</p>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Bank Account Number</label>
                <input
                  type="text"
                  value={bankAccount}
                  onChange={(e) => setBankAccount(e.target.value)}
                  required
                  className="w-full rounded border p-2"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">IFSC Code</label>
                <input
                  type="text"
                  value={ifsc}
                  onChange={(e) => setIfsc(e.target.value)}
                  required
                  className="w-full rounded border p-2 uppercase"
                />
              </div>
              <div className="flex justify-end gap-2 mt-6">
                <button type="button" onClick={() => setIsWithdrawModalOpen(false)} className="rounded px-4 py-2 hover:bg-gray-100">
                  Cancel
                </button>
                <button type="submit" disabled={withdrawMutation.isPending} className="rounded bg-primary-600 px-4 py-2 text-white hover:bg-primary-700 disabled:opacity-50">
                  {withdrawMutation.isPending ? 'Processing...' : 'Submit Request'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </DashboardLayout>
  );
}

import React, { useState } from 'react';
import {
  Sparkles,
  Bot,
  Search,
  FileText,
  Languages,
  TrendingUp,
  UserCheck,
  Zap,
  Mic,
  Copy,
  Check,
  Building,
  MapPin,
  ArrowRight,
  ShieldCheck,
} from 'lucide-react';
import { callAI, AITask } from '../../lib/ai';
import { VoiceSearchButton } from '../../components/voice-search-button';
import { useLanguageContext } from '../../lib/i18n/language-context';
import { useSearchParams, useNavigate } from 'react-router-dom';

export const AIHubPage: React.FC = () => {
  const { t } = useLanguageContext();
  const [searchParams, setSearchParams] = useSearchParams();
  
  const defaultTab = searchParams.get('tab') as 'assistant' | 'smart-search' | 'recommendations' | 'generator' | 'lead-summary' | 'translation' | 'market';
  
  const [activeTab, setActiveTab] = useState<
    'assistant' | 'smart-search' | 'recommendations' | 'generator' | 'lead-summary' | 'translation' | 'market'
  >(defaultTab || 'assistant');
  const [loading, setLoading] = useState<boolean>(false);
  const [copied, setCopied] = useState<boolean>(false);

  // Chat State
  const [chatInput, setChatInput] = useState<string>('');
  const [messages, setMessages] = useState<Array<{ role: 'user' | 'assistant'; text: string }>>([
    {
      role: 'assistant',
      text: 'Hello! I am your RealtyNow AI Property Advisor. Ask me anything about property prices, buying vs renting in India, home loans, or top localities!',
    },
  ]);

  // Smart Search State
  const [searchQuery, setSearchQuery] = useState<string>(
    'Looking for a 3 BHK luxury apartment in Worli Mumbai under 2.5 Cr with swimming pool',
  );
  const [parsedFilter, setParsedFilter] = useState<Record<string, unknown> | null>(null);

  // Generator State
  const [genTitle, setGenTitle] = useState<string>('Luxury 3BHK Apartment');
  const [genCity, setGenCity] = useState<string>('Mumbai');
  const [genLocality, setGenLocality] = useState<string>('Worli');
  const [genType, setGenType] = useState<string>('Residential Apartment');
  const [genBedrooms, setGenBedrooms] = useState<number>(3);
  const [genOutput, setGenOutput] = useState<{ title?: string; description?: string; seo?: string } | null>(null);

  // Lead Summary State
  const [leadText, setLeadText] = useState<string>(
    'Hi, I am Rahul Verma interested in buying a 3BHK in HSR Layout Bengaluru. My budget is around 1.2 Crore. Looking for ready-to-move properties with bank pre-approval ready.',
  );
  const [leadSummaryOutput, setLeadSummaryOutput] = useState<string>('');

  // Translation State
  const [transText, setTransText] = useState<string>(
    'Spacious 3 BHK sea-facing apartment in Worli with modern amenities, gated security, and covered parking.',
  );
  const [transLang, setTransLang] = useState<string>('Hindi');
  const [transOutput, setTransOutput] = useState<string>('');

  // Market Insights State
  const [marketCity, setMarketCity] = useState<string>('Bengaluru');
  const [marketLocality, setMarketLocality] = useState<string>('HSR Layout');
  const [marketOutput, setMarketOutput] = useState<string>('');

  // Recommendation State
  const [recInput, setRecInput] = useState<string>(
    '2BHK apartment in IT corridors under 80 Lakhs with metro connectivity',
  );
  const [recOutput, setRecOutput] = useState<string>('');

  // Handlers
  const handleChatSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!chatInput.trim() || loading) return;

    const userText = chatInput.trim();
    setMessages((prev) => [...prev, { role: 'user', text: userText }]);
    setChatInput('');
    setLoading(true);

    try {
      const res = await callAI('chat', { message: userText });
      setMessages((prev) => [...prev, { role: 'assistant', text: res }]);
    } catch {
      setMessages((prev) => [...prev, { role: 'assistant', text: 'Sorry, I encountered an issue. Please try again.' }]);
    } finally {
      setLoading(false);
    }
  };

  const handleSmartSearch = async () => {
    setLoading(true);
    try {
      const res = await callAI('parse_search', { query: searchQuery });
      try {
        setParsedFilter(JSON.parse(res));
      } catch {
        setParsedFilter({ raw: res });
      }
    } catch {
      setParsedFilter({ error: 'Failed to parse query.' });
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateCopy = async () => {
    setLoading(true);
    try {
      const desc = await callAI('description', {
        title: genTitle,
        city: genCity,
        locality: genLocality,
        type: genType,
        bedrooms: genBedrooms,
      });
      const title = await callAI('title', {
        city: genCity,
        locality: genLocality,
        type: genType,
        bedrooms: genBedrooms,
        purpose: 'Sale',
      });
      const seo = await callAI('seo', {
        title: genTitle,
        city: genCity,
        locality: genLocality,
      });
      setGenOutput({ title, description: desc, seo });
    } finally {
      setLoading(false);
    }
  };

  const handleSummarizeLead = async () => {
    setLoading(true);
    try {
      const res = await callAI('lead_summary', { message: leadText });
      setLeadSummaryOutput(res);
    } finally {
      setLoading(false);
    }
  };

  const handleTranslate = async () => {
    setLoading(true);
    try {
      const res = await callAI('translate', { text: transText, language: transLang });
      setTransOutput(res);
    } finally {
      setLoading(false);
    }
  };

  const handleMarketInsights = async () => {
    setLoading(true);
    try {
      const res = await callAI('market_insights', { city: marketCity, locality: marketLocality });
      setMarketOutput(res);
    } finally {
      setLoading(false);
    }
  };

  const handleRecommendations = async () => {
    setLoading(true);
    try {
      const res = await callAI('recommend', { message: recInput });
      setRecOutput(res);
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white py-10 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto space-y-8">
        {/* Page Header */}
        <div className="text-center space-y-4">
          <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-red-500/10 border border-red-500/30 text-red-400 text-xs font-semibold uppercase tracking-wider">
            <Sparkles className="w-4 h-4 text-red-400" /> {t('ai.phase1', 'Phase 1 — AI Foundation Suite')}
          </div>
          <h1 className="text-3xl sm:text-5xl font-extrabold text-white tracking-tight">
            RealtyNow{' '}
            <span className="text-transparent bg-clip-text bg-gradient-to-r from-red-500 via-rose-400 to-amber-400">
              {t('ai.subtitle', 'AI Property Advisor')}
            </span>
          </h1>
          <p className="text-slate-400 max-w-2xl mx-auto text-sm sm:text-base">
            {t(
              'ai.description',
              'Powered by OpenRouter AI (GPT-4o Mini). Search using voice, generate property copy, summarize customer leads, and analyze locality price trends in real-time.',
            )}
          </p>

          <div className="flex items-center justify-center gap-2 text-xs text-emerald-400 bg-emerald-950/40 border border-emerald-500/30 px-3 py-1.5 rounded-lg w-fit mx-auto">
            <ShieldCheck className="w-4 h-4 text-emerald-400" />{' '}
            {t('ai.activeStatus', 'Active & Connected to OpenRouter AI Engine')}
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex items-center justify-center gap-2 overflow-x-auto pb-2 scrollbar-none border-b border-slate-800">
          {[
            { id: 'assistant', label: 'AI Assistant', icon: Bot },
            { id: 'smart-search', label: 'Smart Search', icon: Search },
            { id: 'recommendations', label: 'Recommendations', icon: Zap },
            { id: 'generator', label: 'Copy Generator', icon: FileText },
            { id: 'lead-summary', label: 'Lead Summary', icon: UserCheck },
            { id: 'translation', label: 'AI Translation', icon: Languages },
            { id: 'market', label: 'Market Insights', icon: TrendingUp },
          ].map((tab) => {
            const Icon = tab.icon;
            const active = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => {
                  setActiveTab(tab.id as typeof activeTab);
                  setSearchParams({ tab: tab.id });
                }}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl font-semibold text-xs sm:text-sm transition-all whitespace-nowrap ${
                  active
                    ? 'bg-red-600 text-white shadow-lg shadow-red-600/30 scale-105'
                    : 'bg-slate-900/80 text-slate-400 hover:text-white hover:bg-slate-800'
                }`}
              >
                <Icon className={`w-4 h-4 ${active ? 'text-white' : 'text-slate-400'}`} />
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* TAB 1: AI Assistant Chat */}
        {activeTab === 'assistant' && (
          <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl max-w-4xl mx-auto space-y-6">
            <div className="flex items-center justify-between border-b border-slate-800 pb-4">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <Bot className="w-5 h-5 text-red-500" /> Interactive AI Real Estate Assistant
              </h3>
              <span className="text-xs text-slate-400">Ask in English or Voice</span>
            </div>

            <div className="h-80 overflow-y-auto space-y-4 pr-2">
              {messages.map((m, idx) => (
                <div key={idx} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div
                    className={`max-w-md p-4 rounded-2xl text-sm leading-relaxed ${
                      m.role === 'user'
                        ? 'bg-red-600 text-white rounded-br-none'
                        : 'bg-slate-800/90 text-slate-200 border border-slate-700/60 rounded-bl-none'
                    }`}
                  >
                    {m.text}
                  </div>
                </div>
              ))}
              {loading && (
                <div className="flex justify-start">
                  <div className="bg-slate-800 text-slate-400 px-4 py-3 rounded-2xl text-xs flex items-center gap-2">
                    <Sparkles className="w-4 h-4 text-amber-400 animate-spin" /> Thinking...
                  </div>
                </div>
              )}
            </div>

            <form onSubmit={handleChatSubmit} className="flex items-center gap-2 pt-2">
              <input
                type="text"
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                placeholder="Ask about properties in Mumbai, buying guide, home loans..."
                className="flex-1 bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white placeholder-slate-500 focus:outline-none focus:border-red-500"
              />
              <VoiceSearchButton onResult={(text) => setChatInput(text)} />
              <button
                type="submit"
                disabled={loading || !chatInput.trim()}
                className="bg-red-600 hover:bg-red-500 disabled:opacity-50 text-white font-semibold px-5 py-3 rounded-xl transition-all text-sm flex items-center gap-1.5"
              >
                Send <ArrowRight className="w-4 h-4" />
              </button>
            </form>
          </div>
        )}

        {/* TAB 2: AI Smart Search Filter Extractor */}
        {activeTab === 'smart-search' && (
          <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl max-w-3xl mx-auto space-y-6">
            <div className="space-y-1">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <Search className="w-5 h-5 text-red-500" /> AI Natural Language Search Extractor
              </h3>
              <p className="text-xs text-slate-400">
                Type freeform natural text to automatically parse city, BHK, budget, and property types.
              </p>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-semibold text-slate-300">Natural Language Search Query:</label>
              <div className="flex gap-2">
                <textarea
                  rows={3}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="flex-1 bg-slate-950 border border-slate-800 rounded-xl p-3 text-sm text-white focus:outline-none focus:border-red-500"
                />
                <VoiceSearchButton onResult={(t) => setSearchQuery(t)} />
              </div>
              <button
                onClick={handleSmartSearch}
                disabled={loading}
                className="bg-gradient-to-r from-red-600 to-rose-600 text-white font-semibold px-6 py-2.5 rounded-xl text-sm hover:from-red-500 hover:to-rose-500 transition-all flex items-center gap-2"
              >
                <Sparkles className="w-4 h-4" /> Extract Search Filters
              </button>
            </div>

            {parsedFilter && (
              <div className="bg-slate-950 border border-slate-800 rounded-xl p-4 space-y-2">
                <h4 className="text-xs font-bold text-emerald-400 uppercase tracking-wider">
                  Parsed Filter Output (JSON):
                </h4>
                <pre className="text-xs text-slate-200 overflow-x-auto bg-slate-900 p-3 rounded-lg border border-slate-800">
                  {JSON.stringify(parsedFilter, null, 2)}
                </pre>
              </div>
            )}
          </div>
        )}

        {/* TAB 3: Recommendations */}
        {activeTab === 'recommendations' && (
          <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl max-w-3xl mx-auto space-y-6">
            <div className="space-y-1">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <Zap className="w-5 h-5 text-red-500" /> AI Property Matchmaker & Locality Recommendations
              </h3>
              <p className="text-xs text-slate-400">
                Receive customized locality and property recommendations based on your preferences.
              </p>
            </div>

            <div className="space-y-3">
              <input
                type="text"
                value={recInput}
                onChange={(e) => setRecInput(e.target.value)}
                placeholder="e.g. 3 BHK in IT hubs with high appreciation under 1.5 Cr"
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-sm text-white focus:outline-none focus:border-red-500"
              />
              <button
                onClick={handleRecommendations}
                disabled={loading}
                className="bg-red-600 text-white font-semibold px-6 py-2.5 rounded-xl text-sm hover:bg-red-500 transition-all flex items-center gap-2"
              >
                <Sparkles className="w-4 h-4" /> Generate Recommendations
              </button>
            </div>

            {recOutput && (
              <div className="bg-slate-950 border border-slate-800 rounded-xl p-4 text-sm text-slate-200 whitespace-pre-line leading-relaxed">
                {recOutput}
              </div>
            )}
          </div>
        )}

        {/* TAB 4: Copy Generator */}
        {activeTab === 'generator' && (
          <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl max-w-4xl mx-auto space-y-6">
            <div className="space-y-1">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <FileText className="w-5 h-5 text-red-500" /> AI Property Copy & SEO Generator
              </h3>
              <p className="text-xs text-slate-400">
                Generate high-converting property titles, descriptions, and SEO meta copy for your listings.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="text-xs font-medium text-slate-300">Property Title Baseline:</label>
                <input
                  type="text"
                  value={genTitle}
                  onChange={(e) => setGenTitle(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-2.5 text-sm text-white mt-1"
                />
              </div>
              <div>
                <label className="text-xs font-medium text-slate-300">City:</label>
                <input
                  type="text"
                  value={genCity}
                  onChange={(e) => setGenCity(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-2.5 text-sm text-white mt-1"
                />
              </div>
              <div>
                <label className="text-xs font-medium text-slate-300">Locality:</label>
                <input
                  type="text"
                  value={genLocality}
                  onChange={(e) => setGenLocality(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-2.5 text-sm text-white mt-1"
                />
              </div>
              <div>
                <label className="text-xs font-medium text-slate-300">Property Type:</label>
                <input
                  type="text"
                  value={genType}
                  onChange={(e) => setGenType(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-2.5 text-sm text-white mt-1"
                />
              </div>
            </div>

            <button
              onClick={handleGenerateCopy}
              disabled={loading}
              className="bg-red-600 hover:bg-red-500 text-white font-semibold px-6 py-2.5 rounded-xl text-sm transition-all flex items-center gap-2"
            >
              <Sparkles className="w-4 h-4" /> Generate Copy & SEO
            </button>

            {genOutput && (
              <div className="bg-slate-950 border border-slate-800 rounded-xl p-5 space-y-4">
                <div>
                  <span className="text-xs font-bold text-red-400 uppercase">Generated Title:</span>
                  <p className="text-sm font-semibold text-white mt-1">{genOutput.title}</p>
                </div>
                <div>
                  <span className="text-xs font-bold text-amber-400 uppercase">Generated Description:</span>
                  <p className="text-sm text-slate-300 leading-relaxed mt-1">{genOutput.description}</p>
                </div>
                <div>
                  <span className="text-xs font-bold text-emerald-400 uppercase">SEO Meta Description:</span>
                  <p className="text-xs text-slate-400 mt-1">{genOutput.seo}</p>
                </div>
              </div>
            )}
          </div>
        )}

        {/* TAB 5: Lead Summary */}
        {activeTab === 'lead-summary' && (
          <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl max-w-3xl mx-auto space-y-6">
            <div className="space-y-1">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <UserCheck className="w-5 h-5 text-red-500" /> AI Customer Lead Summarizer
              </h3>
              <p className="text-xs text-slate-400">
                Summarize long customer inquiry messages into quick actionable bullet points for agents.
              </p>
            </div>

            <div className="space-y-3">
              <textarea
                rows={4}
                value={leadText}
                onChange={(e) => setLeadText(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-sm text-white focus:outline-none focus:border-red-500"
              />
              <button
                onClick={handleSummarizeLead}
                disabled={loading}
                className="bg-red-600 text-white font-semibold px-6 py-2.5 rounded-xl text-sm hover:bg-red-500 transition-all flex items-center gap-2"
              >
                <Sparkles className="w-4 h-4" /> Summarize Lead
              </button>
            </div>

            {leadSummaryOutput && (
              <div className="bg-slate-950 border border-slate-800 rounded-xl p-4 text-sm text-slate-200 whitespace-pre-line leading-relaxed">
                {leadSummaryOutput}
              </div>
            )}
          </div>
        )}

        {/* TAB 6: AI Translation */}
        {activeTab === 'translation' && (
          <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl max-w-3xl mx-auto space-y-6">
            <div className="space-y-1">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <Languages className="w-5 h-5 text-red-500" /> AI Multilingual Real Estate Translator
              </h3>
              <p className="text-xs text-slate-400">Translate property copy into major Indian languages.</p>
            </div>

            <div className="space-y-4">
              <div>
                <label className="text-xs font-semibold text-slate-300">Target Language:</label>
                <select
                  value={transLang}
                  onChange={(e) => setTransLang(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-2.5 text-sm text-white mt-1"
                >
                  <option value="Hindi">Hindi (हिन्दी)</option>
                  <option value="Telugu">Telugu (తెలుగు)</option>
                  <option value="Tamil">Tamil (தமிழ்)</option>
                  <option value="Kannada">Kannada (కన్నడ)</option>
                  <option value="Marathi">Marathi (मराठी)</option>
                  <option value="Bengali">Bengali (বাংলা)</option>
                </select>
              </div>

              <textarea
                rows={3}
                value={transText}
                onChange={(e) => setTransText(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl p-3 text-sm text-white focus:outline-none focus:border-red-500"
              />

              <button
                onClick={handleTranslate}
                disabled={loading}
                className="bg-red-600 text-white font-semibold px-6 py-2.5 rounded-xl text-sm hover:bg-red-500 transition-all flex items-center gap-2"
              >
                <Sparkles className="w-4 h-4" /> Translate Text
              </button>

              {transOutput && (
                <div className="bg-slate-950 border border-slate-800 rounded-xl p-4 text-sm text-slate-200">
                  {transOutput}
                </div>
              )}
            </div>
          </div>
        )}

        {/* TAB 7: Market Insights */}
        {activeTab === 'market' && (
          <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-xl max-w-3xl mx-auto space-y-6">
            <div className="space-y-1">
              <h3 className="text-lg font-bold text-white flex items-center gap-2">
                <TrendingUp className="w-5 h-5 text-red-500" /> AI Market & Locality Insights Generator
              </h3>
              <p className="text-xs text-slate-400">
                Generate price per sqft trends, appreciation estimates, and locality advantages.
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="text-xs font-semibold text-slate-300">City:</label>
                <input
                  type="text"
                  value={marketCity}
                  onChange={(e) => setMarketCity(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-2.5 text-sm text-white mt-1"
                />
              </div>
              <div>
                <label className="text-xs font-semibold text-slate-300">Locality:</label>
                <input
                  type="text"
                  value={marketLocality}
                  onChange={(e) => setMarketLocality(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl p-2.5 text-sm text-white mt-1"
                />
              </div>
            </div>

            <button
              onClick={handleMarketInsights}
              disabled={loading}
              className="bg-red-600 text-white font-semibold px-6 py-2.5 rounded-xl text-sm hover:bg-red-500 transition-all flex items-center gap-2"
            >
              <Sparkles className="w-4 h-4" /> Analyze Market
            </button>

            {marketOutput && (
              <div className="bg-slate-950 border border-slate-800 rounded-xl p-5 text-sm text-slate-200 whitespace-pre-line leading-relaxed">
                {marketOutput}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search,
  Mic,
  Camera,
  MapPin,
  Sparkles,
  ArrowRight,
  TrendingUp,
  Building2,
  Home,
  Store,
  Warehouse,
  Users,
  Star,
  Phone,
  MessageCircle,
  Calendar,
  ShieldCheck,
  BadgeCheck,
  Zap,
  Bot,
  Calculator,
  FileText,
  Wallet,
  KeyRound,
  Briefcase,
  Heart,
  GitCompare,
  Eye,
  CheckCircle2,
  AppWindow,
  Smartphone,
  QrCode,
  Quote,
  ArrowUpRight,
  BarChart3,
  MapPinned,
  Layers,
  Award,
  Clock,
  Newspaper,
  Mail,
  PhoneCall,
  Scale,
  Hammer,
  Sun,
  Shield,
  Truck,
  Ruler,
  PaintBucket,
