/* ============================================================
   Dynamic AI Advertisement Banner Section (Home Page)
============================================================ */
function AIAdBannerSection() {
  const { t } = useLanguageContext();
  const realtimeTick = useRealtimeCount('advertisements');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [direction, setDirection] = useState(1); // 1 = next, -1 = prev
  const [isPaused, setIsPaused] = useState(false);
  const [progress, setProgress] = useState(0);

  const { data: ads } = useQuery({
    queryKey: ['home-ad-banners', realtimeTick],
    queryFn: async () => {
      const { data } = await supabase
        .from('advertisements')
        .select('*')
        .eq('is_active', true)
        .order('priority', { ascending: false })
        .order('display_order', { ascending: true });

      const filtered = (data ?? []).filter((a) => {
        if (a.end_date && new Date(a.end_date) < new Date()) return false;
        if (a.ends_at && new Date(a.ends_at) < new Date()) return false;
        return true;
      });

      return filtered as (Advertisement & {
        banner_tags?: string[];
        property_id?: string;
        category_name?: string;
        link_url?: string;
        seo_alt_text?: string;
        image_caption?: string;
      })[];
    },
  });

  const defaultBanners = [
    {
      id: 'demo-banner-1',
      title: 'Monsoon Mega Property Fest 2026',
      subtitle: 'Zero Brokerage on Verified Luxury Apartments & Villas',
      description: 'Get up to 5% instant cashback, free modular kitchen, and zero processing fee on home loans.',
      cta_text: 'Claim Exclusive Offer',
      cta_link: '/search?purpose=Buy',
      image_desktop: 'https://images.pexels.com/photos/1732414/pexels-photo-1732414.jpeg?auto=compress&cs=tinysrgb&w=1600',
      banner_tags: ['Zero Brokerage', '5% Cashback', 'RERA Approved'],
    },
    {
      id: 'demo-banner-2',
      title: 'Premium Smart Luxury Villas',
      subtitle: 'Exclusive Gated Community with 24/7 AI Security',
      description: 'Enjoy private swimming pool, home automation, and 0% down payment options.',
      cta_text: 'View Luxury Villas',
      cta_link: '/search?type=Villa',
      image_desktop: 'https://images.pexels.com/photos/1396122/pexels-photo-1396122.jpeg?auto=compress&cs=tinysrgb&w=1600',
      banner_tags: ['Smart Automation', 'Private Pool', 'Zero Down Payment'],
    },
    {
      id: 'demo-banner-3',
      title: 'Sea-View Penthouses in Mumbai',
      subtitle: 'Iconic Skyline Views | Starts at ₹3.2 Cr',
      description: 'Breathtaking Arabian Sea views, world-class concierge, and smart home features in every unit.',
      cta_text: 'Explore Penthouses',
      cta_link: '/search?type=Penthouse',
      image_desktop: 'https://images.pexels.com/photos/2581922/pexels-photo-2581922.jpeg?auto=compress&cs=tinysrgb&w=1600',
      banner_tags: ['Sea View', 'Premium Amenities', 'Luxury Living'],
    },
    {
      id: 'demo-banner-4',
      title: 'Commercial Workspaces & Tech Parks',
      subtitle: 'Prime Business Locations with High Rental Yields',
      description: 'Invest in GRADE-A commercial spaces with guaranteed 10% annual rental return.',
      cta_text: 'Explore Commercial',
      cta_link: '/search?purpose=Commercial',
      image_desktop: 'https://images.pexels.com/photos/380769/pexels-photo-380769.jpeg?auto=compress&cs=tinysrgb&w=1600',
      banner_tags: ['Grade-A Space', '10% Rental Yield', 'High ROI'],
    },
    {
      id: 'demo-banner-5',
      title: 'Serene Farmhouse Estates in Hyderabad',
      subtitle: 'Escape the City | Private Green Living',
      description: 'Sprawling 2-acre farmhouse plots with landscaped gardens, organic farm, and clubhouse.',
      cta_text: 'Discover Estates',
      cta_link: '/search?type=Farmhouse',
      image_desktop: 'https://images.pexels.com/photos/259950/pexels-photo-259950.jpeg?auto=compress&cs=tinysrgb&w=1600',
      banner_tags: ['2-Acre Plots', 'Green Living', 'Gated Community'],
    },
  ];

  const bannerItems = ads && ads.length > 0 ? ads : defaultBanners;
  const SLIDE_DURATION = 5000;

  // Progress bar + auto-play
  useEffect(() => {
    if (isPaused) return;
    setProgress(0);
    const startTime = Date.now();
    const tick = setInterval(() => {
      const elapsed = Date.now() - startTime;
      setProgress(Math.min((elapsed / SLIDE_DURATION) * 100, 100));
    }, 50);
    const slide = setTimeout(() => {
      setDirection(1);
      setCurrentIndex((prev) => (prev + 1) % bannerItems.length);
    }, SLIDE_DURATION);
    return () => { clearInterval(tick); clearTimeout(slide); };
  }, [currentIndex, isPaused, bannerItems.length]);

  const goTo = (idx: number) => {
    setDirection(idx > currentIndex ? 1 : -1);
    setCurrentIndex(idx);
  };

  const handlePrev = (e: React.MouseEvent) => {
    e.stopPropagation();
    setDirection(-1);
    setCurrentIndex((prev) => (prev === 0 ? bannerItems.length - 1 : prev - 1));
  };

  const handleNext = (e: React.MouseEvent) => {
    e.stopPropagation();
    setDirection(1);
    setCurrentIndex((prev) => (prev + 1) % bannerItems.length);
  };

  const handleBannerClick = async (ad: any) => {
    if (ad.id && typeof ad.id === 'string' && !ad.id.startsWith('demo-')) {
      try {
        await supabase.rpc('increment_ad_click', { p_ad_id: ad.id });
      } catch {
        await supabase
          .from('advertisements')
          .update({ clicks: ((ad.clicks as number) ?? 0) + 1 })
          .eq('id', ad.id);
      }
    }
  };

  const activeAd: any = bannerItems[currentIndex % bannerItems.length] || defaultBanners[0];
  const targetLink = activeAd.property_id
    ? `/property/${activeAd.property_id}`
    : activeAd.category_name
      ? `/search?purpose=${activeAd.category_name}`
      : activeAd.cta_link || activeAd.link_url || '/search';

  const slideVariants = {
    enter: (dir: number) => ({ x: dir > 0 ? '100%' : '-100%', opacity: 0, scale: 1.05 }),
    center: { x: 0, opacity: 1, scale: 1 },
    exit: (dir: number) => ({ x: dir > 0 ? '-100%' : '100%', opacity: 0, scale: 0.95 }),
  };

  const textVariants: any = {
    hidden: { opacity: 0, y: 30 },
    visible: (i: number) => ({ opacity: 1, y: 0, transition: { delay: i * 0.12, duration: 0.5, ease: 'easeOut' } }),
  };

  return (
    <section
      className="py-8 bg-slate-50/50"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      <div className="container-wide">
        <div className="relative overflow-hidden rounded-3xl shadow-2xl min-h-[420px] sm:min-h-[480px] group">

          {/* Slides */}
          <AnimatePresence initial={false} custom={direction} mode="popLayout">
            <motion.div
              key={activeAd.id || currentIndex}
              custom={direction}
              variants={slideVariants}
              initial="enter"
              animate="center"
              exit="exit"
              transition={{ duration: 0.65, ease: [0.32, 0.72, 0, 1] }}
              className="absolute inset-0"
            >
              {/* Background image with Ken Burns zoom */}
              <motion.img
                src={activeAd.image_desktop || defaultBanners[0].image_desktop}
                alt={activeAd.seo_alt_text || activeAd.title}
                className="absolute inset-0 h-full w-full object-cover"
                initial={{ scale: 1.08 }}
                animate={{ scale: 1 }}
                transition={{ duration: 6, ease: 'easeOut' }}
              />
              {/* Multi-layer gradient for depth */}
              <div className="absolute inset-0 bg-gradient-to-r from-black/90 via-black/60 to-transparent" />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-black/20" />
            </motion.div>
          </AnimatePresence>

          {/* Content */}
          <div className="relative z-10 flex items-center min-h-[420px] sm:min-h-[480px] p-6 sm:p-12">
            <div className="w-full max-w-2xl">
              {/* Badge row */}
              <motion.div
                key={`badge-${currentIndex}`}
                custom={0}
                variants={textVariants}
                initial="hidden"
                animate="visible"
                className="flex flex-wrap items-center gap-2 mb-4"
              >
                <span className="inline-flex items-center gap-1.5 bg-red-600 text-white text-[11px] font-extrabold uppercase tracking-widest px-3 py-1.5 rounded-full shadow-lg shadow-red-600/30">
                  <Sparkles className="h-3 w-3 animate-pulse" />
                  {t('home.verifiedSponsoredOffer', 'Verified Sponsored Offer')}
                </span>
                {activeAd.banner_tags && activeAd.banner_tags.slice(0, 3).map((tag: string, i: number) => (
                  <motion.span
                    key={i}
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: 0.2 + i * 0.08 }}
                    className="rounded-full bg-white/10 backdrop-blur-sm px-3 py-1 text-[11px] font-semibold text-slate-200 border border-white/20"
                  >
                    {tag}
                  </motion.span>
                ))}
              </motion.div>

              {/* Title */}
              <motion.h2
                key={`title-${currentIndex}`}
                custom={1}
                variants={textVariants}
                initial="hidden"
                animate="visible"
                className="font-display text-2xl sm:text-3xl lg:text-4xl xl:text-5xl font-extrabold text-white tracking-tight leading-tight"
              >
                {activeAd.title}
              </motion.h2>

              {/* Subtitle */}
              {activeAd.subtitle && (
                <motion.p
                  key={`sub-${currentIndex}`}
                  custom={2}
                  variants={textVariants}
                  initial="hidden"
                  animate="visible"
                  className="mt-3 text-base sm:text-lg font-semibold text-amber-400"
                >
                  {activeAd.subtitle}
                </motion.p>
              )}

              {/* Description */}
              {activeAd.description && (
                <motion.p
                  key={`desc-${currentIndex}`}
                  custom={3}
                  variants={textVariants}
                  initial="hidden"
                  animate="visible"
                  className="mt-2 text-sm text-slate-300 leading-relaxed max-w-xl"
                >
                  {activeAd.description}
                </motion.p>
              )}

              {/* CTA */}
              <motion.div
                key={`cta-${currentIndex}`}
                custom={4}
                variants={textVariants}
                initial="hidden"
                animate="visible"
                className="mt-7 flex flex-wrap items-center gap-4"
              >
                {targetLink.startsWith('http') ? (
                  <a
                    href={targetLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    onClick={() => handleBannerClick(activeAd)}
                    className="group inline-flex items-center gap-2 rounded-2xl bg-gradient-to-r from-red-600 via-rose-500 to-red-600 px-7 py-3.5 text-sm font-extrabold text-white shadow-2xl shadow-red-600/40 hover:shadow-red-600/60 hover:scale-105 transition-all"
                  >
                    <span>{activeAd.cta_text || t('home.exploreOffer', 'Explore Offer')}</span>
                    <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                  </a>
                ) : (
                  <Link
                    to={targetLink}
                    onClick={() => handleBannerClick(activeAd)}
                    className="group inline-flex items-center gap-2 rounded-2xl bg-gradient-to-r from-red-600 via-rose-500 to-red-600 px-7 py-3.5 text-sm font-extrabold text-white shadow-2xl shadow-red-600/40 hover:shadow-red-600/60 hover:scale-105 transition-all"
                  >
                    <span>{activeAd.cta_text || t('home.exploreOffer', 'Explore Offer')}</span>
                    <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-1" />
                  </Link>
                )}
                <span className="text-xs text-white/50 font-medium">
                  ⚡ {t('home.limitedTimeDeal', 'Real-time verified listing | Limited time deal')}
                </span>
              </motion.div>
            </div>
          </div>

          {/* Progress Bar */}
          {!isPaused && bannerItems.length > 1 && (
            <div className="absolute bottom-0 left-0 right-0 z-20 h-1 bg-white/10">
              <motion.div
                className="h-full bg-gradient-to-r from-red-500 to-rose-500"
                initial={{ width: '0%' }}
                animate={{ width: `${progress}%` }}
                transition={{ ease: 'linear' }}
              />
            </div>
          )}

          {/* Left / Right Arrows - Always visible on hover */}
          {bannerItems.length > 1 && (
            <>
              <motion.button
                type="button"
                onClick={handlePrev}
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
                className="absolute left-3 sm:left-6 top-1/2 -translate-y-1/2 z-30 flex h-12 w-12 items-center justify-center rounded-full bg-white/20 text-white backdrop-blur-md border border-white/40 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-600 hover:border-red-500 shadow-lg cursor-pointer"
                aria-label="Previous slide"
              >
                <ChevronLeft className="h-6 w-6" />
              </motion.button>
              <motion.button
                type="button"
                onClick={handleNext}
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.95 }}
                className="absolute right-3 sm:right-6 top-1/2 -translate-y-1/2 z-30 flex h-12 w-12 items-center justify-center rounded-full bg-white/20 text-white backdrop-blur-md border border-white/40 opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-600 hover:border-red-500 shadow-lg cursor-pointer"
                aria-label="Next slide"
              >
                <ChevronRight className="h-6 w-6" />
              </motion.button>
            </>
          )}

          {/* Dot Indicators */}
          {bannerItems.length > 1 && (
            <div className="absolute bottom-6 left-1/2 z-20 flex -translate-x-1/2 items-center gap-2 backdrop-blur-sm bg-black/20 rounded-full px-3 py-2">
              {bannerItems.map((_, i) => (
                <motion.button
                  key={i}
                  type="button"
                  onClick={() => goTo(i)}
                  whileHover={{ scale: 1.2 }}
                  whileTap={{ scale: 0.9 }}
                  className={cn(
                    'rounded-full transition-all cursor-pointer shadow-md',
                    currentIndex === i
                      ? 'w-8 h-2.5 bg-red-500 shadow-red-500/50'
                      : 'w-2 h-2 bg-white/50 hover:bg-white/80',
                  )}
                  aria-label={`Go to slide ${i + 1}`}
                  aria-current={currentIndex === i}
                />
              ))}
            </div>
          )}

          {/* Slide Counter */}
          {bannerItems.length > 1 && (
            <div className="absolute top-6 right-6 z-20 flex items-center gap-2 bg-black/40 backdrop-blur-md rounded-full px-3 py-1.5 text-white text-xs font-semibold border border-white/20">
              <span className="text-red-400 font-bold">{currentIndex + 1}</span>
              <span className="text-white/60">/</span>
              <span>{bannerItems.length}</span>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

