function SignatureCollection() {
  const { t } = useLanguageContext();
  const { data } = useQuery({
    queryKey: ['home-luxury'],
    queryFn: async () => {
      const { data } = await supabase
        .from('properties')
        .select('*, cities(name), localities(name), property_types(name)')
        .eq('status', 'published')
        .eq('is_luxury', true)
        .order('price', { ascending: false })
        .limit(3);
      return (data ?? []).map((p) => {
        const r = p as unknown as {
          cities?: { name: string };
          localities?: { name: string };
          property_types?: { name: string };
        };
        return {
          ...p,
          city_name: r.cities?.name ?? null,
          locality_name: r.localities?.name ?? null,
          property_type_name: r.property_types?.name ?? null,
        };
      });
    },
  });

  if (!data || data.length === 0) return null;

  return (
    <SectionShell
      title={t('home.signatureCollection', 'Signature Collection')}
      subtitle={t('home.signatureSubtitle', 'Ultra-luxury homes for the discerning buyer')}
      id="luxury"
    >
      <div className="grid gap-6 lg:grid-cols-3">
        {data.map((p, i) => (
          <motion.div
            key={p.id}
