/* ============================================================
   Paid Ad Properties Carousel — 4-card sponsored spotlight
============================================================ */
function PaidAdPropertiesCarousel() {
  const { t } = useLanguageContext();
  const navigate = useNavigate();
  const [current, setCurrent] = useState(0);
  const [isPaused, setIsPaused] = useState(false);
  const VISIBLE = 4; // cards shown at once on desktop

  const { data: properties } = useQuery({
    queryKey: ['paid-ad-properties'],
    queryFn: async () => {
      const { data } = await supabase
        .from('properties')
        .select('*, cities(name), localities(name), property_types(name)')
        .eq('status', 'published')
        .eq('is_featured', true)
        .order('created_at', { ascending: false })
        .limit(12);
      if (!data || data.length === 0) {
        // fallback: any published properties
        const { data: fallback } = await supabase
          .from('properties')
          .select('*, cities(name), localities(name), property_types(name)')
          .eq('status', 'published')
          .order('view_count', { ascending: false })
          .limit(12);
        return (fallback ?? []).map((p: any) => ({
          ...p,
          city_name: p.cities?.name ?? null,
          locality_name: p.localities?.name ?? null,
          property_type_name: p.property_types?.name ?? null,
        }));
      }
      return data.map((p: any) => ({
        ...p,
        city_name: p.cities?.name ?? null,
        locality_name: p.localities?.name ?? null,
        property_type_name: p.property_types?.name ?? null,
      }));
    },
  });

  const items = properties ?? [];
  const total = items.length;
  const maxIndex = Math.max(0, total - VISIBLE);

  // Auto-play
  useEffect(() => {
    if (isPaused || total <= VISIBLE) return;
    const t = setInterval(() => {
      setCurrent((c) => (c >= maxIndex ? 0 : c + 1));
    }, 3500);
    return () => clearInterval(t);
  }, [isPaused, total, maxIndex]);

  const prev = () => setCurrent((c) => Math.max(0, c - 1));
  const next = () => setCurrent((c) => Math.min(maxIndex, c + 1));

  if (total === 0) return null;

  const formatPrice = (price: number) => {
    if (price >= 10000000) return `₹${(price / 10000000).toFixed(1)}Cr`;
    if (price >= 100000) return `₹${(price / 100000).toFixed(0)}L`;
    return `₹${price.toLocaleString('en-IN')}`;
  };

  return (
    <section
      className="py-12 sm:py-16 bg-gradient-to-b from-slate-900 to-slate-800 overflow-hidden"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      <div className="container-wide">

        {/* Header */}
        <div className="flex items-end justify-between mb-8 gap-4">
          <div>
            <div className="inline-flex items-center gap-2 rounded-full bg-red-600/20 border border-red-500/30 px-4 py-1.5 mb-3">
              <Sparkles className="h-3.5 w-3.5 text-red-400 animate-pulse" />
              <span className="text-[11px] font-extrabold uppercase tracking-widest text-red-400">
                {t('home.sponsoredSpotlight', 'Sponsored Spotlight')}
              </span>
            </div>
            <h2 className="font-display text-2xl sm:text-3xl font-extrabold text-white">
              {t('home.featuredForYou', 'Featured Properties for You')}
            </h2>
            <p className="mt-1.5 text-slate-400 text-sm">
              {t('home.handPickedPremium', 'Hand-picked premium listings with verified details')}
            </p>
          </div>
          <div className="flex items-center gap-3 shrink-0">
            {/* Arrows */}
            <button
              onClick={prev}
              disabled={current === 0}
              className="flex h-10 w-10 items-center justify-center rounded-full border border-white/20 bg-white/10 text-white backdrop-blur-sm hover:bg-red-600 hover:border-red-500 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
              aria-label="Previous"
            >
              <ChevronLeft className="h-5 w-5" />
            </button>
            <button
              onClick={next}
              disabled={current >= maxIndex}
              className="flex h-10 w-10 items-center justify-center rounded-full border border-white/20 bg-white/10 text-white backdrop-blur-sm hover:bg-red-600 hover:border-red-500 disabled:opacity-30 disabled:cursor-not-allowed transition-all"
              aria-label="Next"
            >
              <ChevronRight className="h-5 w-5" />
            </button>
            <Link
              to="/search?is_featured=true"
              className="hidden sm:flex items-center gap-1.5 rounded-full border border-white/20 bg-white/10 px-4 py-2 text-xs font-bold text-white hover:bg-red-600 hover:border-red-500 transition-all"
            >
              {t('home.viewAll', 'View All')} <ArrowRight className="h-3.5 w-3.5" />
            </Link>
          </div>
        </div>

        {/* Slider Track */}
        <div className="overflow-hidden">
          <motion.div
            className="flex gap-4"
            animate={{ x: `calc(-${current} * (25% + 1rem) * ${VISIBLE <= total ? 1 : 0})` }}
            transition={{ type: 'spring', stiffness: 300, damping: 30 }}
            style={{ width: `calc(${total} * 25% + ${total - 1} * 1rem)` }}
          >
            {items.map((p: any, i: number) => (
              <motion.div
                key={p.id}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: i * 0.05 }}
                className="w-[calc(25%-0.75rem)] shrink-0 min-w-[240px]"
                onClick={() => navigate(`/property/${p.id}`)}
              >
                <div className="group relative flex flex-col h-full rounded-2xl overflow-hidden cursor-pointer border border-white/10 hover:border-red-500/50 hover:-translate-y-1.5 transition-all duration-300 shadow-xl hover:shadow-2xl bg-slate-800">

                  {/* Image */}
                  <div className="relative aspect-[4/3] overflow-hidden">
                    <img
                      src={p.images?.[0] ?? 'https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg'}
                      alt={p.title}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                      loading="lazy"
                    />
                    <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent" />

                    {/* Badges */}
                    <div className="absolute top-3 left-3 flex flex-wrap gap-1.5 z-10">
                      <span className="inline-flex items-center gap-1 rounded-full bg-red-600 px-2.5 py-1 text-[10px] font-extrabold uppercase text-white shadow-lg">
                        <Sparkles className="h-2.5 w-2.5" /> Sponsored
                      </span>
                      {p.is_luxury && (
                        <span className="rounded-full bg-amber-500 px-2 py-0.5 text-[10px] font-bold text-white">
                          Luxury
                        </span>
                      )}
                    </div>

                    {/* Price overlay */}
                    <div className="absolute bottom-3 left-3 right-3 z-10">
                      <p className="font-display text-xl font-extrabold text-white drop-shadow-lg">
                        {formatPrice(p.price)}
                      </p>
                    </div>
                  </div>

                  {/* Content */}
                  <div className="p-4 flex flex-col gap-2 flex-1">
                    <h3 className="font-bold text-white text-sm leading-tight line-clamp-2 group-hover:text-red-400 transition-colors">
                      {p.title}
                    </h3>
                    <p className="text-xs text-slate-400 flex items-center gap-1 truncate">
                      <MapPin className="h-3 w-3 text-red-400 shrink-0" />
                      {[p.locality_name, p.city_name].filter(Boolean).join(', ') || p.address || 'Location TBD'}
                    </p>

                    {/* Specs */}
                    <div className="flex items-center gap-3 text-xs text-slate-400 mt-auto pt-2 border-t border-white/10">
                      {p.bedrooms != null && (
                        <span className="flex items-center gap-0.5">🛏 {p.bedrooms} BHK</span>
                      )}
                      {p.built_up_area && (
                        <span className="flex items-center gap-0.5">📐 {p.built_up_area} sqft</span>
                      )}
                      {p.purpose && (
                        <span className={`ml-auto rounded-full px-2 py-0.5 text-[10px] font-bold ${p.purpose === 'Rent' ? 'bg-blue-600/30 text-blue-300' : 'bg-emerald-600/30 text-emerald-300'}`}>
                          {p.purpose === 'Rent' ? 'Rent' : 'Sale'}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </motion.div>
        </div>

        {/* Dot Indicators */}
        {total > VISIBLE && (
          <div className="flex items-center justify-center gap-2 mt-7">
            {Array.from({ length: maxIndex + 1 }).map((_, i) => (
              <button
                key={i}
                onClick={() => setCurrent(i)}
                className={cn(
                  'rounded-full transition-all duration-300',
                  current === i ? 'w-7 h-2 bg-red-500' : 'w-2 h-2 bg-white/30 hover:bg-white/60',
                )}
                aria-label={`Go to slide ${i + 1}`}
              />
            ))}
          </div>
        )}

      </div>
    </section>
  );
}

/* ============================================================
   Latest Blogs
============================================================ */
function LatestBlogs() {
  const { t } = useLanguageContext();
  const realtimeTick = useRealtimeCount('blogs');
  const { data, isLoading } = useQuery({
    queryKey: ['home-blogs', realtimeTick],
    queryFn: async () => {
      const { data } = await supabase
        .from('blogs')
        .select('*')
        .eq('published', true)
        .order('published_at', { ascending: false })
        .limit(3);
      return data ?? [];
    },
  });

  return (
    <SectionShell
      title={t('home.latestFromBlog', 'Latest from our Blog')}
      subtitle={t('home.blogSubtitle', 'Guides, tips, and market insights')}
      id="blogs"
      action={
        <Link
          to="/blog"
          className="flex items-center gap-1 text-sm font-semibold text-primary-600 hover:text-primary-700"
        >
          {t('common.allPosts', 'All posts')} <ArrowRight className="h-4 w-4" />
        </Link>
      }
    >
      {isLoading ? (
        <div className="grid gap-6 sm:grid-cols-3">
          {Array.from({ length: 3 }).map((_, i) => (
            <div key={i} className="skeleton h-72 rounded-2xl" />
          ))}
        </div>
      ) : data && data.length > 0 ? (
        <div className="grid gap-6 sm:grid-cols-3">
          {data.map((b, i) => (
            <motion.div
              key={b.id}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: i * 0.08 }}
            >
              <Link
                to={`/blog/${b.slug}`}
                className="group block overflow-hidden rounded-2xl border border-navy-100 bg-white transition hover:shadow-cardHover"
              >
                {b.cover_image && (
                  <div className="aspect-video overflow-hidden">
                    <img
                      src={b.cover_image}
                      alt={b.title}
                      className="h-full w-full object-cover transition duration-500 group-hover:scale-105"
                    />
                  </div>
                )}
                <div className="p-5">
                  <div className="flex gap-1.5">
                    {(b.tags as string[] | null)?.slice(0, 2).map((tag) => (
                      <span key={tag} className="badge-blue">
                        {tag}
                      </span>
                    ))}
                  </div>
                  <h3 className="mt-2 font-display font-bold text-navy-900 line-clamp-2 group-hover:text-primary-700">
                    {b.title}
                  </h3>
                  <p className="mt-2 text-sm text-navy-600 line-clamp-2">{b.excerpt}</p>
                  <p className="mt-3 text-xs text-navy-400">
                    {new Date(b.published_at ?? b.created_at).toLocaleDateString('en-IN', {
                      day: 'numeric',
                      month: 'short',
                      year: 'numeric',
                    })}
                  </p>
                </div>
              </Link>
            </motion.div>
          ))}
        </div>
      ) : (
        <p className="text-center text-sm text-navy-400">{t('home.noBlogsYet', 'No blog posts yet.')}</p>
      )}
    </SectionShell>
  );
}

