            {t('home.weEnhance', 'We ')}<span className="text-red-600">{t('home.enhanceLiving2', 'Enhance Your Living.')}</span>
          </h2>
          <p className="mt-5 text-slate-600 max-w-2xl mx-auto text-base leading-relaxed">
            {t('home.servicesDescription', 'Discover premium services to complete your dream home experience with')}{' '}
            <span className="font-bold text-red-600 underline underline-offset-2 decoration-red-200">
              {t('home.trustedProfessionals', 'trusted professionals')}
            </span>
