                        <span>{svc.cta}</span>
                        <ArrowRight className="h-4 w-4 transition-transform duration-200 group-hover:translate-x-1" />
                      </button>

                    </div>
                  </div>
                </CardWrap>
              </motion.div>
            );
          })}
        </div>

        {/* ── Trust Badges Row ── */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 pt-4 border-t border-slate-100">
          {TRUST_BADGES.map((badge) => (
            <div key={badge.title} className="flex items-center gap-3">
              <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl border border-amber-100 bg-amber-50">
                <badge.icon className="h-5 w-5 text-amber-600" />
              </div>
              <div>
                <p className="font-bold text-slate-900 text-sm">{badge.title}</p>
                <p className="text-[11px] text-slate-500">{badge.sub}</p>
              </div>
            </div>
          ))}
        </div>

      </div>
    </section>
  );
}

