interface AgentInfo {
  first_name: string | null;
  last_name: string | null;
  email: string;
  phone: string | null;
  avatar_url: string | null;
  bio: string | null;
  company: string | null;
  license_number: string | null;
}

export function PropertyDetailPage() {
  const { t } = useLanguageContext();
  const { id } = useParams();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const { addToast } = useToast();
  const [activeImg, setActiveImg] = useState(0);
  const [lightbox, setLightbox] = useState(false);
  const [contactOpen, setContactOpen] = useState(false);
  const [apptOpen, setApptOpen] = useState(false);
  const [reviewOpen, setReviewOpen] = useState(false);
  const [showVideo, setShowVideo] = useState(false);
  const [form, setForm] = useState({ name: '', email: '', phone: '', message: '' });
  const [apptForm, setApptForm] = useState({ date: '', time: '', notes: '' });
  const [reviewForm, setReviewForm] = useState({ rating: 5, comment: '' });
  const [saved, setSaved] = useState(false);
  const [compared, setCompared] = useState(false);
  const [showShare, setShowShare] = useState(false);

  const { data: property, isLoading } = useQuery({
    queryKey: ['property', id],
    queryFn: () => fetchProperty(id!),
    enabled: !!id,
  });

  const { data: agent } = useQuery({
    queryKey: ['property-agent', property?.assigned_agent_id],
    queryFn: async () => {
      const { data } = await supabase
        .from('profiles')
        .select('first_name, last_name, email, phone, avatar_url, bio, company, license_number')
        .eq('id', property!.assigned_agent_id!)
        .maybeSingle();
      return data as AgentInfo | null;
    },
    enabled: !!property?.assigned_agent_id,
  });

  const { data: similar } = useQuery({
    queryKey: ['similar', property?.city_id, property?.property_type_id],
    queryFn: async () => {
      const { data } = await supabase
        .from('properties')
        .select('*, cities!inner(name), localities(name), property_types(name)')
        .eq('status', 'published')
        .neq('id', id!)
        .eq('city_id', property!.city_id!)
        .limit(3);
      return (data ?? []).map((p) => {
        const r = p as unknown as {
          cities?: { name: string };
          localities?: { name: string };
          property_types?: { name: string };
        };
        return {
          ...p,
          city_name: r.cities?.name ?? null,
          locality_name: r.localities?.name ?? null,
          property_type_name: r.property_types?.name ?? null,
        };
      });
    },
    enabled: !!property?.city_id,
  });

  const { data: recentViews } = useQuery({
    queryKey: ['recent-views', id],
    queryFn: async () => {
      const { data } = await supabase
        .from('property_views')
        .select('property_id')
        .order('created_at', { ascending: false })
        .limit(5);
      if (!data || data.length === 0) return [];
      const ids = [
        ...new Set(data.map((v: { property_id: string }) => v.property_id).filter((pid: string) => pid !== id)),
      ].slice(0, 4);
      if (ids.length === 0) return [];
      const { data: props } = await supabase
        .from('properties')
        .select('*, cities!inner(name), localities(name), property_types(name)')
        .in('id', ids);
      return (props ?? []).map((p) => {
        const r = p as unknown as {
          cities?: { name: string };
          localities?: { name: string };
          property_types?: { name: string };
        };
        return {
          ...p,
          city_name: r.cities?.name ?? null,
          locality_name: r.localities?.name ?? null,
          property_type_name: r.property_types?.name ?? null,
        };
      });
    },
  });

  const { data: reviews } = useQuery({
    queryKey: ['reviews', id],
    queryFn: async () => {
      const { data } = await supabase
        .from('reviews')
        .select('*, profiles!inner(first_name, last_name, avatar_url)')
        .eq('property_id', id!)
        .order('created_at', { ascending: false });
      return data ?? [];
    },
    enabled: !!id,
  });

  const { data: priceHistory } = useQuery({
    queryKey: ['price-history', id],
    queryFn: async () => {
      const { data } = await supabase
        .from('property_status_history')
        .select('*')
        .eq('property_id', id!)
        .order('created_at', { ascending: false })
        .limit(5);
      return data ?? [];
    },
    enabled: !!id,
  });

  useEffect(() => {
    if (id) trackPropertyView(id, user?.id);
  }, [id, user?.id]);

  useEffect(() => {
    if (id) {
      setCompared(isCompared(id));
      if (user) {
        supabase
          .from('favorites')
          .select('id')
          .eq('user_id', user.id)
          .eq('property_id', id)
          .maybeSingle()
          .then(({ data }) => setSaved(!!data));
      }
    }
  }, [user, id]);

  const toggleSave = async () => {
    if (!user) {
      navigate('/login');
      return;
    }
    if (saved) {
      await supabase.from('favorites').delete().eq('user_id', user.id).eq('property_id', id);
      setSaved(false);
    } else {
      await supabase.from('favorites').insert({ user_id: user.id, property_id: id });
      setSaved(true);
    }
  };

  const toggleCompare = async () => {
    if (!id) return;
    try {
      const isNowCompared = await toggleCompareProperty(id, user?.id);
      setCompared(isNowCompared);
      addToast(
        'success',
        isNowCompared
          ? t('notifications.addedToCompare', 'Added to comparison list')
          : t('notifications.removedFromCompare', 'Removed from comparison list'),
      );
    } catch (err) {
      addToast('error', err instanceof Error ? err.message : t('notifications.errorCompare', 'Compare action failed'));
    }
  };

  const shareLinks = [
    { name: 'WhatsApp', href: `https://wa.me/?text=${encodeURIComponent(window.location.href)}` },
    {
      name: 'Facebook',
      href: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(window.location.href)}`,
    },
    { name: 'X (Twitter)', href: `https://twitter.com/intent/tweet?url=${encodeURIComponent(window.location.href)}` },
    {
      name: 'LinkedIn',
      href: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(window.location.href)}`,
    },
  ];

  const handlePrint = () => window.print();

  const enquiryMutation = useMutation({
    mutationFn: async () => {
      const payload: Record<string, unknown> = {
        property_id: id,
        name: form.name,
        email: form.email,
        phone: form.phone,
        message: form.message,
      };
      if (user) payload.customer_id = user.id;
      if (property?.assigned_agent_id) payload.agent_id = property.assigned_agent_id;
      const { error } = await supabase.from('enquiries').insert(payload);
      if (error) throw error;
    },
    onSuccess: () => {
      setContactOpen(false);
      setForm({ name: '', email: '', phone: '', message: '' });
      addToast('success', 'Enquiry sent successfully!');
    },
    onError: (err: any) => addToast('error', err.message || 'Failed to send enquiry'),
  });

  const apptMutation = useMutation({
    mutationFn: async () => {
      if (!user) throw new Error('Please sign in to book an appointment');
      const scheduledAt = new Date(`${apptForm.date}T${apptForm.time}`).toISOString();
      const { error } = await supabase.from('appointments').insert({
        property_id: id,
        customer_id: user.id,
        agent_id: property?.assigned_agent_id,
        scheduled_at: scheduledAt,
        notes: apptForm.notes,
        status: 'requested',
      });
      if (error) throw error;
    },
    onSuccess: () => {
      setApptOpen(false);
      setApptForm({ date: '', time: '', notes: '' });
      queryClient.invalidateQueries({ queryKey: ['portal-appointments'] });
      addToast('success', 'Appointment requested successfully!');
    },
    onError: (err: any) => addToast('error', err.message || 'Failed to request appointment'),
  });

  const reviewMutation = useMutation({
    mutationFn: async () => {
      if (!user) throw new Error('Please sign in to leave a review');
      const { error } = await supabase.from('reviews').insert({
        property_id: id,
        user_id: user.id,
        rating: reviewForm.rating,
        comment: reviewForm.comment,
      });
      if (error) throw error;
    },
    onSuccess: () => {
      setReviewOpen(false);
      setReviewForm({ rating: 5, comment: '' });
      queryClient.invalidateQueries({ queryKey: ['reviews', id] });
      addToast('success', 'Review submitted successfully!');
    },
    onError: (err: any) => addToast('error', err.message || 'Failed to submit review'),
  });

  if (isLoading)
    return (
      <div className="container-page py-16">
        <div className="flex justify-center">
          <Spinner className="h-8 w-8" />
        </div>
      </div>
    );
  if (!property)
    return (
      <div className="container-page py-16">
        <Card>
          <EmptyState
            icon={<Home className="h-6 w-6" />}
            title={t('property.notFound', 'Property not found')}
            description={t('property.removedMsg', 'This listing may have been removed.')}
            action={
              <Link to="/search">
                <Button variant="secondary">{t('common.browseProperties', 'Browse properties')}</Button>
              </Link>
            }
          />
        </Card>
      </div>
    );

  const images = property.images?.length
    ? property.images
    : ['https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg'];
  const agentName = agent ? `${agent.first_name ?? ''} ${agent.last_name ?? ''}`.trim() : 'Agent';
  const schema = {
    '@context': 'https://schema.org',
    '@type': 'RealEstateListing',
    name: property.title,
    description: property.description,
    image: images,
    address: property.address ?? `${property.locality_name ?? ''}, ${property.city_name ?? ''}`,
    offers: { price: property.price, priceCurrency: 'INR' },
  };

  return (
    <div className="container-page py-6">
      <script type="application/ld+json">{JSON.stringify(schema)}</script>

      <div className="mb-4 flex items-center gap-2 text-sm text-navy-500">
        <Link to="/" className="hover:text-navy-800">
          {t('common.home', 'Home')}
        </Link>
        <ChevronLeft className="h-3 w-3 rotate-180" />
        <Link to="/search" className="hover:text-navy-800">
          {t('common.search', 'Search')}
        </Link>
        <ChevronLeft className="h-3 w-3 rotate-180" />
        <span className="text-navy-700">{property.title}</span>
      </div>

      {/* Property Title & Main Media Showcase */}
      <div className="grid gap-2 lg:grid-cols-3">
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          className="relative aspect-video overflow-hidden rounded-2xl bg-navy-100 lg:col-span-2 group cursor-pointer"
          onClick={() => setLightbox(true)}
        >
          <img
            src={images[activeImg]}
            alt={property.title}
            className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-navy-950/40 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
            <span className="bg-white/90 backdrop-blur text-navy-900 font-bold text-xs px-3.5 py-2 rounded-full shadow-lg flex items-center gap-1.5">
              <Maximize2 className="h-4 w-4" /> {t('property.expandGallery', 'Expand Gallery')}
            </span>
          </div>

          <div className="absolute left-4 top-4 flex gap-2">
            <Badge variant={property.purpose === 'Rent' ? 'info' : 'gold'}>
              {t('common.for', 'For')}{' '}
              {property.purpose === 'Rent' ? t('common.rent', 'Rent') : t('common.sale', 'Sale')}
            </Badge>
            {property.is_featured && <Badge variant="success">{t('common.featured', 'Featured')}</Badge>}
            {property.is_luxury && <Badge variant="error">{t('common.luxury', 'Luxury')}</Badge>}
          </div>

          <div className="absolute right-4 top-4 flex gap-2">
            <button
              onClick={toggleSave}
              className={cn(
                'grid h-10 w-10 place-items-center rounded-full bg-white/90 shadow backdrop-blur transition hover:scale-110',
                saved ? 'text-error-500' : 'text-navy-400',
              )}
              title={
                saved ? t('common.removeFromSaved', 'Remove from saved') : t('common.saveProperty', 'Save property')
              }
            >
              <Heart className={cn('h-5 w-5', saved && 'fill-error-500')} />
            </button>
            <button
              onClick={toggleCompare}
              className={cn(
                'grid h-10 w-10 place-items-center rounded-full bg-white/90 shadow backdrop-blur transition hover:scale-110',
                compared ? 'text-secondary-600' : 'text-navy-400',
              )}
              title={
                compared
                  ? t('common.removeFromCompare', 'Remove from compare')
                  : t('common.addToCompare', 'Add to compare')
              }
            >
              <GitCompare className="h-5 w-5" />
            </button>
            <button
              onClick={() => setShowShare((s) => !s)}
              className="grid h-10 w-10 place-items-center rounded-full bg-white/90 shadow backdrop-blur transition hover:scale-110 text-navy-500"
              title={t('common.share', 'Share')}
            >
              <Share2 className="h-5 w-5" />
            </button>
            <button
              onClick={handlePrint}
              className="grid h-10 w-10 place-items-center rounded-full bg-white/90 shadow backdrop-blur transition hover:scale-110 text-navy-500"
              title={t('common.print', 'Print')}
            >
              <Printer className="h-5 w-5" />
            </button>
          </div>
          {showShare && (
            <div className="absolute right-4 top-16 z-20 rounded-xl bg-white p-2 shadow-xl">
              {shareLinks.map((s) => (
                <a
                  key={s.name}
                  href={s.href}
                  target="_blank"
                  rel="noopener"
                  className="block rounded-lg px-3 py-2 text-sm hover:bg-navy-50"
                >
                  {s.name}
                </a>
              ))}
            </div>
          )}
        </motion.div>
        <div className="hidden lg:grid grid-cols-3 gap-2 auto-rows-[100px]">
          {images.slice(0, 6).map((img, i) => (
            <button
              key={i}
              onClick={() => {
                setActiveImg(i);
                setLightbox(true);
              }}
              className={cn('overflow-hidden rounded-lg bg-navy-100', activeImg === i && 'ring-2 ring-navy-500')}
            >
              <img src={img} alt="" className="h-full w-full object-cover transition hover:scale-105" />
            </button>
          ))}
        </div>
      </div>
      <div className="mt-3 flex gap-2 overflow-x-auto lg:hidden">
        {images.map((img, i) => (
          <button
            key={i}
            onClick={() => {
              setActiveImg(i);
              setLightbox(true);
            }}
            className={cn('h-16 w-24 shrink-0 overflow-hidden rounded-lg', activeImg === i && 'ring-2 ring-navy-500')}
          >
            <img src={img} alt="" className="h-full w-full object-cover" />
          </button>
        ))}
      </div>

      {/* Lightbox Modal with Left & Right Carousel Arrows */}
      {lightbox && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 backdrop-blur-md"
          onClick={() => setLightbox(false)}
        >
          {/* Close button */}
          <button
            className="absolute right-6 top-6 z-50 grid h-11 w-11 place-items-center rounded-full bg-white/10 text-white hover:bg-white/25 transition-all shadow-lg"
            onClick={() => setLightbox(false)}
            title="Close Lightbox"
          >
            <X className="h-6 w-6" />
          </button>

          {/* Image counter pill */}
          <div className="absolute top-6 left-1/2 -translate-x-1/2 bg-white/15 backdrop-blur-md text-white font-bold text-xs px-4 py-1.5 rounded-full border border-white/20 shadow-md">
            Image {activeImg + 1} of {images.length}
          </div>

          {/* Left Arrow Button */}
          {images.length > 1 && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                setActiveImg((prev) => (prev - 1 + images.length) % images.length);
              }}
              className="absolute left-4 sm:left-8 top-1/2 -translate-y-1/2 z-50 grid h-12 w-12 sm:h-14 sm:w-14 place-items-center rounded-full bg-white/15 hover:bg-white/30 text-white backdrop-blur-md transition-all shadow-2xl hover:scale-110 cursor-pointer border border-white/20"
              title="Previous Image (Left Arrow)"
            >
              <ChevronLeft className="h-7 w-7" />
            </button>
          )}

          {/* Center Image */}
          <img
            src={images[activeImg]}
            alt={`Property image ${activeImg + 1}`}
            className="max-h-[80vh] max-w-[88vw] object-contain shadow-2xl rounded-2xl select-none"
            onClick={(e) => e.stopPropagation()}
          />

          {/* Right Arrow Button */}
          {images.length > 1 && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                setActiveImg((prev) => (prev + 1) % images.length);
              }}
              className="absolute right-4 sm:right-8 top-1/2 -translate-y-1/2 z-50 grid h-12 w-12 sm:h-14 sm:w-14 place-items-center rounded-full bg-white/15 hover:bg-white/30 text-white backdrop-blur-md transition-all shadow-2xl hover:scale-110 cursor-pointer border border-white/20"
              title="Next Image (Right Arrow)"
            >
              <ChevronRight className="h-7 w-7" />
            </button>
          )}

          {/* Thumbnail Carousel Bar */}
          <div
            className="absolute bottom-6 flex gap-2.5 overflow-x-auto max-w-[90vw] px-4 py-2 bg-black/40 backdrop-blur-md rounded-2xl border border-white/10"
            onClick={(e) => e.stopPropagation()}
          >
            {images.map((img, i) => (
              <button
                key={i}
                onClick={() => setActiveImg(i)}
                className={cn(
                  'h-14 w-20 shrink-0 overflow-hidden rounded-xl border-2 transition-all',
                  activeImg === i
                    ? 'border-white scale-105 shadow-lg'
                    : 'border-transparent opacity-60 hover:opacity-100',
                )}
              >
                <img src={img} alt="" className="h-full w-full object-cover" />
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_360px]">
        <div className="space-y-6">
          <Card className="p-6">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div>
                <h1 className="font-display text-2xl font-bold text-navy-900 sm:text-3xl">{property.title}</h1>
                <p className="mt-1.5 flex items-center gap-1.5 text-sm text-navy-600">
                  <MapPin className="h-4 w-4 text-navy-400" />
                  {property.address ?? `${property.locality_name ?? ''}, ${property.city_name ?? ''}`}
                </p>
              </div>
              <div className="text-right">
                <p className="font-display text-3xl font-extrabold text-navy-900">
                  {formatCompactPrice(property.price)}
                  {property.purpose === 'Rent' && <span className="text-sm font-medium text-navy-500">/mo</span>}
                </p>
                {property.purpose === 'Rent' && property.security_deposit && (
                  <p className="text-xs text-navy-500">Deposit: {formatPrice(property.security_deposit)}</p>
                )}
              </div>
            </div>
            <div className="mt-5 grid grid-cols-2 gap-4 border-t border-navy-100 pt-5 sm:grid-cols-4">
              {[
                { icon: Bed, label: t('property.bedrooms', 'Bedrooms'), value: property.bedrooms },
                { icon: Bath, label: t('property.bathrooms', 'Bathrooms'), value: property.bathrooms },
                {
                  icon: Maximize,
                  label: t('property.builtUp', 'Built-up'),
                  value: property.built_up_area ? `${property.built_up_area} ${t('property.sqft', 'sqft')}` : null,
                },
                { icon: Car, label: t('property.parking', 'Parking'), value: property.parking },
              ].map((s) => (
                <div key={s.label} className="flex items-center gap-3">
                  <div className="grid h-10 w-10 place-items-center rounded-xl bg-navy-50 text-navy-600">
                    <s.icon className="h-5 w-5" />
                  </div>
                  <div>
                    <p className="text-xs text-navy-500">{s.label}</p>
                    <p className="font-semibold text-navy-900">{s.value ?? '—'}</p>
                  </div>
                </div>
              ))}
            </div>
          </Card>

          {property.videos && property.videos.length > 0 && (
            <Card className="p-6">
              <h2 className="font-display text-lg font-semibold text-navy-900">
                {t('property.videoTitle', 'Property Video')}
              </h2>
              <div className="mt-4 aspect-video overflow-hidden rounded-xl bg-navy-100">
                {showVideo ? (
                  <video src={property.videos[0]} controls className="h-full w-full" />
                ) : (
                  <button onClick={() => setShowVideo(true)} className="flex h-full w-full items-center justify-center">
                    <div className="grid h-16 w-16 place-items-center rounded-full bg-white/90 shadow-lg">
                      <Play className="h-8 w-8 text-navy-700 ml-1" />
                    </div>
                  </button>
                )}
              </div>
            </Card>
          )}

          {property.floor_plans && property.floor_plans.length > 0 && (
            <Card className="p-6">
              <h2 className="font-display text-lg font-semibold text-navy-900">
                {t('property.floorPlans', 'Floor Plans')}
              </h2>
              <div className="mt-4 grid gap-3 sm:grid-cols-2">
                {property.floor_plans.map((fp, i) => (
                  <div key={i} className="overflow-hidden rounded-xl border border-navy-100">
                    <img src={fp} alt={`Floor plan ${i + 1}`} className="w-full object-cover" />
                  </div>
                ))}
              </div>
            </Card>
          )}

          {property.documents && property.documents.length > 0 && (
            <Card className="p-6">
              <h2 className="font-display text-lg font-semibold text-navy-900">
                {t('property.documents', 'Documents')}
              </h2>
              <div className="mt-4 space-y-2">
                {property.documents.map((doc, i) => (
                  <a
                    key={i}
                    href={doc}
                    target="_blank"
                    rel="noopener"
                    className="flex items-center gap-2 rounded-lg border border-navy-100 p-3 hover:bg-navy-50"
                  >
                    <FileDown className="h-4 w-4 text-navy-500" /> {t('property.document', 'Document')} {i + 1}
                  </a>
                ))}
              </div>
            </Card>
          )}

          {property.latitude && property.longitude && (
            <Card className="p-6">
              <h2 className="font-display text-lg font-semibold text-navy-900">{t('property.location', 'Location')}</h2>
              <div className="mt-4 aspect-video overflow-hidden rounded-xl bg-navy-100">
                <iframe
                  title="Map"
                  width="100%"
                  height="100%"
                  frameBorder="0"
                  src={`https://www.openstreetmap.org/export/embed.html?bbox=${property.longitude - 0.01}%2C${property.latitude - 0.01}%2C${property.longitude + 0.01}%2C${property.latitude + 0.01}&layer=mapnik&marker=${property.latitude}%2C${property.longitude}`}
                  style={{ border: 0 }}
                  allowFullScreen
                  loading="lazy"
                />
              </div>
            </Card>
          )}

          {property.description && (
            <Card className="p-6">
              <h2 className="font-display text-lg font-semibold text-navy-900">
                {t('property.description', 'Description')}
              </h2>
              <p className="mt-3 whitespace-pre-line text-sm leading-relaxed text-navy-700">{property.description}</p>
            </Card>
          )}

          {property.ai_description && (
            <Card className="border-gold-200 bg-gold-50/40 p-6">
              <div className="flex items-center gap-2">
                <Bot className="h-5 w-5 text-gold-600" />
                <h2 className="font-display text-lg font-semibold text-navy-900">
                  {t('property.aiDescription', 'AI Description')}
                </h2>
              </div>
              <p className="mt-3 whitespace-pre-line text-sm leading-relaxed text-navy-700">
                {property.ai_description}
              </p>
            </Card>
          )}

          <Card className="p-6">
            <h2 className="font-display text-lg font-semibold text-navy-900">{t('property.overview', 'Overview')}</h2>
            <div className="mt-4 grid gap-x-6 gap-y-3 sm:grid-cols-2">
              {[
                { label: t('search.propertyTypeLabel', 'Property type'), value: property.property_type_name },
                { label: t('search.purposeLabel', 'Purpose'), value: property.purpose },
                { label: t('search.furnishingLabel', 'Furnishing'), value: property.furnishing },
                {
                  label: t('property.floor', 'Floor'),
                  value:
                    property.floor_number != null
                      ? `${property.floor_number} of ${property.total_floors ?? '—'}`
                      : null,
                },
                { label: t('search.facingLabel', 'Facing'), value: property.facing },
                {
                  label: t('property.carpetArea', 'Carpet area'),
                  value: property.carpet_area ? `${property.carpet_area} ${t('property.sqft', 'sqft')}` : null,
                },
                {
                  label: t('property.plotArea', 'Plot area'),
                  value: property.plot_area ? `${property.plot_area} ${t('property.sqft', 'sqft')}` : null,
                },
                {
                  label: t('property.ageOfProperty', 'Age of property'),
                  value: property.age_of_property ? `${property.age_of_property} yrs` : null,
                },
                { label: t('property.ownership', 'Ownership'), value: property.ownership_type },
                { label: t('property.balconies', 'Balconies'), value: property.balconies },
              ].map((r) => (
                <div key={r.label} className="flex justify-between border-b border-navy-50 pb-2 text-sm">
                  <span className="text-navy-500">{r.label}</span>
                  <span className="font-medium text-navy-800">{r.value ?? '—'}</span>
                </div>
              ))}
            </div>
          </Card>

          {property.amenities && property.amenities.length > 0 && (
            <Card className="p-6">
              <h2 className="font-display text-lg font-semibold text-navy-900">
                {t('property.amenities', 'Amenities')}
              </h2>
              <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3">
                {property.amenities.map((a) => (
                  <div key={a} className="flex items-center gap-2 text-sm text-navy-700">
                    <Check className="h-4 w-4 text-success-500" /> {a}
                  </div>
                ))}
              </div>
            </Card>
          )}

          {priceHistory && priceHistory.length > 0 && (
            <Card className="p-6">
              <h2 className="font-display text-lg font-semibold text-navy-900">
                {t('property.priceHistory', 'Price History')}
              </h2>
              <div className="mt-4 space-y-2">
                {priceHistory.map((ph) => (
                  <div key={ph.id} className="flex items-center justify-between border-b border-navy-50 pb-2 text-sm">
                    <span className="text-navy-500">{new Date(ph.created_at).toLocaleDateString('en-IN')}</span>
                    <span className="font-medium text-navy-800">{ph.to_status}</span>
                  </div>
                ))}
              </div>
            </Card>
          )}

          {property.latitude && property.longitude && (
            <Card className="p-6">
              <h2 className="font-display text-lg font-semibold text-navy-900">
                {t('property.neighborhood', 'Neighborhood')}
              </h2>
              <div className="mt-4 grid grid-cols-2 gap-4 sm:grid-cols-4">
                {[
                  { label: t('property.schools', 'Schools'), icon: Home, count: '12 nearby' },
                  { label: t('property.hospitals', 'Hospitals'), icon: ShieldCheck, count: '5 nearby' },
                  { label: t('property.metro', 'Metro'), icon: Navigation, count: '1.2 km' },
                  { label: t('property.malls', 'Malls'), icon: Map, count: '3 nearby' },
                ].map((n) => (
                  <div key={n.label} className="flex items-center gap-3 rounded-xl border border-navy-100 p-3">
                    <n.icon className="h-5 w-5 text-navy-400" />
                    <div>
                      <p className="text-xs text-navy-500">{n.label}</p>
                      <p className="text-sm font-semibold text-navy-800">{n.count}</p>
                    </div>
                  </div>
                ))}
              </div>
            </Card>
          )}

          {/* Reviews with submission */}
          <Card className="p-6">
            <div className="flex items-center justify-between">
              <h2 className="font-display text-lg font-semibold text-navy-900">{t('property.reviews', 'Reviews')}</h2>
              <div className="flex items-center gap-3">
                {reviews && reviews.length > 0 && (
                  <div className="flex items-center gap-2 text-sm">
                    <RatingStars
                      rating={reviews.reduce((a: number, r: { rating: number }) => a + r.rating, 0) / reviews.length}
                    />
                    <span className="text-navy-600">
                      {reviews.length} {t('property.reviewsCount', 'reviews')}
                    </span>
                  </div>
                )}
                <Button
                  size="sm"
                  variant="secondary"
                  onClick={() => (user ? setReviewOpen(true) : navigate('/login'))}
                  icon={<Star className="h-4 w-4" />}
                >
                  {t('property.writeReview', 'Write a review')}
                </Button>
              </div>
            </div>
            {reviews && reviews.length > 0 ? (
              <div className="mt-4 space-y-4">
                {reviews.map((r: Record<string, unknown>) => {
                  const p = r.profiles as Record<string, unknown> | Record<string, unknown>[] | null;
                  const rp = Array.isArray(p) ? p[0] : p;
                  return (
                    <div key={r.id as string} className="border-b border-navy-50 pb-4 last:border-0">
                      <div className="flex items-center gap-3">
                        <Avatar
                          name={`${rp?.first_name ?? ''} ${rp?.last_name ?? ''}`.trim() || 'User'}
                          src={(rp?.avatar_url as string) ?? null}
                          size={36}
                        />
                        <div>
                          <p className="text-sm font-semibold text-navy-900">{String(rp?.first_name ?? 'Anonymous')}</p>
                          <RatingStars rating={r.rating as number} size={12} />
                        </div>
                      </div>
                      {r.comment ? <p className="mt-2 text-sm text-navy-700">{r.comment as string}</p> : null}
                    </div>
                  );
                })}
              </div>
            ) : (
              <p className="mt-4 text-sm text-navy-400">
                {t('property.noReviews', 'No reviews yet. Be the first to review!')}
              </p>
            )}
          </Card>
        </div>

        {/* Sidebar */}
        <aside className="space-y-4 lg:sticky lg:top-24 lg:self-start">
          <Card className="p-5">
            <div className="flex items-center justify-between">
              <span className="text-sm text-navy-500">{t('property.managedBy', 'Managed by')}</span>
              <StatusBadge status={property.status} />
            </div>
            <div className="mt-3 flex items-center gap-3">
              <Avatar name={agentName} src={agent?.avatar_url ?? null} size={44} />
              <div className="min-w-0">
                <p className="font-semibold text-navy-900 truncate">{agentName}</p>
                {agent?.company && <p className="text-xs text-navy-500 truncate">{agent.company}</p>}
                {agent?.license_number && (
                  <p className="text-xs text-navy-500">
                    {t('property.license', 'License')}: {agent.license_number}
                  </p>
                )}
              </div>
            </div>
            {agent?.bio && <p className="mt-3 text-xs text-navy-600 line-clamp-2">{agent.bio}</p>}
            <div className="mt-4 grid gap-2">
              <Button onClick={() => setContactOpen(true)} icon={<Mail className="h-4 w-4" />} className="w-full">
                {t('property.contactAgent', 'Contact Agent')}
              </Button>
              <Button
                variant="secondary"
                icon={<Calendar className="h-4 w-4" />}
                className="w-full"
                onClick={() => (user ? setApptOpen(true) : navigate('/login'))}
              >
                {t('property.bookVisit', 'Book a Visit')}
              </Button>
              {agent?.phone && (
                <a href={`tel:${agent.phone}`}>
                  <Button variant="ghost" icon={<Phone className="h-4 w-4" />} className="w-full">
                    {agent.phone}
                  </Button>
                </a>
              )}
            </div>
            <div className="mt-4 flex items-center gap-3 rounded-lg bg-navy-50 px-3 py-2 text-xs text-navy-600">
              <ShieldCheck className="h-4 w-4 text-success-500" /> {t('property.verifiedBy', 'Verified by RealtyNow')}
            </div>
          </Card>

          <Card className="p-5">
            <p className="text-sm font-semibold text-navy-900">{t('property.insights', 'Property insights')}</p>
            <div className="mt-3 space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-navy-500">{t('property.views', 'Views')}</span>
                <span className="font-medium text-navy-800 flex items-center gap-1">
                  <Eye className="h-3.5 w-3.5" /> {formatNumber(property.view_count)}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-navy-500">{t('property.posted', 'Posted')}</span>
                <span className="font-medium text-navy-800">
                  {new Date(property.created_at).toLocaleDateString('en-IN', {
                    day: 'numeric',
                    month: 'short',
                    year: 'numeric',
                  })}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-navy-500">{t('property.propertyId', 'Property ID')}</span>
                <span className="font-mono text-xs text-navy-700">{property.id.slice(0, 8)}</span>
              </div>
            </div>
          </Card>
        </aside>
      </div>

      {/* Similar properties */}
      {similar && similar.length > 0 && (
        <section className="mt-16">
          <h2 className="font-display text-2xl font-bold text-navy-900">
            {t('property.similarProperties', 'Similar Properties')}
          </h2>
          <div className="mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {similar.map((p) => (
              <PropertyCard key={p.id} property={p as unknown as Parameters<typeof PropertyCard>[0]['property']} />
            ))}
          </div>
        </section>
      )}

      {/* Recently viewed */}
      {recentViews && recentViews.length > 0 && (
        <section className="mt-16">
          <h2 className="font-display text-2xl font-bold text-navy-900">
            {t('property.recentlyViewed', 'Recently Viewed')}
          </h2>
          <div className="mt-6 grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
            {recentViews.map((p) => (
              <PropertyCard key={p.id} property={p as unknown as Parameters<typeof PropertyCard>[0]['property']} />
            ))}
          </div>
        </section>
      )}

      {/* Contact modal */}
      <Modal
        open={contactOpen}
        onClose={() => setContactOpen(false)}
        title={t('property.contactAgent', 'Contact Agent')}
        footer={
          <Button
            loading={enquiryMutation.isPending}
            onClick={() => enquiryMutation.mutate()}
            icon={<Send className="h-4 w-4" />}
            className="w-full"
          >
            {t('forms.sendEnquiry', 'Send enquiry')}
          </Button>
        }
      >
        <p className="mb-4 text-sm text-navy-500">
          {t('property.shareDetailsMsg', 'Share your details. The agent will reach out shortly.')}
        </p>
        <div className="space-y-3">
          <Input
            label={t('forms.name', 'Name')}
            value={form.name}
            onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
            placeholder={t('forms.yourName', 'Your name')}
          />
          <Input
            label={t('forms.email', 'Email')}
            type="email"
            value={form.email}
            onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))}
            placeholder="you@email.com"
          />
          <Input
            label={t('forms.phone', 'Phone')}
            value={form.phone}
            onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))}
            placeholder="+91 90000 00000"
          />
          <Textarea
            label={t('forms.message', 'Message')}
            value={form.message}
            onChange={(e) => setForm((f) => ({ ...f, message: e.target.value }))}
            placeholder={t('forms.interestedMsg', "I'm interested in this property. Please share more details.")}
          />
          {enquiryMutation.isSuccess && (
            <p className="text-sm text-success-600 flex items-center gap-1">
              <Check className="h-4 w-4" />{' '}
              {t('property.enquirySentMsg', 'Enquiry sent! The agent will contact you soon.')}
            </p>
          )}
        </div>
      </Modal>

      {/* Appointment modal */}
      <Modal
        open={apptOpen}
        onClose={() => setApptOpen(false)}
        title={t('property.bookVisit', 'Book a property visit')}
        footer={
          <Button
            loading={apptMutation.isPending}
            onClick={() => apptMutation.mutate()}
            icon={<Calendar className="h-4 w-4" />}
            className="w-full"
          >
            {t('forms.requestAppointment', 'Request appointment')}
          </Button>
        }
      >
        <p className="mb-4 text-sm text-navy-500">
          {t('property.pickDateMsg', 'Pick a date and time to visit this property. The agent will confirm.')}
        </p>
        <div className="space-y-3">
          <div className="grid gap-3 sm:grid-cols-2">
            <Input
              label={t('forms.date', 'Date')}
              type="date"
              value={apptForm.date}
              onChange={(e) => setApptForm((f) => ({ ...f, date: e.target.value }))}
            />
            <Input
              label={t('forms.time', 'Time')}
              type="time"
              value={apptForm.time}
              onChange={(e) => setApptForm((f) => ({ ...f, time: e.target.value }))}
            />
          </div>
          <Textarea
            label={t('forms.notesOptional', 'Notes (optional)')}
            value={apptForm.notes}
            onChange={(e) => setApptForm((f) => ({ ...f, notes: e.target.value }))}
            placeholder={t('forms.specificRequests', 'Any specific requests or questions')}
          />
          {apptMutation.isSuccess && (
            <p className="text-sm text-success-600 flex items-center gap-1">
              <Check className="h-4 w-4" />{' '}
              {t('property.apptRequestedMsg', 'Appointment requested! Check your portal for updates.')}
            </p>
          )}
        </div>
      </Modal>

      {/* Review modal */}
      <Modal
        open={reviewOpen}
        onClose={() => setReviewOpen(false)}
        title={t('property.writeReview', 'Write a review')}
        footer={
          <Button
            loading={reviewMutation.isPending}
            onClick={() => reviewMutation.mutate()}
            icon={<Star className="h-4 w-4" />}
            className="w-full"
          >
            {t('forms.submitReview', 'Submit review')}
          </Button>
        }
      >
        <div className="space-y-4">
          <div>
            <label className="label">{t('forms.rating', 'Rating')}</label>
            <div className="flex gap-1">
              {[1, 2, 3, 4, 5].map((i) => (
                <button
                  key={i}
                  type="button"
                  onClick={() => setReviewForm((f) => ({ ...f, rating: i }))}
                  className={i <= reviewForm.rating ? 'text-gold-400' : 'text-navy-200'}
                >
                  <Star className="h-6 w-6 fill-current" />
                </button>
              ))}
            </div>
          </div>
          <Textarea
            label={t('forms.comment', 'Comment')}
            value={reviewForm.comment}
            onChange={(e) => setReviewForm((f) => ({ ...f, comment: e.target.value }))}
            placeholder={t('forms.shareExperience', 'Share your experience with this property')}
          />
          {reviewMutation.isSuccess && (
            <p className="text-sm text-success-600 flex items-center gap-1">
              <Check className="h-4 w-4" /> {t('property.reviewSubmitted', 'Review submitted!')}
            </p>
          )}
        </div>
      </Modal>
    </div>
  );
}

import { useMemo, useState, useCallback } from 'react';
