// ──────────────────────────────────────────────────────────────
// AI Score Badge
// ──────────────────────────────────────────────────────────────
function AIScoreBadge({ score }: { score: number }) {
  const color =
    score >= 90
      ? 'from-emerald-500 to-green-600'
      : score >= 75
        ? 'from-amber-500 to-orange-500'
        : 'from-slate-400 to-slate-500';
  return (
    <span
      className={`inline-flex items-center gap-1 rounded-full bg-gradient-to-r ${color} px-2 py-0.5 text-[10px] font-extrabold text-white shadow`}
    >
      <Sparkles className="h-2.5 w-2.5" />
      AI {score}%
    </span>
  );
}

// ──────────────────────────────────────────────────────────────
// Property Horizontal List Card (desktop/tablet)
// ──────────────────────────────────────────────────────────────
interface HorizontalCardProps {
  property: Property & { city_name?: string; locality_name?: string; property_type_name?: string };
  onSave?: (id: string) => void;
  onCompare?: (id: string) => void;
  saved?: boolean;
  compared?: boolean;
}

function HorizontalCard({ property: p, onSave, onCompare, saved = false, compared = false }: HorizontalCardProps) {
  const { t } = useLanguageContext();
  const navigate = useNavigate();
  const [activeImg, setActiveImg] = useState(0);
  const [hovered, setHovered] = useState(false);
  const [imgHovered, setImgHovered] = useState(false);

  const images = p.images?.length ? p.images : ['https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg'];
  const aiScore = useMemo(() => Math.floor(75 + Math.random() * 25), [p.id]);
  const investScore = useMemo(() => Math.floor(60 + Math.random() * 35), [p.id]);
  const pricePerSqft = p.built_up_area && p.price ? Math.round(p.price / p.built_up_area) : null;

  const topAmenities = (p.amenities ?? []).slice(0, 5);
  const amenityIcons: Record<string, string> = {
    'Swimming Pool': '🏊',
    Gym: '💪',
    'Club House': '🏛️',
    Security: '🛡️',
    'Power Backup': '⚡',
    'Children Park': '🛝',
    Lift: '🛗',
    Garden: '🌿',
  };

  const handleContact = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    navigate(`/property/${p.id}`);
  };

  return (
    <motion.article
      initial={{ opacity: 0, y: 16 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, ease: 'easeOut' }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      className={cn(
        'group relative flex flex-col sm:flex-row bg-white rounded-[20px] overflow-hidden border transition-all duration-300 cursor-pointer',
        hovered ? 'shadow-2xl shadow-slate-200/80 border-slate-200 -translate-y-0.5' : 'shadow-md border-slate-100',
      )}
      style={{ minHeight: 240 }}
      onClick={() => navigate(`/property/${p.id}`)}
    >
      {/* ── IMAGE PANEL (38%) ── */}
      <div
        className="relative w-full sm:w-[38%] shrink-0 overflow-hidden"
        style={{ minHeight: 220 }}
        onMouseEnter={() => setImgHovered(true)}
        onMouseLeave={() => setImgHovered(false)}
      >
        <img
          src={images[activeImg]}
          alt={p.title}
          className={cn(
            'h-full w-full object-cover transition-transform duration-500',
            imgHovered ? 'scale-110' : 'scale-100',
          )}
          style={{ minHeight: 220 }}
          loading="lazy"
        />

        {/* Gradient overlay */}
        <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-black/10" />

        {/* Top-left badges */}
        <div className="absolute top-3 left-3 flex flex-wrap gap-1.5 z-10">
          {p.purpose && (
            <span
              className={cn(
                'text-[10px] font-extrabold px-2 py-0.5 rounded-full uppercase tracking-wide shadow',
                p.purpose === 'Rent' ? 'bg-blue-600 text-white' : 'bg-red-600 text-white',
              )}
            >
              {p.purpose === 'Rent' ? t('property.forRent', 'For Rent') : t('property.forSale', 'For Sale')}
            </span>
          )}
          {p.is_featured && (
            <span className="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-amber-500 text-white shadow uppercase">
              {t('common.featured', 'Featured')}
            </span>
          )}
          {p.is_luxury && (
            <span className="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-purple-600 text-white shadow uppercase">
              {t('common.luxury', 'Luxury')}
            </span>
          )}
          {p.has_virtual_tour && (
            <span className="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-emerald-600 text-white shadow flex items-center gap-1 uppercase">
              <Camera className="h-2.5 w-2.5" /> 360°
            </span>
          )}
          {p.videos && p.videos.length > 0 && (
            <span className="text-[10px] font-extrabold px-2 py-0.5 rounded-full bg-rose-600 text-white shadow flex items-center gap-1 uppercase">
              <Play className="h-2.5 w-2.5" /> Video
            </span>
          )}
        </div>

        {/* Top-right actions */}
        <div className="absolute top-3 right-3 flex gap-1.5 z-10" onClick={(e) => e.stopPropagation()}>
          <button
            onClick={(e) => {
              e.stopPropagation();
              onSave?.(p.id);
            }}
            className={cn(
              'grid h-8 w-8 place-items-center rounded-full bg-white/90 shadow-md backdrop-blur-sm transition hover:scale-110',
              saved ? 'text-red-600' : 'text-slate-500',
            )}
          >
            <Heart className={cn('h-4 w-4', saved && 'fill-red-600')} />
          </button>
          <button className="grid h-8 w-8 place-items-center rounded-full bg-white/90 shadow-md backdrop-blur-sm text-slate-500 hover:scale-110 transition">
            <Share2 className="h-4 w-4" />
          </button>
        </div>

        {/* Image gallery dots + count */}
        {images.length > 1 && (
          <div className="absolute bottom-3 left-0 right-0 flex items-center justify-center gap-1 z-10">
            {images.slice(0, 5).map((_, i) => (
              <button
                key={i}
                onClick={(e) => {
                  e.stopPropagation();
                  setActiveImg(i);
                }}
                className={cn(
                  'h-1.5 rounded-full transition-all',
                  activeImg === i ? 'w-5 bg-white' : 'w-1.5 bg-white/50',
                )}
              />
            ))}
          </div>
        )}
        <div className="absolute bottom-3 right-3 bg-black/50 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-0.5 rounded-full flex items-center gap-1">
          <Camera className="h-2.5 w-2.5" /> {images.length}
        </div>

        {/* AI match chip */}
        <div className="absolute top-10 right-3 z-10">
          <AIScoreBadge score={aiScore} />
        </div>
      </div>

      {/* ── CONTENT PANEL (62%) ── */}
      <div className="flex flex-1 flex-col p-4 sm:p-5 justify-between min-w-0">
        {/* Header: Title + Price */}
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div className="min-w-0 flex-1">
            <h2 className="font-display text-base sm:text-lg font-bold text-slate-900 truncate leading-tight">
              {p.title}
            </h2>
            <div className="mt-1 flex items-center gap-1.5 text-xs text-slate-500">
              <MapPin className="h-3 w-3 text-red-500 shrink-0" />
              <span className="truncate">{[p.address, p.locality_name, p.city_name].filter(Boolean).join(', ')}</span>
            </div>
            {p.property_type_name && (
              <div className="mt-1 flex items-center gap-2 flex-wrap">
                <span className="text-[11px] font-semibold text-slate-500 bg-slate-100 px-2 py-0.5 rounded-full">
                  {p.property_type_name}
                </span>
                {(p as any).is_verified && (
                  <span className="text-[11px] font-semibold text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded-full flex items-center gap-0.5">
                    <CheckCircle2 className="h-3 w-3" /> {t('common.verified', 'Verified')}
                  </span>
                )}
              </div>
            )}
          </div>
          <div className="text-right shrink-0">
            <p className="font-display text-xl sm:text-2xl font-extrabold text-slate-900">
              {formatCompactPrice(p.price)}
            </p>
            {pricePerSqft && <p className="text-[11px] text-slate-500 mt-0.5">₹{formatNumber(pricePerSqft)}/sq.ft</p>}
            {p.purpose === 'Rent' && <p className="text-[11px] text-slate-500">/month</p>}
          </div>
        </div>

        {/* Specs row */}
        <div className="mt-3 flex flex-wrap gap-x-4 gap-y-1.5">
          {[
            p.bedrooms != null && { icon: Bed, val: `${p.bedrooms} BHK`, key: 'bed' },
            p.bathrooms != null && { icon: Bath, val: `${p.bathrooms} Bath`, key: 'bath' },
            p.parking != null && { icon: Car, val: `${p.parking} Park`, key: 'park' },
            p.built_up_area && { icon: Maximize2, val: `${formatNumber(p.built_up_area)} sq.ft`, key: 'area' },
          ]
            .filter(Boolean)
            .map((s: any) => (
              <div key={s.key} className="flex items-center gap-1 text-sm text-slate-700">
                <s.icon className="h-3.5 w-3.5 text-slate-400 shrink-0" />
                <span className="font-semibold">{s.val}</span>
              </div>
            ))}
          {p.floor_number != null && (
            <div className="flex items-center gap-1 text-sm text-slate-700">
              <Building2 className="h-3.5 w-3.5 text-slate-400" />
              <span className="font-semibold">
                Floor {p.floor_number}
                {p.total_floors ? `/${p.total_floors}` : ''}
              </span>
            </div>
          )}
          {p.facing && (
            <div className="flex items-center gap-1 text-sm text-slate-700">
              <Navigation className="h-3.5 w-3.5 text-slate-400" />
              <span className="font-semibold">{p.facing}</span>
            </div>
          )}
        </div>

        {/* Nearby chips */}
        <div className="mt-3 flex flex-wrap gap-1.5">
          {[
            { label: 'Metro 800m', icon: '🚇' },
            { label: 'School 500m', icon: '🏫' },
            { label: 'Hospital 1.2km', icon: '🏥' },
          ].map((n) => (
            <span
              key={n.label}
              className="inline-flex items-center gap-1 rounded-full border border-slate-100 bg-slate-50 px-2 py-0.5 text-[11px] text-slate-600"
            >
              {n.icon} {n.label}
            </span>
          ))}
        </div>

        {/* Amenities */}
        {topAmenities.length > 0 && (
          <div className="mt-3 flex flex-wrap gap-1.5">
            {topAmenities.map((a) => (
              <span
                key={a}
                className="inline-flex items-center gap-1 rounded-full border border-slate-200 bg-white px-2 py-0.5 text-[11px] font-medium text-slate-700"
              >
                {amenityIcons[a] ?? '✓'} {a}
              </span>
            ))}
            {(p.amenities?.length ?? 0) > 5 && (
              <span className="text-[11px] font-semibold text-red-600 px-1">
                +{(p.amenities?.length ?? 0) - 5} more
              </span>
            )}
          </div>
        )}

        {/* AI Insight chips */}
        <div className="mt-3 flex flex-wrap gap-1.5">
          <span className="inline-flex items-center gap-1 rounded-full bg-emerald-50 border border-emerald-100 px-2 py-0.5 text-[11px] font-bold text-emerald-700">
            <TrendingUp className="h-3 w-3" /> Invest {investScore}%
          </span>
          <span className="inline-flex items-center gap-1 rounded-full bg-blue-50 border border-blue-100 px-2 py-0.5 text-[11px] font-bold text-blue-700">
            <BarChart3 className="h-3 w-3" /> Rental Yield {(2.5 + Math.random() * 2).toFixed(1)}%
          </span>
          <span className="inline-flex items-center gap-1 rounded-full bg-violet-50 border border-violet-100 px-2 py-0.5 text-[11px] font-bold text-violet-700">
            <Zap className="h-3 w-3" /> High Demand
          </span>
        </div>

        {/* Footer: Updated time + Actions */}
        <div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-slate-100 pt-3">
          <div className="flex items-center gap-1.5 text-[11px] text-slate-400">
            <Clock className="h-3 w-3" />
            <span>Updated {new Date(p.updated_at).toLocaleDateString()}</span>
            {p.view_count && (
              <>
                <span className="text-slate-200">·</span>
                <Eye className="h-3 w-3" />
                <span>{formatNumber(p.view_count)} views</span>
              </>
            )}
          </div>

          {/* Action buttons */}
          <div className="flex items-center gap-1.5 w-full xl:w-auto overflow-x-auto hide-scrollbar" onClick={(e) => e.stopPropagation()}>
            <button
              onClick={handleContact}
              className="flex flex-1 xl:flex-none justify-center items-center gap-1.5 rounded-xl bg-red-600 hover:bg-red-700 px-2.5 py-1.5 text-[11px] xl:text-xs font-bold text-white transition-all hover:scale-[1.02] shadow-sm shadow-red-600/30 whitespace-nowrap"
            >
              <Phone className="h-3.5 w-3.5" /> {t('property.contactAgent', 'Contact')}
            </button>
            <button
              onClick={handleContact}
              className="flex flex-1 xl:flex-none justify-center items-center gap-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-700 px-2.5 py-1.5 text-[11px] xl:text-xs font-bold text-white transition-all hover:scale-[1.02] shadow-sm shadow-emerald-600/30 whitespace-nowrap"
            >
              <MessageCircle className="h-3.5 w-3.5" /> WhatsApp
            </button>
            <button
              onClick={handleContact}
              className="flex flex-1 xl:flex-none justify-center items-center gap-1.5 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 px-2.5 py-1.5 text-[11px] xl:text-xs font-bold text-slate-700 transition-all hover:scale-[1.02] whitespace-nowrap"
            >
              <Calendar className="h-3.5 w-3.5" /> {t('property.bookVisit', 'Visit')}
            </button>
            <Link
              to={`/property/${p.id}`}
              className="flex flex-1 xl:flex-none justify-center items-center gap-1.5 rounded-xl border border-red-200 bg-red-50 hover:bg-red-100 px-2.5 py-1.5 text-[11px] xl:text-xs font-bold text-red-600 transition-all hover:scale-[1.02] whitespace-nowrap"
              onClick={(e) => e.stopPropagation()}
            >
              <Eye className="h-3.5 w-3.5" /> {t('common.viewDetails', 'Details')}
            </Link>
            <button
              onClick={(e) => {
                e.stopPropagation();
                onCompare?.(p.id);
              }}
              className={cn(
                'grid h-8 w-8 place-items-center rounded-xl border transition hover:scale-[1.02]',
                compared
                  ? 'border-blue-400 bg-blue-50 text-blue-600'
                  : 'border-slate-200 bg-white text-slate-500 hover:bg-slate-50',
              )}
              title={t('property.addToCompare', 'Compare')}
            >
              <GitCompare className="h-4 w-4" />
            </button>
            <button
              onClick={(e) => {
                e.stopPropagation();
                onSave?.(p.id);
              }}
              className={cn(
                'grid h-8 w-8 place-items-center rounded-xl border transition hover:scale-[1.02]',
                saved
                  ? 'border-red-400 bg-red-50 text-red-600'
                  : 'border-slate-200 bg-white text-slate-500 hover:bg-slate-50',
              )}
              title={t('property.saveProperty', 'Save')}
            >
              <BookmarkPlus className="h-4 w-4" />
            </button>
          </div>
        </div>
      </div>
    </motion.article>
  );
}

// ──────────────────────────────────────────────────────────────
// Property Grid Card (compact)
// ──────────────────────────────────────────────────────────────
function GridCard({
  property: p,
}: {
  property: Property & { city_name?: string; locality_name?: string; property_type_name?: string };
}) {
  const { t } = useLanguageContext();
  const navigate = useNavigate();
  const images = p.images?.length ? p.images : ['https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg'];
  const aiScore = useMemo(() => Math.floor(75 + Math.random() * 25), [p.id]);

  return (
    <motion.article
      initial={{ opacity: 0, scale: 0.97 }}
      animate={{ opacity: 1, scale: 1 }}
      transition={{ duration: 0.25 }}
      className="group relative flex flex-col bg-white rounded-2xl overflow-hidden border border-slate-100 shadow-md hover:shadow-xl hover:-translate-y-1 transition-all duration-300 cursor-pointer"
      onClick={() => navigate(`/property/${p.id}`)}
    >
      <div className="relative aspect-[4/3] overflow-hidden">
        <img
          src={images[0]}
          alt={p.title}
          className="h-full w-full object-cover group-hover:scale-105 transition-transform duration-500"
          loading="lazy"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent" />
        <div className="absolute top-2 left-2 flex gap-1 flex-wrap">
          {p.purpose && (
            <span
              className={cn(
                'text-[10px] font-bold px-1.5 py-0.5 rounded-full',
                p.purpose === 'Rent' ? 'bg-blue-600 text-white' : 'bg-red-600 text-white',
              )}
            >
              {p.purpose === 'Rent' ? t('property.forRent', 'Rent') : t('property.forSale', 'Sale')}
            </span>
          )}
          {p.is_featured && (
            <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-amber-500 text-white">
              {t('common.featured', 'Featured')}
            </span>
          )}
        </div>
        <button
          className="absolute top-2 right-2 grid h-7 w-7 place-items-center rounded-full bg-white/90 text-slate-500 shadow"
          onClick={(e) => e.stopPropagation()}
        >
          <Heart className="h-3.5 w-3.5" />
        </button>
        <div className="absolute bottom-2 right-2">
          <AIScoreBadge score={aiScore} />
        </div>
        <div className="absolute bottom-2 left-2 text-white font-display font-extrabold text-base">
          {formatCompactPrice(p.price)}
        </div>
      </div>
      <div className="p-3">
        <h3 className="font-bold text-slate-900 text-sm truncate">{p.title}</h3>
        <p className="text-[11px] text-slate-500 mt-0.5 truncate flex items-center gap-0.5">
          <MapPin className="h-3 w-3 shrink-0 text-red-400" />
          {p.locality_name}, {p.city_name}
        </p>
        <div className="mt-2 flex items-center gap-3 text-xs text-slate-700">
          {p.bedrooms != null && (
            <span className="flex items-center gap-0.5">
              <Bed className="h-3 w-3 text-slate-400" />
              {p.bedrooms} BHK
            </span>
          )}
          {p.bathrooms != null && (
            <span className="flex items-center gap-0.5">
              <Bath className="h-3 w-3 text-slate-400" />
              {p.bathrooms}
            </span>
          )}
          {p.built_up_area && (
            <span className="flex items-center gap-0.5">
              <Maximize2 className="h-3 w-3 text-slate-400" />
              {formatNumber(p.built_up_area)} sqft
            </span>
          )}
        </div>
        <Link
          to={`/property/${p.id}`}
          className="mt-3 block w-full text-center rounded-xl bg-red-600 hover:bg-red-700 py-1.5 text-xs font-bold text-white transition"
          onClick={(e) => e.stopPropagation()}
        >
          {t('common.viewDetails', 'View Details')}
        </Link>
      </div>
    </motion.article>
  );
}

// ──────────────────────────────────────────────────────────────
// Skeleton
// ──────────────────────────────────────────────────────────────
function ListSkeleton() {
  return (
    <div
      className="flex gap-0 sm:gap-4 bg-white rounded-[20px] border border-slate-100 shadow-md overflow-hidden animate-pulse"
      style={{ minHeight: 240 }}
    >
      <div className="w-full sm:w-[38%] bg-slate-200 shrink-0" style={{ minHeight: 220 }} />
      <div className="flex-1 p-5 space-y-3">
        <div className="h-6 bg-slate-200 rounded-lg w-3/4" />
        <div className="h-4 bg-slate-100 rounded-lg w-1/2" />
        <div className="h-8 bg-slate-100 rounded-xl w-1/3" />
        <div className="flex gap-3">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="h-5 bg-slate-100 rounded-lg w-16" />
          ))}
        </div>
        <div className="flex gap-2 mt-auto">
          {Array.from({ length: 5 }).map((_, i) => (
            <div key={i} className="h-8 bg-slate-100 rounded-xl w-20" />
          ))}
        </div>
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// Filter Sidebar
// ──────────────────────────────────────────────────────────────
interface FilterSidebarProps {
  params: URLSearchParams;
  setFilter: (k: string, v: string) => void;
  clearAll: () => void;
  activeCount: number;
  types: { id: string; name: string; category: string }[];
  cities: { id: string; name: string }[];
  localities: { id: string; name: string; city_id: string }[];
}

function FilterSidebar({ params, setFilter, clearAll, activeCount, types, cities, localities }: FilterSidebarProps) {
  const { t } = useLanguageContext();
  const [openSections, setOpenSections] = useState<string[]>(['purpose', 'location', 'price', 'details']);
  const toggle = (s: string) =>
    setOpenSections((prev) => (prev.includes(s) ? prev.filter((x) => x !== s) : [...prev, s]));
  const open = (s: string) => openSections.includes(s);

  const SectionHeader = ({ id, label }: { id: string; label: string }) => (
    <button
      className="flex w-full items-center justify-between py-2 text-sm font-bold text-slate-800"
      onClick={() => toggle(id)}
    >
      {label}
      <ChevronDown className={cn('h-4 w-4 text-slate-400 transition-transform', open(id) && 'rotate-180')} />
    </button>
  );

  return (
    <div className="rounded-2xl border border-slate-100 bg-white shadow-md overflow-hidden">
      {/* Sidebar Header */}
      <div className="flex items-center justify-between p-4 border-b border-slate-100">
        <h2 className="font-bold text-slate-900 flex items-center gap-2">
          <SlidersHorizontal className="h-4 w-4 text-red-600" />
          {t('search.filtersHeader', 'Filters')}
          {activeCount > 0 && (
            <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-red-600 text-[10px] font-extrabold text-white">
              {activeCount}
            </span>
          )}
        </h2>
        {activeCount > 0 && (
          <button
            onClick={clearAll}
            className="flex items-center gap-1 text-xs text-red-600 hover:text-red-700 font-semibold"
          >
            <X className="h-3.5 w-3.5" /> {t('search.clearAll', 'Clear All')}
          </button>
        )}
      </div>

      <div className="p-4 space-y-1 max-h-[calc(100vh-200px)] overflow-y-auto">
        {/* Purpose */}
        <div className="border-b border-slate-50 pb-2">
          <SectionHeader id="purpose" label={t('search.purposeLabel', 'Purpose')} />
          {open('purpose') && (
            <div className="grid grid-cols-2 gap-2 mt-2">
              {[
                { v: 'Sale', l: t('common.sale', 'Buy') },
                { v: 'Rent', l: t('common.rent', 'Rent') },
              ].map(({ v, l }) => (
                <button
                  key={v}
                  onClick={() => setFilter('purpose', params.get('purpose') === v ? '' : v)}
                  className={cn(
                    'rounded-xl py-2 text-sm font-bold transition border',
                    params.get('purpose') === v
                      ? 'bg-red-600 text-white border-red-600 shadow-md shadow-red-600/20'
                      : 'bg-slate-50 text-slate-700 border-slate-200 hover:border-red-300 hover:bg-red-50',
                  )}
                >
                  {l}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Location */}
        <div className="border-b border-slate-50 pb-2">
          <SectionHeader id="location" label={t('search.cityLabel', 'Location')} />
          {open('location') && (
            <div className="mt-2 space-y-2">
              <select
                value={params.get('city') ?? ''}
                onChange={(e) => setFilter('city', e.target.value)}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-700 focus:border-red-400 focus:outline-none focus:ring-1 focus:ring-red-200"
              >
                <option value="">{t('search.anyCity', 'Any City')}</option>
                {cities?.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
              <select
                value={params.get('locality') ?? ''}
                onChange={(e) => setFilter('locality', e.target.value)}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-700 focus:border-red-400 focus:outline-none focus:ring-1 focus:ring-red-200"
              >
                <option value="">{t('search.anyLocality', 'Any Locality')}</option>
                {localities?.map((l) => (
                  <option key={l.id} value={l.id}>
                    {l.name}
                  </option>
                ))}
              </select>
            </div>
          )}
        </div>

        {/* Property Type */}
        <div className="border-b border-slate-50 pb-2">
          <SectionHeader id="type" label={t('search.propertyTypeLabel', 'Property Type')} />
          {open('type') && (
            <div className="mt-2">
              <select
                value={params.get('type_id') ?? ''}
                onChange={(e) => setFilter('type_id', e.target.value)}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm text-slate-700 focus:border-red-400 focus:outline-none focus:ring-1 focus:ring-red-200"
              >
                <option value="">{t('search.anyType', 'Any Type')}</option>
                {types?.map((t2) => (
                  <option key={t2.id} value={t2.id}>
                    {t2.name}
                  </option>
                ))}
              </select>
            </div>
          )}
        </div>

        {/* Price */}
        <div className="border-b border-slate-50 pb-2">
          <SectionHeader id="price" label={t('search.priceRange', 'Price Range')} />
          {open('price') && (
            <div className="mt-2 grid grid-cols-2 gap-2">
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">
                  {t('search.minPrice', 'Min ₹')}
                </label>
                <input
                  type="number"
                  placeholder="0"
                  value={params.get('min_price') ?? ''}
                  onChange={(e) => setFilter('min_price', e.target.value)}
                  className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm focus:border-red-400 focus:outline-none"
                />
              </div>
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">
                  {t('search.maxPrice', 'Max ₹')}
                </label>
                <input
                  type="number"
                  placeholder="∞"
                  value={params.get('max_price') ?? ''}
                  onChange={(e) => setFilter('max_price', e.target.value)}
                  className="w-full rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm focus:border-red-400 focus:outline-none"
                />
              </div>
            </div>
          )}
        </div>

        {/* Details */}
        <div className="border-b border-slate-50 pb-2">
          <SectionHeader id="details" label={t('search.bedroomsLabel', 'Bedrooms & Bathrooms')} />
          {open('details') && (
            <div className="mt-2 space-y-3">
              <div>
                <p className="text-[11px] font-bold text-slate-500 mb-1.5">{t('search.bedroomsLabel', 'Bedrooms')}</p>
                <div className="flex gap-1.5 flex-wrap">
                  {['', '1', '2', '3', '4', '5+'].map((b) => (
                    <button
                      key={b}
                      onClick={() => setFilter('bedrooms', b === '5+' ? '5' : b)}
                      className={cn(
                        'h-8 px-3 rounded-xl text-xs font-bold border transition',
                        params.get('bedrooms') === (b === '5+' ? '5' : b)
                          ? 'bg-red-600 text-white border-red-600'
                          : 'bg-slate-50 text-slate-700 border-slate-200 hover:border-red-300',
                      )}
                    >
                      {b || t('search.any', 'Any')}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <p className="text-[11px] font-bold text-slate-500 mb-1.5">{t('search.bathroomsLabel', 'Bathrooms')}</p>
                <div className="flex gap-1.5">
                  {['', '1', '2', '3', '4'].map((b) => (
                    <button
                      key={b}
                      onClick={() => setFilter('bathrooms', b)}
                      className={cn(
                        'h-8 px-3 rounded-xl text-xs font-bold border transition',
                        params.get('bathrooms') === b
                          ? 'bg-red-600 text-white border-red-600'
                          : 'bg-slate-50 text-slate-700 border-slate-200 hover:border-red-300',
                      )}
                    >
                      {b || t('search.any', 'Any')}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Area */}
        <div className="border-b border-slate-50 pb-2">
          <SectionHeader id="area" label={t('search.areaRange', 'Area (sq.ft)')} />
          {open('area') && (
            <div className="mt-2 grid grid-cols-2 gap-2">
              <input
                type="number"
                placeholder={t('search.minArea', 'Min')}
                value={params.get('min_area') ?? ''}
                onChange={(e) => setFilter('min_area', e.target.value)}
                className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm focus:border-red-400 focus:outline-none"
              />
              <input
                type="number"
                placeholder={t('search.maxArea', 'Max')}
                value={params.get('max_area') ?? ''}
                onChange={(e) => setFilter('max_area', e.target.value)}
                className="rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-sm focus:border-red-400 focus:outline-none"
              />
            </div>
          )}
        </div>

        {/* Furnishing */}
        <div className="border-b border-slate-50 pb-2">
          <SectionHeader id="furnish" label={t('search.furnishingLabel', 'Furnishing')} />
          {open('furnish') && (
            <div className="mt-2 space-y-1.5">
              {[
                { v: '', l: t('search.any', 'Any') },
                { v: 'Unfurnished', l: t('search.unfurnished', 'Unfurnished') },
                { v: 'Semi-Furnished', l: t('search.semiFurnished', 'Semi-Furnished') },
                { v: 'Fully Furnished', l: t('search.fullyFurnished', 'Fully Furnished') },
              ].map(({ v, l }) => (
                <label key={v} className="flex items-center gap-2 text-sm text-slate-700 cursor-pointer">
                  <input
                    type="radio"
                    name="furnishing"
                    value={v}
                    checked={params.get('furnishing') === v || (!params.get('furnishing') && !v)}
                    onChange={() => setFilter('furnishing', v)}
                    className="text-red-600 border-slate-300 focus:ring-red-400"
                  />
                  {l}
                </label>
              ))}
            </div>
          )}
        </div>

        {/* Extras */}
        <div className="pt-2 space-y-2">
          <label className="flex items-center gap-2.5 text-sm font-semibold text-slate-700 cursor-pointer">
            <input
              type="checkbox"
              checked={params.get('luxury') === '1'}
              onChange={(e) => setFilter('luxury', e.target.checked ? '1' : '')}
              className="h-4 w-4 rounded border-slate-300 text-red-600 focus:ring-red-400"
            />
            ✨ {t('search.luxuryOnly', 'Luxury Properties Only')}
          </label>
          <label className="flex items-center gap-2.5 text-sm font-semibold text-slate-700 cursor-pointer">
            <input
              type="checkbox"
              checked={params.get('virtual_tour') === '1'}
              onChange={(e) => setFilter('virtual_tour', e.target.checked ? '1' : '')}
              className="h-4 w-4 rounded border-slate-300 text-red-600 focus:ring-red-400"
            />
            <Camera className="h-3.5 w-3.5 text-emerald-600" /> {t('search.hasVirtualTour', '360° Virtual Tour')}
          </label>
        </div>
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// Main Search Page
// ──────────────────────────────────────────────────────────────
export function SearchPage() {
  const { t } = useLanguageContext();
  const { user } = useAuth();
  const { addToast } = useToast();
  const [params, setParams] = useSearchParams();
  const [showFilters, setShowFilters] = useState(false);
  const [view, setView] = useState<ViewMode>('list');
  const [sort, setSort] = useState<SortOption>('newest');
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [savedIds, setSavedIds] = useState<Set<string>>(new Set());
  const [comparedIds, setComparedIds] = useState<Set<string>>(new Set());
  const page = Math.max(1, Number(params.get('page') ?? '1') || 1);

  const { data: types } = useQuery({
    queryKey: ['ptypes-all'],
    queryFn: async () => {
      const { data } = await supabase.from('property_types').select('id, name, category').order('name');
      return data ?? [];
    },
  });
  const { data: cities } = useQuery({
    queryKey: ['cities-all'],
    queryFn: async () => {
      const { data } = await supabase.from('cities').select('id, name').order('name');
      return data ?? [];
    },
  });
  const { data: localities } = useQuery({
    queryKey: ['localities-all'],
    queryFn: async () => {
      const { data } = await supabase.from('localities').select('id, name, city_id').order('name').limit(200);
      return data ?? [];
    },
  });

  const query = params.get('q') || '';

  const searchSuggestions = useCallback(async (q: string) => {
    if (q.length < 2) {
      setSuggestions([]);
      return;
    }
    const { data } = await supabase.from('properties').select('title').ilike('title', `%${q}%`).limit(6);
    setSuggestions((data ?? []).map((p: { title: string }) => p.title));
  }, []);

  const filters: PropertyFilters = useMemo(() => {
    const typeIdParam = params.get('type_id') || undefined;
    const typeNameParam = params.get('type') || undefined;
    let resolvedTypeId = typeIdParam;
    if (typeNameParam && types) {
      const found = types.find((t2) => t2.name.toLowerCase() === typeNameParam.toLowerCase());
      if (found) resolvedTypeId = found.id;
    }
    return {
      q: params.get('q') || undefined,
      city_id: params.get('city') || undefined,
      purpose: params.get('purpose') || undefined,
      property_type_id: resolvedTypeId,
      min_price: params.get('min_price') ? Number(params.get('min_price')) : undefined,
      max_price: params.get('max_price') ? Number(params.get('max_price')) : undefined,
      bedrooms: params.get('bedrooms') ? Number(params.get('bedrooms')) : undefined,
      bathrooms: params.get('bathrooms') ? Number(params.get('bathrooms')) : undefined,
      min_area: params.get('min_area') ? Number(params.get('min_area')) : undefined,
      max_area: params.get('max_area') ? Number(params.get('max_area')) : undefined,
      furnishing: params.get('furnishing') || undefined,
      facing: params.get('facing') || undefined,
      is_luxury: params.get('luxury') === '1' || undefined,
    };
  }, [params, types]);

  const sortClause = useMemo(() => {
    switch (sort) {
      case 'price_asc':
        return { order: 'price', ascending: true } as const;
      case 'price_desc':
        return { order: 'price', ascending: false } as const;
      case 'popular':
        return { order: 'view_count', ascending: false } as const;
      case 'area':
        return { order: 'built_up_area', ascending: false } as const;
      default:
        return { order: 'published_at', ascending: false } as const;
    }
  }, [sort]);

  const { data, isLoading } = useQuery({
    queryKey: ['search', filters, sort, page],
    queryFn: async () => {
      let q = supabase
        .from('properties')
        .select('*, cities!inner(name), localities(name), property_types(name)', { count: 'estimated' })
        .eq('status', 'published');
      if (filters.purpose) q = q.eq('purpose', filters.purpose);
      if (filters.city_id) q = q.eq('city_id', filters.city_id);
      if (filters.property_type_id) q = q.eq('property_type_id', filters.property_type_id);
      if (filters.min_price != null) q = q.gte('price', filters.min_price);
      if (filters.max_price != null) q = q.lte('price', filters.max_price);
      if (filters.bedrooms != null) q = q.eq('bedrooms', filters.bedrooms);
      if (filters.bathrooms != null) q = q.eq('bathrooms', filters.bathrooms);
      if (filters.min_area != null) q = q.gte('built_up_area', filters.min_area);
      if (filters.max_area != null) q = q.lte('built_up_area', filters.max_area);
      if (filters.furnishing) q = q.eq('furnishing', filters.furnishing);
      if (filters.facing) q = q.eq('facing', filters.facing);
      if (filters.is_luxury) q = q.eq('is_luxury', true);
      if (filters.q)
        q = q.or(`title.ilike.%${filters.q}%,description.ilike.%${filters.q}%,address.ilike.%${filters.q}%`);
      q = q
        .order(sortClause.order, { ascending: sortClause.ascending })
        .range((page - 1) * PAGE_SIZE, page * PAGE_SIZE - 1);
      const { data, error, count } = await q;
      if (error) throw error;
      const mapped = (data ?? []).map((p) => {
        const r = p as unknown as {
          cities?: { name: string };
          localities?: { name: string };
          property_types?: { name: string };
        };
        return {
          ...p,
          city_name: r.cities?.name ?? null,
          locality_name: r.localities?.name ?? null,
          property_type_name: r.property_types?.name ?? null,
        };
      });
      return { data: mapped, count: count ?? 0 };
    },
  });

  const setFilter = (key: string, value: string) => {
    const next = new URLSearchParams(params);
    if (value) next.set(key, value);
    else next.delete(key);
    next.delete('page');
    setParams(next);
  };

  const goToPage = (p: number) => {
    const next = new URLSearchParams(params);
    next.set('page', String(p));
    setParams(next);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const clearAll = () => setParams(new URLSearchParams());
  const activeCount = Array.from(params.keys()).filter((k) => !['q', 'page'].includes(k)).length;
  const totalPages = data?.count ? Math.ceil(data.count / PAGE_SIZE) : 1;

  const toggleSave = (id: string) => {
    setSavedIds((prev) => {
      const n = new Set(prev);
      n.has(id) ? n.delete(id) : n.add(id);
      return n;
    });
    addToast('success', savedIds.has(id) ? 'Removed from saved' : 'Saved!');
  };
  const toggleCompare = (id: string) => {
    setComparedIds((prev) => {
      const n = new Set(prev);
      n.has(id) ? n.delete(id) : n.add(id);
      return n;
    });
  };

  const pageTitle =
    filters.purpose === 'Rent'
      ? t('search.forRentTitle', 'Properties for Rent')
      : filters.purpose === 'Sale'
        ? t('search.forSaleTitle', 'Properties for Sale')
        : t('search.title', 'Search Properties');

  return (
    <div className="min-h-screen bg-slate-50">
      {/* ── TOP TOOLBAR ── */}
      <div className="sticky top-0 z-40 bg-white/95 backdrop-blur-xl border-b border-slate-100 shadow-sm">
        <div className="container-page py-3">
          <div className="flex flex-wrap items-center gap-3">
            {/* Search Input */}
            <div className="relative flex-1 min-w-[200px] max-w-md">
              <Search className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <input
                value={query}
                onChange={(e) => {
                  setFilter('q', e.target.value);
                  searchSuggestions(e.target.value);
                }}
                placeholder={t('search.placeholder', 'City, locality, project or builder...')}
                className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2.5 pl-10 pr-4 text-sm text-slate-800 placeholder:text-slate-400 focus:border-red-400 focus:bg-white focus:outline-none focus:ring-2 focus:ring-red-100"
              />
              <AnimatePresence>
                {suggestions.length > 0 && (
                  <motion.div
                    initial={{ opacity: 0, y: -4 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0 }}
                    className="absolute z-50 mt-1 w-full rounded-xl border border-slate-100 bg-white shadow-xl overflow-hidden"
                  >
                    {suggestions.map((s) => (
                      <button
                        key={s}
                        onClick={() => {
                          setFilter('q', s);
                          setSuggestions([]);
                        }}
                        className="flex w-full items-center gap-2 px-4 py-2.5 text-sm hover:bg-red-50 hover:text-red-700 transition"
                      >
                        <Search className="h-3.5 w-3.5 text-slate-400" /> {s}
                      </button>
                    ))}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            {/* Results count */}
            <div className="hidden sm:flex items-center gap-1.5 text-sm text-slate-600">
              <span className="font-bold text-slate-900">{formatNumber(data?.count ?? 0)}</span>
              <span>{t('search.results', 'results')}</span>
              {filters.q && (
                <span className="text-slate-400">
                  for "<span className="font-semibold text-slate-700">{filters.q}</span>"
                </span>
              )}
            </div>

            <div className="flex items-center gap-2 ml-auto flex-wrap">
              {/* Sort */}
              <div className="flex items-center gap-1.5 rounded-xl border border-slate-200 bg-white px-3 py-2">
                <SortDesc className="h-3.5 w-3.5 text-slate-400 shrink-0" />
                <select
                  value={sort}
                  onChange={(e) => setSort(e.target.value as SortOption)}
                  className="text-sm font-semibold text-slate-700 bg-transparent focus:outline-none cursor-pointer"
                >
                  <option value="newest">{t('search.newest', 'Newest')}</option>
                  <option value="price_asc">{t('search.priceLowHigh', 'Price ↑')}</option>
                  <option value="price_desc">{t('search.priceHighLow', 'Price ↓')}</option>
                  <option value="popular">{t('search.mostPopular', 'Popular')}</option>
                  <option value="area">{t('search.largestArea', 'Largest Area')}</option>
                </select>
              </div>

              {/* View toggle */}
              <div className="flex items-center gap-0.5 rounded-xl border border-slate-200 bg-white p-1">
                {(
                  [
                    { v: 'list', Icon: Rows3, label: 'List' },
                    { v: 'grid', Icon: LayoutGrid, label: 'Grid' },
                    { v: 'map', Icon: Map, label: 'Map' },
                  ] as const
                ).map(({ v, Icon, label }) => (
                  <button
                    key={v}
                    onClick={() => setView(v)}
                    className={cn(
                      'flex items-center gap-1 rounded-lg px-3 py-1.5 text-xs font-bold transition',
                      view === v ? 'bg-red-600 text-white shadow' : 'text-slate-500 hover:bg-slate-100',
                    )}
                    title={label}
                  >
                    <Icon className="h-3.5 w-3.5" />
                    <span className="hidden sm:inline">{label}</span>
                  </button>
                ))}
              </div>

              {/* Mobile filter toggle */}
              <button
                onClick={() => setShowFilters((v) => !v)}
                className={cn(
                  'flex items-center gap-1.5 rounded-xl border px-3 py-2 text-sm font-bold transition lg:hidden',
                  showFilters ? 'border-red-400 bg-red-50 text-red-600' : 'border-slate-200 bg-white text-slate-700',
                )}
              >
                <Filter className="h-4 w-4" />
                {t('search.filtersHeader', 'Filters')}
                {activeCount > 0 && (
                  <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-red-600 text-[10px] text-white font-extrabold">
                    {activeCount}
                  </span>
                )}
              </button>
            </div>
          </div>

          {/* Active filter chips */}
          {activeCount > 0 && (
            <div className="mt-2 flex flex-wrap items-center gap-1.5">
              <span className="text-xs font-semibold text-slate-500">{t('search.activeFilters', 'Active:')}</span>
              {Array.from(params.entries())
                .filter(([k]) => !['q', 'page'].includes(k))
                .map(([k, v]) => (
                  <span
                    key={k}
                    className="flex items-center gap-1 rounded-full bg-red-50 border border-red-200 px-2.5 py-0.5 text-xs font-semibold text-red-700"
                  >
                    {k}: {v}
                    <button onClick={() => setFilter(k, '')} className="ml-0.5 hover:text-red-900">
                      <X className="h-3 w-3" />
                    </button>
                  </span>
                ))}
              <button onClick={clearAll} className="text-xs text-slate-500 hover:text-red-600 font-semibold ml-1">
                {t('search.clearAll', 'Clear all')}
              </button>
            </div>
          )}
        </div>
      </div>

      {/* ── BODY: Sidebar + Results ── */}
      <div className="container-page py-6">
        <div className="flex gap-6">
          {/* Sidebar */}
          <aside className={cn('shrink-0 w-72', showFilters ? 'block' : 'hidden lg:block')}>
            <div className="sticky top-[88px]">
              <FilterSidebar
                params={params}
                setFilter={setFilter}
                clearAll={clearAll}
                activeCount={activeCount}
                types={types ?? []}
                cities={cities ?? []}
                localities={localities ?? []}
              />
            </div>
          </aside>

          {/* Results */}
          <div className="flex-1 min-w-0">
            {/* Results heading */}
            <div className="mb-4 flex items-center justify-between">
              <h1 className="font-display text-xl font-bold text-slate-900">
                {pageTitle}
                {data?.count != null && (
                  <span className="ml-2 text-sm font-normal text-slate-500">
                    ({formatNumber(data.count)} {t('search.results', 'results')})
                  </span>
                )}
              </h1>
            </div>

            {/* Map view */}
            {view === 'map' && data?.data && (
              <div className="mt-4">
                <PropertyMap properties={data.data} />
              </div>
            )}

            {/* List / Grid */}
            {view !== 'map' && (
              <>
                {isLoading ? (
                  <div
                    className={cn(
                      'space-y-4',
                      view === 'grid' && 'grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-5 space-y-0',
                    )}
                  >
                    {Array.from({ length: view === 'grid' ? 6 : 4 }).map((_, i) =>
                      view === 'list' ? (
                        <ListSkeleton key={i} />
                      ) : (
                        <div key={i} className="h-72 rounded-2xl bg-slate-200 animate-pulse" />
                      ),
                    )}
                  </div>
                ) : data && data.data.length > 0 ? (
                  <>
                    <div
                      className={cn(
                        view === 'grid' ? 'grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-5' : 'space-y-4',
                      )}
                    >
                      {data.data.map((p) =>
                        view === 'list' ? (
                          <HorizontalCard
                            key={p.id}
                            property={p as any}
                            onSave={toggleSave}
                            onCompare={toggleCompare}
                            saved={savedIds.has(p.id)}
                            compared={comparedIds.has(p.id)}
                          />
                        ) : (
                          <GridCard key={p.id} property={p as any} />
                        ),
                      )}
                    </div>

                    {/* Pagination */}
                    {totalPages > 1 && (
                      <div className="mt-8 flex items-center justify-center gap-1.5 flex-wrap">
                        <button
                          disabled={page <= 1}
                          onClick={() => goToPage(page - 1)}
                          className="flex items-center gap-1 rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-700 hover:bg-red-50 hover:border-red-300 hover:text-red-600 disabled:opacity-40 disabled:cursor-not-allowed transition"
                        >
                          <ChevronLeft className="h-4 w-4" /> {t('common.back', 'Prev')}
                        </button>
                        {Array.from({ length: Math.min(totalPages, 7) }).map((_, i) => {
                          const pg = i + 1;
                          return (
                            <button
                              key={pg}
                              onClick={() => goToPage(pg)}
                              className={cn(
                                'h-9 w-9 rounded-xl text-sm font-bold transition border',
                                page === pg
                                  ? 'bg-red-600 text-white border-red-600 shadow-md shadow-red-600/20'
                                  : 'bg-white text-slate-600 border-slate-200 hover:border-red-300 hover:text-red-600',
                              )}
                            >
                              {pg}
                            </button>
                          );
                        })}
                        {totalPages > 7 && <span className="px-2 text-slate-400 font-bold">…</span>}
                        <button
                          disabled={page >= totalPages}
                          onClick={() => goToPage(page + 1)}
                          className="flex items-center gap-1 rounded-xl border border-slate-200 bg-white px-3 py-2 text-sm font-semibold text-slate-700 hover:bg-red-50 hover:border-red-300 hover:text-red-600 disabled:opacity-40 disabled:cursor-not-allowed transition"
                        >
                          {t('common.next', 'Next')} <ChevronRight className="h-4 w-4" />
                        </button>
                      </div>
                    )}
                  </>
                ) : (
                  <div className="flex flex-col items-center justify-center rounded-2xl border-2 border-dashed border-slate-200 bg-white py-20 gap-4">
                    <MapPin className="h-12 w-12 text-slate-300" />
                    <p className="font-bold text-slate-700 text-lg">
                      {t('search.notFoundTitle', 'No properties found')}
                    </p>
                    <p className="text-sm text-slate-500">
                      {t('search.notFoundDesc', 'Try adjusting your filters or searching in a different city.')}
                    </p>
                    <button
                      onClick={clearAll}
                      className="rounded-xl border border-red-200 bg-red-50 text-red-600 px-5 py-2 text-sm font-bold hover:bg-red-100 transition"
                    >
                      {t('search.clearFilters', 'Clear All Filters')}
                    </button>
                  </div>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// Category Page (Buy / Rent / Commercial / Plots / Luxury)
// ──────────────────────────────────────────────────────────────
export function CategoryPage({ category }: { category: 'buy' | 'rent' | 'commercial' | 'plots' | 'luxury' }) {
  const { t } = useLanguageContext();
  const [params] = useSearchParams();
  const purpose = category === 'rent' ? 'Rent' : category === 'buy' ? 'Sale' : undefined;
  const isLuxury = category === 'luxury';
  const page = Math.max(1, Number(params.get('page') ?? '1') || 1);

  const { data: types } = useQuery({
    queryKey: ['ptypes-all'],
    queryFn: async () => {
      const { data } = await supabase.from('property_types').select('id, name, category').order('name');
      return data ?? [];
    },
  });

  const typeFilter = useMemo(() => {
    if (!types) return undefined;
    if (category === 'commercial') return types.filter((t2) => t2.category === 'Commercial').map((t2) => t2.id);
    if (category === 'plots') return types.filter((t2) => t2.category === 'Plot').map((t2) => t2.id);
    return undefined;
  }, [types, category]);

  const filters: PropertyFilters = {
    purpose,
    is_luxury: isLuxury || undefined,
    q: params.get('q') || undefined,
    limit: PAGE_SIZE,
    offset: (page - 1) * PAGE_SIZE,
  };

  const { data, isLoading } = useQuery({
    queryKey: ['category', category, filters, page],
    queryFn: async () => {
      let q = supabase
        .from('properties')
        .select('*, cities!inner(name), localities(name), property_types(name)', { count: 'estimated' })
        .eq('status', 'published');
      if (purpose) q = q.eq('purpose', purpose);
      if (isLuxury) q = q.eq('is_luxury', true);
      if (typeFilter && typeFilter.length > 0) q = q.in('property_type_id', typeFilter);
      if (filters.q) q = q.or(`title.ilike.%${filters.q}%,description.ilike.%${filters.q}%`);
      q = q
        .order('is_featured', { ascending: false })
        .order('published_at', { ascending: false })
        .range((page - 1) * PAGE_SIZE, page * PAGE_SIZE - 1);
      const { data, error, count } = await q;
      if (error) throw error;
      const mapped = (data ?? []).map((p) => {
        const r = p as unknown as {
          cities?: { name: string };
          localities?: { name: string };
          property_types?: { name: string };
        };
        return {
          ...p,
          city_name: r.cities?.name ?? null,
          locality_name: r.localities?.name ?? null,
          property_type_name: r.property_types?.name ?? null,
        };
      });
      return { data: mapped, count: count ?? mapped.length };
    },
  });

  const totalPages = data?.count ? Math.ceil(data.count / PAGE_SIZE) : 1;

  const title = {
    buy: t('search.forSaleTitle', 'Properties for Sale'),
    rent: t('search.forRentTitle', 'Properties for Rent'),
    commercial: t('menu.commercialSpaces', 'Commercial Properties'),
    plots: t('menu.plotsTitle', 'Plots & Land'),
    luxury: t('home.signatureCollection', 'Luxury Homes'),
  }[category];

  return (
    <div className="min-h-screen bg-slate-50">
      <div className="container-page py-8">
        <div className="mb-6">
          <h1 className="font-display text-2xl font-bold text-slate-900">{title}</h1>
          <p className="mt-1 text-sm text-slate-500">
            <span className="font-bold text-slate-800">{formatNumber(data?.count ?? 0)}</span>{' '}
            {t('property.propertiesCount', 'properties')}
          </p>
        </div>
        {isLoading ? (
          <div className="space-y-4">
            {Array.from({ length: 4 }).map((_, i) => (
              <ListSkeleton key={i} />
            ))}
          </div>
        ) : data && data.data.length > 0 ? (
          <div className="space-y-4">
            {data.data.map((p) => (
              <HorizontalCard key={p.id} property={p as any} />
            ))}
            {totalPages > 1 && (
              <div className="mt-8 flex items-center justify-center gap-1.5">
                {Array.from({ length: Math.min(totalPages, 7) }).map((_, i) => {
                  const pg = i + 1;
                  return (
                    <button
                      key={pg}
                      onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                      className={cn(
                        'h-9 w-9 rounded-xl text-sm font-bold border transition',
                        page === pg
                          ? 'bg-red-600 text-white border-red-600'
                          : 'bg-white text-slate-600 border-slate-200 hover:border-red-300',
                      )}
                    >
                      {pg}
                    </button>
                  );
                })}
              </div>
            )}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center rounded-2xl border-2 border-dashed border-slate-200 bg-white py-20 gap-4">
            <Home className="h-12 w-12 text-slate-300" />
            <p className="font-bold text-slate-700">
              {t('search.noCategoryTitle', 'No properties in this category yet')}
            </p>
            <p className="text-sm text-slate-500">
              {t('search.noCategoryDesc', 'Check back soon or browse all properties.')}
            </p>
            <Link to="/search" className="rounded-xl bg-red-600 text-white px-5 py-2 text-sm font-bold">
              {t('search.browseAll', 'Browse All')}
            </Link>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Link, useParams } from 'react-router-dom';
import {
  Calendar,
  ArrowLeft,
  Tag,
  Search as SearchIcon,
  MessageSquare,
  User,
  ChevronRight,
  MapPin,
  Phone,
  Mail,
  Clock,
  Send,
  Home,
} from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { useRealtimeCount } from '../../lib/realtime';
import { useLanguageContext } from '../../lib/i18n/language-context';
import { Card, EmptyState, Button, Skeleton, Input, Textarea } from '../../components/ui';
import { cn } from '../../lib/utils';

export function BlogListPage() {
  const { t } = useLanguageContext();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('');
  const pageSize = 9;
  const realtimeTick = useRealtimeCount('blogs');

  const { data, isLoading } = useQuery({
    queryKey: ['blogs', page, search, category, realtimeTick],
    queryFn: async () => {
      let q = supabase.from('blogs').select('*', { count: 'estimated' }).eq('published', true);
      if (search) q = q.ilike('title', `%${search}%`);
      if (category) q = q.contains('tags', [category]);
      q = q.order('published_at', { ascending: false }).range((page - 1) * pageSize, page * pageSize - 1);
      const { data, error, count } = await q;
      if (error) throw error;
      return { data: data ?? [], count: count ?? 0 };
    },
  });

  const { data: allTags } = useQuery({
    queryKey: ['blog-tags'],
    queryFn: async () => {
      const { data } = await supabase.from('blogs').select('tags').eq('published', true);
      const tagSet = new Set<string>();
      (data ?? []).forEach((b: { tags: string[] | null }) => b.tags?.forEach((t: string) => tagSet.add(t)));
      return Array.from(tagSet);
    },
  });

  const totalPages = data?.count ? Math.ceil(data.count / pageSize) : 1;

  return (
    <div className="container-page py-12">
      <h1 className="font-display text-3xl font-bold text-navy-900">{t('common.blog', 'RealtyNow Blog')}</h1>
      <p className="mt-2 text-navy-600">{t('blog.subtitle', 'Insights, trends, and guides on real estate.')}</p>
      <div className="mt-6 flex flex-wrap items-center gap-3">
        <div className="relative flex-1 min-w-[200px] max-w-md">
          <SearchIcon className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-navy-400" />
          <input
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setPage(1);
            }}
            placeholder={t('blog.searchPlaceholder', 'Search articles...')}
            className="input pl-9"
          />
        </div>
        {allTags && allTags.length > 0 && (
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setCategory('')}
              className={cn(
                'rounded-full px-3 py-1 text-xs font-medium border transition',
                !category ? 'bg-navy-800 text-white' : 'border-navy-200 text-navy-600 hover:bg-navy-50',
              )}
            >
              {t('blog.allCategories', 'All')}
            </button>
            {allTags.map((tag) => (
              <button
                key={tag}
                onClick={() => setCategory(tag === category ? '' : tag)}
                className={cn(
                  'rounded-full px-3 py-1 text-xs font-medium border transition',
                  category === tag ? 'bg-navy-800 text-white' : 'border-navy-200 text-navy-600 hover:bg-navy-50',
                )}
              >
                {tag}
              </button>
            ))}
          </div>
        )}
      </div>

      {isLoading ? (
        <div className="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <Skeleton key={i} className="h-64 rounded-2xl" />
          ))}
        </div>
      ) : data && data.data.length > 0 ? (
        <>
          <div className="mt-8 grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {data.data.map((b) => (
              <Card key={b.id} className="group overflow-hidden p-0 transition hover:shadow-lg">
                <Link to={`/blog/${b.slug ?? b.id}`}>
                  <div className="aspect-[16/9] overflow-hidden bg-navy-100">
                    <img
                      src={b.cover_image ?? 'https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg'}
                      alt={b.title}
                      className="h-full w-full object-cover transition duration-300 group-hover:scale-105"
                    />
                  </div>
                  <div className="p-5">
                    {b.tags && b.tags.length > 0 && (
                      <span className="text-xs font-semibold text-primary-600 uppercase tracking-wider">
                        {b.tags[0]}
                      </span>
                    )}
                    <h2 className="mt-2 font-display text-lg font-bold text-navy-900 group-hover:text-primary-600 transition">
                      {b.title}
                    </h2>
                    <p className="mt-2 text-xs text-navy-500 line-clamp-2">{b.excerpt}</p>
                    <div className="mt-4 flex items-center gap-4 text-xs text-navy-400">
                      <span className="flex items-center gap-1">
                        <Calendar className="h-3.5 w-3.5" />{' '}
                        {b.published_at ? new Date(b.published_at).toLocaleDateString('en-IN') : 'Recently'}
                      </span>
                      <span className="flex items-center gap-1">
                        <User className="h-3.5 w-3.5" /> {b.author_name ?? 'Editorial Team'}
                      </span>
                    </div>
                  </div>
                </Link>
              </Card>
            ))}
          </div>

          {totalPages > 1 && (
            <div className="mt-12 flex justify-center gap-2">
              <Button variant="secondary" size="sm" disabled={page <= 1} onClick={() => setPage((p) => p - 1)}>
                {t('common.prev', 'Prev')}
              </Button>
              {Array.from({ length: totalPages }).map((_, i) => (
                <button
                  key={i}
                  onClick={() => setPage(i + 1)}
                  className={cn(
                    'h-8 w-8 rounded-lg text-xs font-semibold transition',
                    page === i + 1 ? 'bg-navy-800 text-white' : 'text-navy-600 hover:bg-navy-100',
                  )}
                >
                  {i + 1}
                </button>
              ))}
              <Button variant="secondary" size="sm" disabled={page >= totalPages} onClick={() => setPage((p) => p + 1)}>
                {t('common.next', 'Next')}
              </Button>
            </div>
          )}
        </>
      ) : (
        <Card className="mt-8 py-16">
          <EmptyState
            title={t('blog.noArticles', 'No articles found')}
            description={t('blog.noArticlesDesc', 'Try searching for something else or reset your filter.')}
          />
        </Card>
      )}
    </div>
  );
}

export function BlogDetailPage() {
  const { t } = useLanguageContext();
  const { id } = useParams();
  const { data: blog, isLoading } = useQuery({
    queryKey: ['blog-detail', id],
    queryFn: async () => {
      const { data } = await supabase.from('blogs').select('*').or(`id.eq.${id},slug.eq.${id}`).maybeSingle();
      return data;
    },
    enabled: !!id,
  });

  if (isLoading)
    return (
      <div className="container-page py-16 max-w-3xl">
        <Skeleton className="h-8 w-3/4 mb-4" />
        <Skeleton className="h-96 rounded-2xl" />
      </div>
    );
  if (!blog)
    return (
      <div className="container-page py-16">
        <EmptyState
          title={t('blog.notFound', 'Article not found')}
          action={
            <Link to="/blog">
              <Button variant="secondary">{t('blog.backToBlog', 'Back to Blog')}</Button>
            </Link>
          }
        />
      </div>
    );

  return (
    <div className="container-page py-12 max-w-3xl">
      <Link
        to="/blog"
        className="inline-flex items-center gap-1.5 text-xs font-semibold text-navy-500 hover:text-navy-900 mb-6 transition"
      >
        <ArrowLeft className="h-4 w-4" /> {t('blog.backToArticles', 'Back to all articles')}
      </Link>
      {blog.tags && blog.tags.length > 0 && (
        <span className="inline-block rounded-full bg-primary-50 px-3 py-1 text-xs font-semibold text-primary-600 uppercase tracking-wider mb-3">
          {blog.tags[0]}
        </span>
      )}
      <h1 className="font-display text-3xl font-extrabold text-navy-900 sm:text-4xl leading-tight">{blog.title}</h1>
      <div className="mt-4 flex items-center gap-4 text-xs text-navy-500 border-b border-navy-100 pb-6">
        <span className="flex items-center gap-1.5 font-medium text-navy-700">
          <User className="h-4 w-4 text-navy-400" /> {blog.author_name ?? 'Editorial Team'}
        </span>
        <span className="flex items-center gap-1.5">
          <Calendar className="h-4 w-4 text-navy-400" />{' '}
          {blog.published_at
            ? new Date(blog.published_at).toLocaleDateString('en-IN', {
                day: 'numeric',
                month: 'long',
                year: 'numeric',
              })
            : 'Recently'}
        </span>
      </div>
      {blog.cover_image && (
        <div className="mt-6 aspect-[16/9] overflow-hidden rounded-2xl bg-navy-100">
          <img src={blog.cover_image} alt={blog.title} className="h-full w-full object-cover" />
        </div>
      )}
      <div className="mt-8 space-y-4 text-navy-800 leading-relaxed whitespace-pre-line text-base">{blog.content}</div>
    </div>
  );
}

export function FaqPage() {
  const { t } = useLanguageContext();
  const [search, setSearch] = useState('');
  const [openId, setOpenId] = useState<string | null>(null);
  const realtimeTick = useRealtimeCount('faqs');

  const { data, isLoading } = useQuery({
    queryKey: ['faqs', realtimeTick],
    queryFn: async () => {
      const { data } = await supabase
        .from('faqs')
        .select('*')
        .eq('is_active', true)
        .order('sort_order', { ascending: true })
        .order('created_at', { ascending: false });
      return data ?? [];
    },
  });

  const categories = Array.from(
    new Set((data ?? []).map((f: { category: string | null }) => f.category).filter(Boolean)),
  );
  const filtered = data?.filter(
    (f: { question: string; answer: string }) =>
      !search ||
      f.question.toLowerCase().includes(search.toLowerCase()) ||
      f.answer.toLowerCase().includes(search.toLowerCase()),
  );

  return (
    <div className="container-page py-12 max-w-3xl">
      <h1 className="font-display text-3xl font-bold text-navy-900">
        {t('home.faqTitle', 'Frequently Asked Questions')}
      </h1>
      <div className="mt-4">
        <div className="relative">
          <SearchIcon className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-navy-400" />
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={t('faq.searchPlaceholder', 'Search FAQs...')}
            className="input pl-9"
          />
        </div>
      </div>
      {categories.length > 1 && (
        <div className="mt-4 flex flex-wrap gap-2">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSearch(cat || '')}
              className="rounded-full border border-navy-200 px-3 py-1 text-xs font-medium text-navy-600 hover:bg-navy-50"
            >
              {cat}
            </button>
          ))}
        </div>
      )}
      <div className="mt-6 space-y-3">
        {isLoading
          ? Array.from({ length: 4 }).map((_, i) => <Skeleton key={i} className="h-20" />)
          : filtered?.map((f: { id: string; question: string; answer: string }) => (
              <Card key={f.id} className="p-0 overflow-hidden">
                <button
                  onClick={() => setOpenId(openId === f.id ? null : f.id)}
                  className="flex w-full items-center justify-between p-5 text-left"
                >
                  <p className="font-semibold text-navy-900">{f.question}</p>
                  <ChevronRight className={cn('h-4 w-4 text-navy-400 transition', openId === f.id && 'rotate-90')} />
                </button>
                {openId === f.id && <div className="px-5 pb-5 text-sm text-navy-600">{f.answer}</div>}
              </Card>
            ))}
      </div>
    </div>
  );
}

